## Arquivo 2: `src/data/books.js`

```javascript
/**
 * @fileoverview Módulo de dados em memória para a API de livros.
 *
 * Este arquivo contém toda a lógica de persistência dos livros, utilizando
 * um array simples como storage. A escolha por armazenamento em memória
 * (em vez de banco de dados) é intencional para este exemplo educacional:
 *   - Elimina complexidade externa (sem instalação de DB)
 *   - Permite focar nos conceitos de REST, rotas e middleware
 *   - Facilita a compreensão do fluxo de dados request → response
 *
 * Em produção, este módulo seria substituído por um repositório que
 * interage com MongoDB, PostgreSQL, etc. A interface (funções CRUD)
 * permaneceria a mesma, demonstrando o padrão Repository.
 */

// ============================================================================
// ESTRUTURA DE DADOS: Por que Array + Objetos?
// ============================================================================
//
// Escolhemos um ARRAY de objetos porque:
//   1. ORDENAÇÃO PRESERVADA: Arrays mantêm a ordem de inserção, o que é útil
//      para listar livros na sequência em que foram criados.
//   2. SIMPLICIDADE: Para um exemplo educacional, arrays são mais intuitivos
//      do que Maps ou objetos complexos.
//   3. FACILIDADE DE FILTRAGEM: Métodos nativos como filter(), find(), etc.,
//      tornam a implementação de filtragem trivial.
//   4. TRANSIÇÃO PARA PRODUÇÃO: A mesma estrutura pode ser mapeada facilmente
//      para documentos em um banco NoSQL (MongoDB) ou linhas em SQL.
//
// Cada livro possui a seguinte forma (schema):
//   {
//     id: number,          // Identificador único auto-incrementado
//     title: string,       // Título do livro (obrigatório)
//     author: string,      // Autor do livro (obrigatório)
//     year: number,        // Ano de publicação (obrigatório)
//     genre: string,       // Gênero literário (opcional)
//     createdAt: string,   // Timestamp ISO da criação
//     updatedAt: string    // Timestamp ISO da última atualização
//   }

/**
 * Array principal que armazena todos os livros em memória.
 * @type {Array<{id: number, title: string, author: string, year: number, genre?: string, createdAt: string, updatedAt: string}>}
 */
const books = [];

/**
 * Contador auto-incremento para geração de IDs únicos.
 *
 * Usamos um contador simples em vez de UUIDs porque:
 *   - IDs numéricos são mais legíveis e fáceis de testar
 *   - Evita colisões sem necessidade de bibliotecas externas
 *   - Em produção, bancos relacionais fazem auto-incremento nativamente
 *
 * @type {number}
 */
let nextId = 1;

// ============================================================================
// FUNÇÕES CRUD (Create, Read, Update, Delete)
// ============================================================================

/**
 * Recupera todos os livros do storage em memória.
 *
 * Esta função retorna uma cópia rasa (shallow copy) do array para evitar
 * mutações acidentais externas ao módulo. Em JavaScript, arrays são
 * passados por referência, então [...books] cria um novo array com os
 * mesmos elementos — suficiente para nosso caso pois os objetos livro
 * não serão substituídos, apenas atualizados internamente.
 *
 * @function getAllBooks
 * @returns {Array<{id: number, title: string, author: string, year: number, genre?: string, createdAt: string, updatedAt: string}>}
 *   Lista completa de livros.
 *
 * @example
 * // curl -X GET http://localhost:3000/books
 * const allBooks = getAllBooks();
 */
function getAllBooks() {
  return [...books];
}

/**
 * Recupera um livro específico pelo seu ID numérico.
 *
 * Utilizamos o método Array.prototype.find() que retorna o PRIMEIRO elemento
 * que satisfaz a condição de busca, ou undefined se nenhum for encontrado.
 * Isso é mais eficiente que filter().slice(0, 1) pois para de buscar após
 * encontrar o primeiro match — O(n) no pior caso vs O(n) + alocação extra.
 *
 * @function getBookById
 * @param {number} id - O identificador numérico do livro a ser buscado.
 * @returns {{id: number, title: string, author: string, year: number, genre?: string, createdAt: string, updatedAt: string}|undefined}
 *   O livro encontrado ou undefined se não existir.
 *
 * @example
 * // curl -X GET http://localhost:3000/books/1
 * const book = getBookById(1);
 */
function getBookById(id) {
  return books.find((book) => book.id === id);
}

/**
 * Cria um novo livro e o adiciona ao storage.
 *
 * A função gera automaticamente:
 *   - Um ID único usando o contador nextId
 *   - Timestamps de criação e atualização em formato ISO 8601
 *
 * O spread operator (...) é usado para criar uma cópia do objeto recebido,
 * garantindo que mutações futuras no objeto original não afetem o livro
 * armazenado. Isso é uma prática de imutabilidade parcial.
 *
 * @function createBook
 * @param {object} bookData - Dados do novo livro.
 * @param {string} bookData.title - Título do livro (obrigatório).
 * @param {string} bookData.author - Autor do livro (obrigatório).
 * @param {number} bookData.year - Ano de publicação (obrigatório).
 * @param {string} [bookData.genre] - Gênero literário (opcional).
 * @returns {{id: number, title: string, author: string, year: number, genre?: string, createdAt: string, updatedAt: string}}
 *   O livro criado com ID e timestamps gerados automaticamente.
 *
 * @example
 * // curl -X POST http://localhost:3000/books \
 * //    -H "Content-Type: application/json" \
 * //    -d '{"title":"Dom Casmurro","author":"Machado de Assis","year":1899,"genre":"Romance"}'
 * const newBook = createBook({ title: "Dom Casmurro", author: "Machado de Assis", year: 1899, genre: "Romance" });
 */
function createBook(bookData) {
  const now = new Date().toISOString();

  const newBook = {
    id: nextId++, // Incrementa APÓS a atribuição (pós-incremento)
    title: bookData.title,
    author: bookData.author,
    year: bookData.year,
    genre: bookData.genre || null, // Garante que genre seja null se não fornecido
    createdAt: now,
    updatedAt: now,
  };

  books.push(newBook); // O(n) — adição ao final do array
  return newBook;
}

/**
 * Atualiza um livro existente pelo seu ID.
 *
 * A função segue o padrão de atualização parcial (partial update):
 *   - Se o campo for fornecido no payload, ele é atualizado
 *   - Se não for fornecido, o valor original é mantido
 *   - O timestamp updatedAt é sempre atualizado para refletir a mudança
 *
 * Esta abordagem é mais flexível que atualização completa (full update),
 * pois permite modificar apenas campos específicos sem precisar reenviar
 * todos os dados do livro a cada requisição.
 *
 * @function updateBook
 * @param {number} id - O identificador do livro a ser atualizado.
 * @param {object} updates - Campos a serem atualizados.
 * @returns {{id: number, title: string, author: string, year: number, genre?: string, createdAt: string, updatedAt: string}|null}
 *   O livro atualizado ou null se o ID não existir.
 *
 * @example
 * // curl -X PUT http://localhost:3000/books/1 \
 * //    -H "Content-Type: application/json" \
 * //    -d '{"title":"Novo Título","year":1900}'
 * const updated = updateBook(1, { title: "Novo Título", year: 1900 });
 */
function updateBook(id, updates) {
  const bookIndex = books.findIndex((book) => book.id === id);

  if (bookIndex === -1) {
    return null; // Livro não encontrado
  }

  // Atualiza apenas os campos fornecidos (partial update)
  if (updates.title !== undefined) books[bookIndex].title = updates.title;
  if (updates.author !== undefined) books[bookIndex].author = updates.author;
  if (updates.year !== undefined) books[bookIndex].year = updates.year;
  if (updates.genre !== undefined) books[bookIndex].genre = updates.genre;

  // Sempre atualiza o timestamp de modificação
  books[bookIndex].updatedAt = new Date().toISOString();

  return { ...books[bookIndex] }; // Retorna cópia para evitar referência direta
}

/**
 * Exclui um livro do storage pelo seu ID.
 *
 * Utilizamos findIndex() + splice() em vez de filter() porque:
 *   - splice() modifica o array original in-place, economizando memória
 *   - Para arrays pequenos (como neste exemplo educacional), a diferença
 *     de performance é insignificante
 *   - Em arrays grandes, filter() criaria um novo array completo, enquanto
 *     splice() apenas remove os elementos indesejados
 *
 * @function deleteBook
 * @param {number} id - O identificador do livro a ser excluído.
 * @returns {boolean} true se o livro foi encontrado e removido, false caso contrário.
 *
 * @example
 * // curl -X DELETE http://localhost:3000/books/1
 * const removed = deleteBook(1);
 */
function deleteBook(id) {
  const bookIndex = books.findIndex((book) => book.id === id);

  if (bookIndex === -1) {
    return false; // Livro não encontrado
  }

  books.splice(bookIndex, 1); // Remove 1 elemento na posição encontrada
  return true;
}

/**
 * Calcula estatísticas agregadas sobre o catálogo de livros.
 *
 * Esta função demonstra operações de redução (reduce) e contagem que seriam
 * comuns em relatórios e dashboards. As estatísticas retornadas incluem:
 *   - totalBooks: quantidade total de livros
 *   - totalAuthors: quantidade de autores únicos
 *   - avgYear: média dos anos de publicação
 *   - booksByGenre: distribuição de livros por gênero
 *
 * @function getStats
 * @returns {{totalBooks: number, totalAuthors: number, avgYear: number|null, booksByGenre: Object}}
 *   Objeto contendo as estatísticas calculadas.
 *
 * @example
 * // curl -X GET http://localhost:3000/stats
 * const stats = getStats();
 */
function getStats() {
  const totalBooks = books.length;

  // Set garante autores únicos — O(n) para construir, O(1) para lookup futuro
  const uniqueAuthors = new Set(books.map((book) => book.author)).size;

  // Média dos anos de publicação — null se não houver livros (evita divisão por zero)
  const avgYear =
    totalBooks > 0
      ? books.reduce((sum, book) => sum + book.year, 0) / totalBooks
      : null;

  // Distribuição por gênero usando reduce para acumulação eficiente
  const booksByGenre = books.reduce((acc, book) => {
    const genre = book.genre || "Sem gênero"; // Agrupa livros sem gênero nesta categoria
    acc[genre] = (acc[genre] || 0) + 1;
    return acc;
  }, {});

  return {
    totalBooks,
    totalAuthors,
    avgYear: avgYear ? Math.round(avgYear * 100) / 100 : null, // Arredonda para 2 casas decimais
    booksByGenre,
  };
}

// ============================================================================
// EXPORTAÇÃO DOS MÓDULOS (Padrão CommonJS)
// ============================================================================
//
// Usamos module.exports em vez de export default porque:
//   - Node.js usa CommonJS nativamente sem configuração adicional
//   - É mais amplamente suportado por ferramentas do ecossistema npm
//   - Permite named exports múltiplos, facilitando a importação seletiva

module.exports = {
  getAllBooks,
  getBookById,
  createBook,
  updateBook,
  deleteBook,
  getStats,
};
```

