## Arquivo 3: `src/middleware/errorHandler.js`

```javascript
/**
 * @fileoverview Middleware de tratamento de erros para a API de livros.
 *
 * Este módulo implementa três componentes principais:
 *   1. Classes de erro personalizadas que estendem Error nativo
 *   2. Middleware de validação de entrada (request body/params)
 *   3. Middleware global de tratamento de erros do Express
 *
 * ============================================================================
 * POR QUE CLASSES DE ERRO PERSONALIZADAS?
 * ============================================================================
 *
 * JavaScript possui a classe Error nativa, mas ela não carrega informações
 * contextuais suficientes para APIs REST. Classes personalizadas permitem:
 *   - Incluir código de status HTTP como propriedade (400, 404, etc.)
 *   - Adicionar campos extras como message estruturado e details
 *   - Diferenciar tipos de erro no middleware global com instanceof
 *   - Manter stack trace completo para debugging em desenvolvimento
 *
 * ============================================================================
 * POR QUE MIDDLEWARE DE ERROS COM 4 PARÂMETROS?
 * ============================================================================
 *
 * Express identifica middlewares de erro pela assinatura (err, req, res, next).
 * Se um middleware tiver exatamente 4 parâmetros, o roteador do Express o trata
 * como handler de erros e só o invoca quando next(err) é chamado. Isso permite
 * que erros normais sejam tratados normalmente e erros capturados sejam
 * centralizados em um único lugar.
 */

// ============================================================================
// CLASSES DE ERRO PERSONALIZADAS
// ============================================================================

/**
 * Erro genérico para problemas do servidor (500 Internal Server Error).
 *
 * Esta classe é usada quando ocorre uma exceção inesperada que não se enquadra
 * em categorias específicas de cliente. Em produção, o message original deve
 * ser logado internamente mas NÃO exposto ao cliente por segurança.
 *
 * @class InternalServerError
 * @extends Error
 */
class InternalServerError extends Error {
  /**
   * @param {string} [message="Erro interno do servidor"] — Mensagem descritiva do erro.
   */
  constructor(message = "Erro interno do servidor") {
    super(message);
    this.name = "InternalServerError";
    this.statusCode = 500; // Padrão HTTP para erros inesperados do servidor
  }
}

/**
 * Erro para recursos não encontrados (404 Not Found).
 *
 * Usado quando o cliente solicita um recurso que não existe no servidor.
 * A mensagem é personalizada com o tipo de recurso e ID para facilitar
 * o debugging tanto pelo desenvolvedor quanto pelo consumidor da API.
 *
 * @class NotFoundError
 * @extends Error
 */
class NotFoundError extends Error {
  /**
   * @param {string} resource - Nome do recurso (ex: "Livro").
   * @param {number|string} id - Identificador do recurso não encontrado.
   */
  constructor(resource, id) {
    super(`${resource} com ID ${id} não encontrado`);
    this.name = "NotFoundError";
    this.statusCode = 404; // Padrão HTTP para recursos inexistentes
    this.resource = resource;
    this.id = id;
  }
}

/**
 * Erro para dados de entrada inválidos (400 Bad Request).
 *
 * Esta é a classe mais utilizada na API, pois validações de entrada são
 * frequentes. Ela carrega um array de `details` que descreve cada campo
 * inválido, permitindo que o cliente corrija todos os problemas de uma vez.
 *
 * @class ValidationError
 * @extends Error
 */
class ValidationError extends Error {
  /**
   * @param {Array<{field: string, message: string}>} details - Lista de campos inválidos e suas mensagens.
   */
  constructor(details) {
    // Gera uma mensagem resumida a partir dos detalhes
    const summary = details.map((d) => d.message).join("; ");
    super(`Dados de entrada inválidos: ${summary}`);
    this.name = "ValidationError";
    this.statusCode = 400; // Padrão HTTP para requisições malformadas
    this.details = details; // Array estruturado para resposta JSON
  }
}

// ============================================================================
// MIDDLEWARE DE VALIDAÇÃO DE ENTRADA
// ============================================================================

/**
 * Middleware que valida campos obrigatórios no corpo da requisição.
 *
 * Este middleware é aplicado antes dos handlers de rota e verifica se os
 * campos especificados estão presentes e não são strings vazias. Ele usa
 * a técnica de "currying" — a função retorna outra função que recebe (req, res, next).
 *
 * A validação é feita de forma síncrona porque comparações de string/number
 * são operações rápidas que não beneficiam de async/await.
 *
 * @function validateRequiredFields
 * @param {string[]} requiredFields - Array de nomes de campos obrigatórios.
 * @returns {(req: express.Request, res: express.Response, next: express.NextFunction) => void}
 *   Middleware Express que valida os campos e chama next(err) se houver problemas.
 *
 * @example
 * // Uso em uma rota POST /books
 * router.post("/", validateRequiredFields(["title", "author", "year"]), (req, res) => { ... });
 */
function validateRequiredFields(requiredFields) {
  return (req, res, next) => {
    const missing = requiredFields.filter((field) => {
      const value = req.body[field];
      // Considera inválido: undefined, null, string vazia, ou número zero
      return value === undefined || value === null || value === "" || value === 0;
    });

    if (missing.length > 0) {
      // Cria detalhes estruturados para cada campo faltante
      const details = missing.map((field) => ({
        field,
        message: `O campo '${field}' é obrigatório`,
      }));
      // Encadeia o erro para o middleware global de tratamento
      next(new ValidationError(details));
      return;
    }

    next(); // Todos os campos válidos — prossegue para o handler da rota
  };
}

/**
 * Middleware que valida se o parâmetro ID é um número inteiro positivo.
 *
 * Em URLs REST, IDs são tipicamente parte do path (ex: /books/123).
 * O Express captura isso como req.params.id (sempre string). Este middleware
 * converte e valida o valor antes que o handler da rota o utilize.
 *
 * @function validateIdParam
 * @returns {(req: express.Request, res: express.Response, next: express.NextFunction) => void}
 *   Middleware Express que valida o ID e chama next(err) se inválido.
 *
 * @example
 * // Uso em rotas PUT/DELETE /books/:id
 * router.put("/:id", validateIdParam(), (req, res) => { ... });
 */
function validateIdParam() {
  return (req, res, next) => {
    const id = parseInt(req.params.id, 10); // Converte string para número base 10

    // isNaN verifica se a conversão falhou (ex: "/books/abc")
    // !Number.isInteger verifica se não é um número inteiro (ex: "/books/1.5")
    if (isNaN(id) || !Number.isInteger(id) || id < 1) {
      next(new ValidationError([{ field: "id", message: "O ID deve ser um número inteiro positivo" }]));
      return;
    }

    // Armazena o ID validado no objeto req para uso pelo handler
    req.validatedId = id;
    next();
  };
}

// ============================================================================
// MIDDLEWARE GLOBAL DE TRATAMENTO DE ERROS
// ============================================================================

/**
 * Middleware global que captura e formata todos os erros da API.
 *
 * Este é o ÚLTIMO middleware a ser registrado (depois de todas as rotas).
 * Ele intercepta erros passados via next(err) e retorna respostas JSON
 * consistentes, independentemente do tipo de erro.
 *
 * A estrutura de resposta segue o padrão Problem Details (RFC 7807):
 *   { error: { message, statusCode, details? } }
 *
 * Em desenvolvimento, o stack trace completo é incluído para facilitar
 * o debugging. Em produção, apenas a mensagem é exposta por segurança.
 *
 * @function errorHandler
 * @param {Error} err - O erro capturado pelo Express.
 * @param {express.Request} req - Objeto de requisição (para logging).
 * @param {express.Response} res - Objeto de resposta.
 * @param {express.NextFunction} next - Função next (não utilizada aqui).
 *
 * @example
 * // Resposta para erro 404:
 * // { "error": { "message": "Livro com ID 99 não encontrado", "statusCode": 404 } }
 *
 * // Resposta para erro 400:
 * // { "error": { "message": "Dados de entrada inválidos...", "statusCode": 400, "details": [...] } }
 */
function errorHandler(err, req, res, next) {
  // Determina o status HTTP com base no tipo de erro (fallback para 500)
  const statusCode = err.statusCode || 500;

  // Em desenvolvimento, incluímos o stack trace completo
  const isDevelopment = process.env.NODE_ENV !== "production";

  // Constrói a resposta JSON padronizada
  const errorResponse = {
    error: {
      message: err.message,
      statusCode,
      // Inclui detalhes apenas para erros de validação (400)
      ...(err.details ? { details: err.details } : {}),
      // Em desenvolvimento, inclui stack trace para debugging
      ...(isDevelopment && err.stack ? { stack: err.stack } : {}),
    },
  };

  // Log do erro no servidor para fins de monitoramento
  console.error(`[${new Date().toISOString()}] ${err.name}: ${err.message}`);
  if (isDevelopment && err.stack) {
    console.error(err.stack);
  }

  // Envia a resposta JSON com o status apropriado
  res.status(statusCode).json(errorResponse);
}

// ============================================================================
// EXPORTAÇÃO DOS MÓDULOS
// ============================================================================

module.exports = {
  InternalServerError,
  NotFoundError,
  ValidationError,
  validateRequiredFields,
  validateIdParam,
  errorHandler,
};
```

