## Arquivo 4: `src/routes/books.js`

```javascript
/**
 * @fileoverview Rotas REST para o recurso "livros".
 *
 * Este módulo define todas as rotas HTTP relacionadas ao recurso livros,
 * seguindo estritamente as convenções RESTful:
 *
 *   | Método  | Caminho          | Ação                    | Status de Sucesso |
 *   |---------|------------------|-------------------------|-------------------|
 *   | GET     | /books           | Listar todos            | 200 OK            |
 *   | GET     | /books/:id       | Obter um específico     | 200 OK            |
 *   | POST    | /books           | Criar novo              | 201 Created       |
 *   | PUT     | /books/:id       | Atualizar completo      | 200 OK            |
 *   | DELETE  | /books/:id       | Excluir                 | 204 No Content    |
 *   | GET     | /stats           | Estatísticas do catálogo| 200 OK            |
 *
 * ============================================================================
 * POR QUE USAR express.Router()?
 * ============================================================================
 *
 * O Express permite criar "mini-aplicações" chamadas Router que agrupam
 * rotas relacionadas. Vantagens:
 *   - Modularidade: cada recurso tem seu próprio arquivo de rotas
 *   - Reusabilidade: o mesmo router pode ser montado em múltiplos paths
 *   - Middleware específico: middlewares podem ser aplicados a todo um grupo
 *   - Manutenção: facilita encontrar e modificar rotas de um recurso
 *
 * ============================================================================
 * POR QUE ASYNC/AWAIT EM VEZ DE PROMISES/CATCH?
 * ============================================================================
 *
 * async/await torna o código mais legível ao eliminar callbacks aninhados
 * ("callback hell") e chains de .then(). Para este exemplo educacional:
 *   - O código linear é mais fácil de seguir para iniciantes
 *   - Erros são tratados com try/catch, padrão familiar da maioria das linguagens
 *   - Em produção com Express 4.x, async/await funciona perfeitamente
 *     quando o erro é capturado e passado para next(err)
 */

const express = require("express");

// Importa as funções de dados (camada de persistência)
const { getAllBooks, getBookById, createBook, updateBook, deleteBook, getStats } = require("../data/books");

// Importa classes de erro e middlewares de validação
const { NotFoundError, ValidationError, validateRequiredFields, validateIdParam } = require("../middleware/errorHandler");

// Cria um roteador específico para o recurso livros
const router = express.Router();

// ============================================================================
// GET /books — Listar todos os livros (com filtragem opcional)
// ============================================================================

/**
 * Rota: GET /books
 *
 * Retorna uma lista paginada e filtrável de todos os livros.
 *
 * PARÂMETROS DE FILTRAGEM (query string):
 *   - author: filtra por autor (case-insensitive, partial match)
 *   - genre:  filtra por gênero (case-insensitive, partial match)
 *   - search: busca por título OU autor (partial match)
 *   - page:   número da página (padrão: 1)
 *   - limit:  quantidade por página (padrão: 10, máximo: 100)
 *
 * A filtragem é implementada com Array.prototype.filter() que cria um novo
 * array contendo apenas os elementos que satisfazem todas as condições.
 * Isso preserva o array original e permite encadear múltiplos filtros.
 *
 * @route GET /books
 * @access Public
 * @query {string} [author] - Filtra por autor
 * @query {string} [genre] - Filtra por gênero
 * @query {string} [search] - Busca por título ou autor
 * @query {number} [page=1] - Número da página
 * @query {number} [limit=10] - Itens por página
 *
 * @returns {200} Array de livros com metadados de paginação
 * @returns {400} Erro de validação se page/limit forem inválidos
 *
 * @example curl
 *   # Listar todos os livros
 *   curl http://localhost:3000/books
 *
 *   # Filtrar por autor
 *   curl "http://localhost:3000/books?author=machado"
 *
 *   # Buscar e paginar
 *   curl "http://localhost:3000/books?search=dom&page=1&limit=5"
 */
router.get("/books", (req, res) => {
  try {
    // Extrai parâmetros de query com valores padrão
    const { author, genre, search, page = 1, limit = 10 } = req.query;

    // Converte paginação para números e valida limites
    const pageNum = parseInt(page, 10);
    const limitNum = parseInt(limit, 10);

    if (isNaN(pageNum) || pageNum < 1 || isNaN(limitNum) || limitNum < 1 || limitNum > 100) {
      throw new ValidationError([
        { field: "page", message: "page deve ser um número inteiro positivo" },
        { field: "limit", message: "limit deve ser um número entre 1 e 100" },
      ]);
    }

    // Começa com todos os livros e aplica filtros sequencialmente
    let filtered = getAllBooks();

    // Filtro por autor (case-insensitive, partial match)
    if (author) {
      const authorLower = author.toLowerCase();
      filtered = filtered.filter((book) => book.author.toLowerCase().includes(authorLower));
    }

    // Filtro por gênero (case-insensitive, partial match)
    if (genre) {
      const genreLower = genre.toLowerCase();
      filtered = filtered.filter(
        (book) => book.genre && book.genre.toLowerCase().includes(genreLower)
      );
    }

    // Busca por título ou autor (combina ambos os campos)
    if (search) {
      const searchLower = search.toLowerCase();
      filtered = filtered.filter(
        (book) =>
          book.title.toLowerCase().includes(searchLower) ||
          book.author.toLowerCase().includes(searchLower)
      );
    }

    // Calcula índices de paginação
    const total = filtered.length;
    const startIndex = (pageNum - 1) * limitNum;
    const endIndex = startIndex + limitNum;

    // slice() retorna uma cópia do array — não modifica o original
    const paginatedBooks = filtered.slice(startIndex, endIndex);

    // Resposta inclui metadados de paginação para facilitar navegação
    res.json({
      data: paginatedBooks,
      pagination: {
        currentPage: pageNum,
        totalPages: Math.ceil(total / limitNum),
        totalItems: total,
        itemsPerPage: limitNum,
      },
    });
  } catch (err) {
    // Erros de validação já têm statusCode definido — passam direto
    // Erros inesperados são convertidos para InternalServerError
    if (err instanceof ValidationError) {
      throw err;
    }
    throw new ValidationError([{ field: "query", message: "Parâmetros de consulta inválidos" }]);
  }
});

// ============================================================================
// GET /books/:id — Obter livro por ID
// ============================================================================

/**
 * Rota: GET /books/:id
 *
 * Retorna um único livro identificado pelo seu ID numérico.
 *
 * O middleware validateIdParam() é aplicado automaticamente para garantir
 * que o ID seja um número inteiro válido antes de chegar ao handler.
 * Se o ID for inválido, um ValidationError (400) é gerado.
 *
 * @route GET /books/:id
 * @access Public
 * @param {number} id - Identificador numérico do livro
 *
 * @returns {200} Objeto do livro encontrado
 * @returns {400} Erro de validação se o ID for inválido
 * @returns {404} Erro se o livro não existir
 *
 * @example curl
 *   # Obter livro com ID 1
 *   curl http://localhost:3000/books/1
 *
 *   # ID inválido retorna 400
 *   curl http://localhost:3000/books/abc
 */
router.get("/books/:id", validateIdParam(), (req, res) => {
  const book = getBookById(req.validatedId);

  if (!book) {
    // NotFoundError é uma classe personalizada com statusCode = 404
    throw new NotFoundError("Livro", req.validatedId);
  }

  res.json({ data: book });
});

// ============================================================================
// POST /books — Criar novo livro
// ============================================================================

/**
 * Rota: POST /books
 *
 * Cria um novo livro a partir dos dados fornecidos no corpo da requisição.
 *
 * O middleware validateRequiredFields() garante que title, author e year
 * estejam presentes antes que o handler seja executado. Isso separa a
 * responsabilidade de validação do handler, seguindo o princípio de
 *单一 responsabilidade.
 *
 * O timestamp de criação é gerado automaticamente pelo módulo de dados,
 * garantindo consistência temporal mesmo se múltiplas requisições
 * chegarem no mesmo milissegundo (ISO 8601 suporta timestamps até
 * nanosegundos).
 *
 * @route POST /books
 * @access Public
 * @body {string} title - Título do livro (obrigatório)
 * @body {string} author - Autor do livro (obrigatório)
 * @body {number} year - Ano de publicação (obrigatório)
 * @body {string} [genre] - Gênero literário (opcional)
 *
 * @returns {201} Livro criado com ID e timestamps
 * @returns {400} Erro de validação se campos obrigatórios faltarem
 *
 * @example curl
 *   # Criar um livro
 *   curl -X POST http://localhost:3000/books \
 *     -H "Content-Type: application/json" \
 *     -d '{
 *       "title": "Dom Casmurro",
 *       "author": "Machado de Assis",
 *       "year": 1899,
 *       "genre": "Romance"
 *     }'
 *
 *   # Resposta (201 Created):
 *   {
 *     "data": {
 *       "id": 1,
 *       "title": "Dom Casmurro",
 *       "author": "Machado de Assis",
 *       "year": 1899,
 *       "genre": "Romance",
 *       "createdAt": "2024-01-15T10:30:00.000Z",
 *       "updatedAt": "2024-01-15T10:30:00.000Z"
 *     }
 *   }
 */
router.post("/books", validateRequiredFields(["title", "author", "year"]), (req, res) => {
  const book = createBook(req.body);
  // 201 Created indica que um novo recurso foi criado com sucesso
  res.status(201).json({ data: book });
});

// ============================================================================
// PUT /books/:id — Atualizar livro existente
// ============================================================================

/**
 * Rota: PUT /books/:id
 *
 * Atualiza completamente um livro existente. Diferente de PATCH (que faria
 * atualização parcial), PUT espera que o cliente envie TODOS os campos
 * obrigatórios, pois o servidor substituirá o recurso inteiro.
 *
 * No entanto, para este exemplo educacional, implementamos atualização
 * parcial (semelhante a PATCH) para maior flexibilidade — o cliente pode
 * enviar apenas os campos que deseja modificar.
 *
 * @route PUT /books/:id
 * @access Public
 * @param {number} id - Identificador do livro a atualizar
 * @body {string} [title] - Novo título
 * @body {string} [author] - Novo autor
 * @body {number} [year] - Novo ano de publicação
 * @body {string} [genre] - Novo gênero
 *
 * @returns {200} Livro atualizado
 * @returns {400} Erro de validação se o ID for inválido
 * @returns {404} Erro se o livro não existir
 *
 * @example curl
 *   # Atualizar parcialmente um livro
 *   curl -X PUT http://localhost:3000/books/1 \
 *     -H "Content-Type: application/json" \
 *     -d '{"title": "Dom Casmurro (Ed. Comentada)", "year": 1900}'
 *
 *   # Resposta (200 OK):
 *   {
 *     "data": {
 *       "id": 1,
 *       "title": "Dom Casmurro (Ed. Comentada)",
 *       "author": "Machado de Assis",
 *       "year": 1900,
 *       "genre": "Romance",
 *       "createdAt": "2024-01-15T10:30:00.000Z",
 *       "updatedAt": "2024-01-15T10:35:00.000Z"
 *     }
 *   }
 */
router.put("/books/:id", validateIdParam(), (req, res) => {
  const updatedBook = updateBook(req.validatedId, req.body);

  if (!updatedBook) {
    throw new NotFoundError("Livro", req.validatedId);
  }

  res.json({ data: updatedBook });
});

// ============================================================================
// DELETE /books/:id — Excluir livro
// ============================================================================

/**
 * Rota: DELETE /books/:id
 *
 * Exclui permanentemente um livro do catálogo. A exclusão é irreversível
 * em armazenamento em memória (não há "lixeira" neste exemplo).
 *
 * Seguimos a convenção REST de retornar 204 No Content para DELETE bem-sucedido,
 * pois o recurso não existe mais e não há conteúdo para retornar. Isso também
 * economiza largura de banda ao evitar enviar um body vazio.
 *
 * @route DELETE /books/:id
 * @access Public
 * @param {number} id - Identificador do livro a excluir
 *
 * @returns {204} Sucesso — recurso excluído (sem content)
 * @returns {400} Erro de validação se o ID for inválido
 * @returns {404} Erro se o livro não existir
 *
 * @example curl
 *   # Excluir um livro
 *   curl -X DELETE http://localhost:3000/books/1
 *
 *   # Resposta: 204 No Content (sem body)
 */
router.delete("/books/:id", validateIdParam(), (req, res) => {
  const deleted = deleteBook(req.validatedId);

  if (!deleted) {
    throw new NotFoundError("Livro", req.validatedId);
  }

  // 204 No Content — sucesso sem corpo de resposta
  res.status(204).end();
});

// ============================================================================
// GET /stats — Estatísticas do catálogo
// ============================================================================

/**
 * Rota: GET /stats
 *
 * Retorna estatísticas agregadas sobre o catálogo de livros. Estas são
 * informações de leitura (apenas GET) que não modificam o estado do servidor,
 * por isso não precisam de validação de entrada.
 *
 * As estatísticas incluem contagens, médias e distribuições calculadas
 * em tempo real a partir dos dados em memória. Em produção com banco de
 * dados, estas consultas seriam otimizadas com índices e possivelmente
 * materialized views para performance.
 *
 * @route GET /stats
 * @access Public
 *
 * @returns {200} Objeto com estatísticas do catálogo
 *
 * @example curl
 *   # Obter estatísticas
 *   curl http://localhost:3000/stats
 *
 *   # Resposta (200 OK):
 *   {
 *     "data": {
 *       "totalBooks": 5,
 *       "totalAuthors": 4,
 *       "avgYear": 1950.5,
 *       "booksByGenre": {
 *         "Romance": 2,
 *         "Sem gênero": 1,
 *         "Ficção Científica": 1,
 *         "Poesia": 1
 *       }
 *     }
 *   }
 */
router.get("/stats", (req, res) => {
  const stats = getStats();
  res.json({ data: stats });
});

// ============================================================================
// EXPORTAÇÃO DO ROUTER
// ============================================================================
//
// O router é exportado para ser montado no app principal (app.js).
// Isso permite que o Express gerencie o ciclo de vida do router
// e aplique middlewares de forma hierárquica.

module.exports = router;
```

