## Arquivo 5: `src/app.js`

```javascript
/**
 * @fileoverview Aplicação principal da API REST de livros.
 *
 * Este arquivo configura o servidor Express, registra middlewares globais,
 * monta as rotas e inicia o listener na porta configurada.
 *
 * ============================================================================
 * ARQUITETURA EM CAMADAS
 * ============================================================================
 *
 * A aplicação segue uma arquitetura em camadas bem definida:
 *
 *   ┌─────────────────────────────────────────┐
 *   │           Camada de Apresentação         │  ← app.js (Express, rotas, middleware)
 *   ├─────────────────────────────────────────┤
 *   │            Camada de Roteamento          │  ← routes/books.js (handlers por rota)
 *   ├─────────────────────────────────────────┤
 *   │           Camada de Negócio              │  ← (implícita nos handlers)
 *   ├─────────────────────────────────────────┤
 *   │            Camada de Dados               │  ← data/books.js (CRUD em memória)
 *   └─────────────────────────────────────────┘
 *
 * Cada camada depende apenas da camada inferior, nunca da superior.
 * Isso permite testar e substituir camadas independentemente.
 *
 * ============================================================================
 * POR QUE express.json() E express.urlencoded()?
 * ============================================================================
 *
 * Express não faz parsing automático do corpo das requisições. Estes
 * middlewares nativos convertem:
 *   - express.json():      body em formato JSON (Content-Type: application/json)
 *   - express.urlencoded(): body em formato URL-encoded (form submissions)
 *
 * Sem estes middlewares, req.body seria undefined e as rotas POST/PUT
 * não conseguiriam acessar os dados enviados pelo cliente.
 */

const express = require("express");

// Importa o router de livros (camada de roteamento)
const bookRoutes = require("./routes/books");

// Importa o middleware global de tratamento de erros
const { errorHandler } = require("./middleware/errorHandler");

// Cria a aplicação Express
const app = express();

// ============================================================================
// CONFIGURAÇÃO DE PORTA
// ============================================================================
//
// Usamos process.env.PORT || 3000 para permitir:
//   - Desenvolvimento local: porta 3000 por padrão
//   - Deploy em plataformas (Heroku, Railway, etc.): usa a variável de ambiente
//   - Múltiplas instâncias locais sem conflito de portas
//
// O operador || (OR lógico) retorna o primeiro valor truthy encontrado.

const PORT = process.env.PORT || 3000;

// ============================================================================
// MIDDLEWARES GLOBAIS
// ============================================================================
//
// Middlewares são funções que têm acesso ao objeto request, response e next.
// Eles são executados EM ORDEM de registro, formando uma "pilha" (stack).
// Cada middleware pode:
//   1. Modificar req ou res
//   2. Encerrar a requisição enviando uma resposta
//   3. Chamar next() para passar o controle ao próximo middleware
//
// A ordem é CRÍTICA: middlewares de parsing devem vir antes das rotas,
// e o middleware de erro deve ser o ÚLTIMO registrado.

/**
 * Middleware: Parsing de JSON
 * Permite que as rotas acessem req.body com objetos JavaScript parseados
 * a partir do corpo JSON das requisições POST/PUT.
 */
app.use(express.json());

/**
 * Middleware: Parsing de URL-encoded
 * Permite parsing de dados enviados via formulários HTML ou curl -d.
 * limit: "10mb" define o tamanho máximo do body aceito.
 */
app.use(express.urlencoded({ extended: true, limit: "10mb" }));

/**
 * Middleware: Logging básico de requisições
 * Registra no console cada requisição recebida com método, URL e timestamp.
 * Útil para debugging e monitoramento em desenvolvimento.
 * Em produção, considere usar um logger estruturado como Winston ou Pino.
 */
app.use((req, res, next) => {
  console.log(
    `[${new Date().toISOString()}] ${req.method} ${req.url}`
  );
  next(); // Passa o controle para o próximo middleware/rota
});

// ============================================================================
// MONTAGEM DAS ROTAS
// ============================================================================
//
// app.use('/api', bookRoutes) monta todas as rotas do router sob o prefixo /api.
 * Isso significa que:
 *   - GET /books no router → GET /api/books na aplicação
 *   - POST /books no router → POST /api/books na aplicação
 *
 * O prefixo /api é uma convenção REST para versionamento futuro (ex: /api/v1/).
 * Em projetos maiores, pode-se usar app.use('/api/v1', bookRoutes) para
 * permitir múltiplas versões da API coexistirem.

app.use("/api", bookRoutes);

// ============================================================================
// ROTA DE HEALTH CHECK
// ============================================================================
//
 * Uma rota de health check é essencial para:
 *   - Monitoramento de disponibilidade (uptime monitoring)
 *   - Load balancers verificarem se o serviço está saudável
 *   - Kubernetes/Docker usarem como probe de saúde
 *
 * Retorna 200 com mensagem simples — sem dependências externas.

app.get("/api/health", (req, res) => {
  res.json({
    status: "ok",
    timestamp: new Date().toISOString(),
    uptime: process.uptime(), // Tempo em segundos que o processo está rodando
  });
});

// ============================================================================
// ROTA 404 PARA RECURSOS NÃO ENCONTRADOS
// ============================================================================
//
 * Esta rota deve vir DEPOIS de todas as outras rotas registradas.
 * Ela captura qualquer requisição cujo path não corresponda a nenhuma
 * rota definida, retornando 404 com mensagem clara.
 *
 * Se esta rota fosse registrada antes das rotas de livros, ela capturaria
 * TODAS as requisições, tornando as rotas funcionais inacessíveis.

app.use((req, res, next) => {
  res.status(404).json({
    error: {
      message: `Rota ${req.method} ${req.url} não encontrada`,
      statusCode: 404,
    },
  });
});

// ============================================================================
// MIDDLEWARE GLOBAL DE TRATAMENTO DE ERROS
// ============================================================================
 * Este middleware deve ser o ÚLTIMO app.use() registrado.
 * Ele captura erros passados via next(err) por qualquer rota ou middleware.
 * A assinatura com 4 parâmetros (err, req, res, next) é o que identifica
 * um middleware de erro para o Express.

app.use(errorHandler);

// ============================================================================
// INICIALIZAÇÃO DO SERVIDOR
// ============================================================================

app.listen(PORT, () => {
  console.log(`
╔══════════════════════════════════════════════════════════╗
║     API REST de Livros — Servidor Iniciado com Sucesso   ║
║                                                          ║
║  📍 Endereço:    http://localhost:${PORT}                  ║
║  📚 Endpoints:   /api/books, /api/stats                  ║
║  💚 Health:      /api/health                             ║
║  🌍 Ambiente:    ${process.env.NODE_ENV || "desenvolvimento".padEnd(32)}║
╚══════════════════════════════════════════════════════════╝
  `);
});

// ============================================================================
// EXPORTAÇÃO PARA TESTES
// ============================================================================
//
 * Exportamos a instância app (não o servidor) para permitir que testes
 * automatizados importem a aplicação e façam requisições HTTP sem precisar
 * iniciar um servidor real. Isso é feito usando supertest ou similar.

module.exports = app;
```

