## File 2: `src/models/book.js` — Data Model & In-Memory Storage

```javascript
/**
 * book.js — Book data model and in-memory storage layer
 *
 * WHY IN-MEMORY STORAGE?
 * ----------------------
 * For an educational example, an in-memory array avoids the complexity of
 * setting up a database (installation, connection strings, migrations). It lets
 * us focus on REST patterns, middleware, and error handling. In production, you
 * would replace this module with a database adapter (e.g., MongoDB, PostgreSQL)
 * while keeping the same interface — this is an example of the Repository Pattern.
 *
 * WHY AN ARRAY OF OBJECTS?
 * -------------------------
 * Each book is an object with typed fields. An array provides O(n) lookup by
 * iteration (acceptable for small datasets) and preserves insertion order, which
 * is useful when listing books. For larger datasets, a Map or database index
 * would give O(1) lookups by ID.
 */

// ─── In-Memory Storage ────────────────────────────────────────────────────────
// We use a module-level array as our "database." Because JavaScript modules are
// singletons (loaded once per process), this array persists across requests.
// In a real app, you'd inject a database connection instead.
const books = [];

// Auto-incrementing ID counter. Using a simple integer avoids UUID collisions
// and keeps IDs human-readable for debugging. In production, consider using
// ULIDs or UUIDs to avoid race conditions in distributed systems.
let nextId = 1;

/**
 * BookModel — Provides CRUD operations on the in-memory book store.
 *
 * Each method is deliberately synchronous because we're operating on an
 * in-memory array. If we were using a database, these would return Promises
 * and be declared `async`. Keeping them sync here makes the code easier to
 * follow for learners.
 */
const BookModel = {
  /**
   * findAll — Retrieve all books, optionally filtered by query parameters.
   *
   * @param {Object} [filters] — Optional filter criteria
   * @param {string} [filters.author] — Filter by author name (case-insensitive partial match)
   * @param {string} [filters.genre]  — Filter by genre (exact match, case-insensitive)
   * @returns {Array<Object>} Array of book objects matching the filters
   *
   * EXAMPLE:
   *   findAll({ author: 'tolkien' }) → [{ id: 1, title: 'The Hobbit', ... }]
   */
  findAll(filters = {}) {
    // Destructure filter keys with defaults so callers never get undefined.
    const { author, genre } = filters;

    return books.filter((book) => {
      // If no author filter is provided, this condition is always true (no filtering).
      // We use .toLowerCase() for case-insensitive matching — users shouldn't need
      // to know the exact capitalization of an author's name.
      const matchesAuthor = !author || book.author.toLowerCase().includes(author.toLowerCase());

      // Genre uses strict equality after lowercasing both sides for consistency.
      const matchesGenre = !genre || book.genre.toLowerCase() === genre.toLowerCase();

      // Both conditions must be true (logical AND) — this is how SQL WHERE clauses
      // combine multiple filter columns with implicit AND logic.
      return matchesAuthor && matchesGenre;
    });
  },

  /**
   * findById — Retrieve a single book by its numeric ID.
   *
   * @param {number} id — The unique identifier of the book
   * @returns {Object|undefined} The book object, or undefined if not found
   *
   * WHY Array.find() INSTEAD OF A LOOP?
   * ------------------------------------
   * Array.find() is more readable and expresses intent clearly: "find the first
   * element where this condition is true." It's functionally equivalent to a
   * manual for-loop with a break, but communicates purpose better.
   */
  findById(id) {
    return books.find((book) => book.id === id);
  },

  /**
   * create — Insert a new book into the store and assign it a unique ID.
   *
   * @param {Object} bookData — The book data to insert (without id or createdAt)
   * @returns {Object} The newly created book object, including its assigned id and timestamp
   *
   * WHY WE RETURN THE FULL OBJECT?
   * ------------------------------
   * REST convention dictates that POST /books returns the created resource so the
   * client can immediately use it without making a second GET request. This is
   * called "eager response" and improves UX by reducing round trips.
   */
  create(bookData) {
    const newBook = {
      id: nextId++,          // Assign current counter value, then increment for next time
      ...bookData,           // Spread in all provided fields (title, author, genre, etc.)
      createdAt: new Date().toISOString(), // ISO 8601 format is the universal standard for timestamps
    };

    books.push(newBook);     // O(1) append to array — efficient for our use case
    return newBook;          // Return the complete object including generated fields
  },

  /**
   * updateById — Replace an existing book's data with new values.
   *
   * @param {number} id — The ID of the book to update
   * @param {Object} updates — Fields to overwrite (partial update supported)
   * @returns {Object|undefined} The updated book, or undefined if not found
   *
   * WHY SPREAD + OVERWRITE INSTEAD OF FULL REPLACEMENT?
   * ---------------------------------------------------
   * We use Object.assign() (via spread syntax) so that only the provided fields
   * are changed. This supports partial updates — a key REST pattern where clients
   * can update just the title without resending the entire book object.
   */
  updateById(id, updates) {
    const index = books.findIndex((book) => book.id === id);

    if (index === -1) {
      return undefined; // Signal "not found" — caller should throw a 404 error
    }

    // Create a new object with existing fields spread in, then overwritten by updates.
    // This preserves fields the client didn't send (like createdAt and id).
    const updatedBook = { ...books[index], ...updates };

    // Replace the old book in-place to maintain array order and references.
    books[index] = updatedBook;
    return updatedBook;
  },

  /**
   * deleteById — Remove a book from the store by its ID.
   *
   * @param {number} id — The ID of the book to delete
   * @returns {boolean} true if a book was deleted, false if not found
   *
   * WHY RETURN A BOOLEAN INSTEAD OF THE DELETED OBJECT?
   * ---------------------------------------------------
   * Deletion is inherently destructive — once removed, the data is gone. Returning
   * the deleted object would require us to store it somewhere first. A boolean
   * clearly communicates success/failure, which is sufficient for a DELETE response.
   */
  deleteById(id) {
    const index = books.findIndex((book) => book.id === id);

    if (index === -1) {
      return false; // Signal "not found" — caller should throw a 404 error
    }

    // splice removes the element and shifts subsequent elements to fill the gap.
    // This maintains contiguous array indices, which is important for predictable behavior.
    books.splice(index, 1);
    return true;
  },

  /**
   * count — Return the total number of books in the store.
   *
   * @returns {number} Total book count
   */
  count() {
    return books.length;
  },
};

module.exports = BookModel;
```

