## File 3: `src/middleware/errorHandler.js` — Custom Error Classes & Middleware

```javascript
/**
 * errorHandler.js — Custom error classes and Express error-handling middleware
 *
 * WHY CUSTOM ERROR CLASSES?
 * -------------------------
 * JavaScript's built-in Error class is generic. By creating subclasses like
 * NotFoundError and ValidationError, we can:
 *   1. Distinguish error types in our middleware (e.g., return 404 vs 400)
 *   2. Attach additional metadata (like `statusCode` and `details`)
 *   3. Provide better debugging information during development
 *
 * This follows the principle of "fail loudly and specifically" — every error
 * should tell us exactly what went wrong and at what HTTP level.
 *
 * WHY ERROR HANDLING MIDDLEWARE?
 * ------------------------------
 * Express has a special middleware signature: (err, req, res, next) => {}. When
 * any middleware or route handler calls `next(err)` or throws an error, Express
 * skips all remaining middleware and jumps to the first error handler with 4
 * arguments. This centralizes error formatting so every route doesn't need its
 * own try/catch block.
 */

/**
 * AppError — Base class for all application-specific errors.
 *
 * Extends the built-in Error class to add HTTP semantics (status code) and
 * optional structured details. All custom errors in this app inherit from this.
 */
class AppError extends Error {
  /**
   * @param {string} message — Human-readable error description
   * @param {number} statusCode — HTTP status code (e.g., 400, 404, 500)
   * @param {Object} [details] — Additional structured error information
   */
  constructor(message, statusCode, details = {}) {
    super(message); // Call the parent Error constructor to set the message

    // Capture the stack trace at the point of instantiation (not where Error was called).
    // This is crucial for debugging because it points to the actual line that threw.
    this.stack = new Error().stack;

    this.statusCode = statusCode; // Attach HTTP status for the middleware to read
    this.details = details;       // Attach structured data (e.g., which field failed validation)
    this.isOperational = true;    // Mark as "expected" error (not a bug in our code)
  }
}

/**
 * NotFoundError — Thrown when a requested resource doesn't exist.
 * Maps to HTTP 404 Not Found.
 */
class NotFoundError extends AppError {
  constructor(resource) {
    // "resource" is a string like 'Book' — we interpolate it into the message.
    super(`${resource} not found`, 404);
  }
}

/**
 * ValidationError — Thrown when client input fails validation rules.
 * Maps to HTTP 400 Bad Request. Includes field-level details for the client.
 */
class ValidationError extends AppError {
  /**
   * @param {string} message — General error description
   * @param {Array<Object>} fields — Array of { field, message } objects detailing each failure
   */
  constructor(message, fields = []) {
    super(message, 400, { fields });
  }
}

/**
 * InternalServerError — Thrown for unexpected server-side failures.
 * Maps to HTTP 500 Internal Server Error. In production, details are hidden
 * from the client response to avoid leaking sensitive information.
 */
class InternalServerError extends AppError {
  constructor(message = 'An unexpected error occurred') {
    super(message, 500);
  }
}

/**
 * errorHandler — Express middleware that catches all errors and formats responses.
 *
 * This MUST be the last middleware registered (after all routes) for it to work.
 * Express matches middleware in registration order, so placing this last ensures
 * it only handles errors that weren't caught earlier.
 *
 * @param {Error} err — The error object thrown by a route or middleware
 * @param {Object} req — Express request object (not used here but required by signature)
 * @param {Object} res — Express response object
 * @param {Function} next — Express next function (unused in error handlers)
 */
const errorHandler = (err, req, res, next) => {
  // Determine the status code: use err.statusCode if set, otherwise default to 500.
  // This ensures that even if we forget to set a status on a custom error, we still
  // return a valid HTTP response instead of letting Express send a generic 500.
  const statusCode = err.statusCode || 500;

  // In development, include the full stack trace so developers can debug quickly.
  // In production, hide it to prevent leaking implementation details to attackers.
  const isDevelopment = process.env.NODE_ENV !== 'production';

  // Build a consistent JSON response shape for ALL errors:
  //   { success: false, error: { message, statusCode, details? } }
  // This uniform structure makes it easy for API consumers to handle errors uniformly.
  const response = {
    success: false,
    error: {
      message: err.message,
      statusCode,
    },
  };

  // Only include details in development (or if explicitly allowed) to avoid
  // leaking internal state like database queries or file paths.
  if (isDevelopment && err.details) {
    response.error.details = err.details;
  }

  // Log the full error with stack trace to the server console for debugging.
  // This is separate from the client response — operators need full info even
  // when clients only get a sanitized message.
  console.error(`[ERROR] ${statusCode} — ${err.message}`);
  if (isDevelopment && err.stack) {
    console.error(err.stack);
  }

  // Send the formatted JSON response.
  res.status(statusCode).json(response);
};

module.exports = { AppError, NotFoundError, ValidationError, InternalServerError, errorHandler };
```

