## File 4: `src/middleware/validation.js` — Input Validation Middleware

```javascript
/**
 * validation.js — Request body validation middleware for book endpoints
 *
 * WHY VALIDATION MIDDLEWARE SEPARATE FROM ROUTES?
 * ------------------------------------------------
 * Separating validation from route logic follows the Single Responsibility Principle.
 * Routes should focus on business logic (what to do), while middleware handles
 * cross-cutting concerns like input sanitization (whether the input is valid).
 * This makes both routes and validators easier to test independently.
 *
 * WHY VALIDATE BEFORE REACHING THE MODEL?
 * ----------------------------------------
 * Validating at the middleware layer prevents invalid data from ever touching our
 * storage layer. It's a "fail fast" approach — reject bad input as early as possible
 * with a clear error message, rather than letting it propagate and cause confusing
 * errors downstream.
 */

const { ValidationError } = require('./errorHandler');

/**
 * validateCreateBook — Middleware that validates the request body for POST /books.
 *
 * Required fields: title (string, non-empty), author (string, non-empty).
 * Optional field: genre (string).
 *
 * @param {Object} req — Express request object
 * @param {Object} res — Express response object
 * @param {Function} next — Express next function
 * @throws {ValidationError} If validation fails, thrown before reaching the route handler
 */
const validateCreateBook = (req, res, next) => {
  const { title, author, genre } = req.body; // Destructure the fields we care about

  // Collect all validation failures into an array. We check ALL fields first so the
  // client receives a complete list of errors in one response, rather than fixing
  // them one at a time (which would require multiple round trips).
  const errors = [];

  if (!title || typeof title !== 'string' || title.trim().length === 0) {
    errors.push({ field: 'title', message: 'Title is required and must be a non-empty string' });
  }

  if (!author || typeof author !== 'string' || author.trim().length === 0) {
    errors.push({ field: 'author', message: 'Author is required and must be a non-empty string' });
  }

  // Genre is optional, but if provided it must be a string.
  if (genre !== undefined && genre !== null && typeof genre !== 'string') {
    errors.push({ field: 'genre', message: 'Genre must be a string if provided' });
  }

  // If any errors were collected, throw a ValidationError with all field details.
  // The error handler middleware will catch this and return a formatted 400 response.
  if (errors.length > 0) {
    throw new ValidationError('Book validation failed', errors);
  }

  // Trim whitespace from string fields to prevent accidental leading/trailing spaces.
  req.body.title = title.trim();
  req.body.author = author.trim();
  if (genre !== undefined && genre !== null) {
    req.body.genre = genre.trim();
  }

  // Validation passed — proceed to the route handler.
  next();
};

/**
 * validateUpdateBook — Middleware that validates the request body for PUT /books/:id.
 *
 * Unlike create, all fields are optional for updates (partial update support).
 * However, if a field IS provided, it must meet the same type requirements.
 *
 * @param {Object} req — Express request object
 * @param {Object} res — Express response object
 * @param {Function} next — Express next function
 * @throws {ValidationError} If validation fails
 */
const validateUpdateBook = (req, res, next) => {
  const { title, author, genre } = req.body;
  const errors = [];

  // For updates, we only validate fields that the client actually sent.
  // This is what makes partial updates possible — sending just { title: 'New Title' }
  // should succeed without requiring author and genre.
  if (title !== undefined) {
    if (typeof title !== 'string' || title.trim().length === 0) {
      errors.push({ field: 'title', message: 'Title must be a non-empty string' });
    }
  }

  if (author !== undefined) {
    if (typeof author !== 'string' || author.trim().length === 0) {
      errors.push({ field: 'author', message: 'Author must be a non-empty string' });
    }
  }

  if (genre !== undefined && typeof genre !== 'string') {
    errors.push({ field: 'genre', message: 'Genre must be a string if provided' });
  }

  if (errors.length > 0) {
    throw new ValidationError('Book validation failed', errors);
  }

  // Trim strings in place, similar to create validation.
  if (title !== undefined) req.body.title = title.trim();
  if (author !== undefined) req.body.author = author.trim();
  if (genre !== undefined) req.body.genre = genre.trim();

  next();
};

module.exports = { validateCreateBook, validateUpdateBook };
```

