## File 5: `src/routes/books.js` — Book CRUD Routes

```javascript
/**
 * books.js — RESTful route handlers for book resources
 *
 * WHY SEPARATE ROUTE FILES?
 * -------------------------
 * As the API grows, keeping all routes in one file becomes unmaintainable. By
 * organizing routes into separate files (one per resource), we:
 *   1. Keep each file focused and easy to navigate
 *   2. Can test route handlers in isolation
 *   3. Make it clear which endpoints belong to which resource
 *
 * This is an example of the "convention over configuration" principle — by
 * following a predictable structure, both humans and tools can understand the
 * codebase without extensive documentation.
 *
 * WHY ASYNC/AWAIT?
 * ----------------
 * Even though our model methods are synchronous in this example, we write routes
 * as async functions because:
 *   1. It's the modern JavaScript standard for handling asynchronous operations
 *   2. When we later connect a database, the route code won't need changes — only
 *      the model layer needs to return Promises
 *   3. Async/await is more readable than .then() chains, reducing cognitive load
 */

const express = require('express');
const BookModel = require('../models/book');
const { NotFoundError } = require('../middleware/errorHandler');
const { validateCreateBook, validateUpdateBook } = require('../middleware/validation');

// Create an Express Router instance. Routers are mini-applications that handle
// a subset of routes. They can be mounted at a path prefix (see server.js), which
// keeps our route definitions clean and reusable.
const router = express.Router();

// ─── GET /books — List all books with optional filtering ──────────────────────
/**
 * @name GET /books
 * @description Retrieve a list of all books, with optional query parameter filters.
 *
 * Query Parameters:
 *   - author (string): Filter by author name (case-insensitive partial match)
 *   - genre  (string): Filter by genre    (case-insensitive exact match)
 *
 * Response Bodies:
 *   200 OK — { success: true, data: [...], count: N }
 *
 * @example
 *   // List all books
 *   curl http://localhost:3000/books
 *
 *   // Filter by author
 *   curl "http://localhost:3000/books?author=tolkien"
 *
 *   // Filter by genre
 *   curl "http://localhost:3000/books?genre=fiction"
 */
router.get('/', async (req, res, next) => {
  try {
    // Extract filter parameters from the query string. Express automatically parses
    // URL query strings into req.query (e.g., ?author=tolkien → req.query.author).
    const filters = {
      author: req.query.author,
      genre: req.query.genre,
    };

    // Call the model to retrieve filtered books. The model handles the filtering
    // logic, keeping routes focused on HTTP concerns (status codes, headers).
    const foundBooks = BookModel.findAll(filters);

    // Return a consistent response shape with success flag, data array, and count.
    // Including `count` at the top level lets clients know the total without
    // having to compute it from the array length themselves.
    res.json({
      success: true,
      data: foundBooks,
      count: foundBooks.length,
    });
  } catch (error) {
    // Pass any unexpected errors to our centralized error handler middleware.
    next(error);
  }
});

// ─── GET /books/:id — Get a single book by ID ────────────────────────────────
/**
 * @name GET /books/:id
 * @description Retrieve a single book by its numeric ID.
 *
 * Path Parameters:
 *   - id (number): The unique identifier of the book
 *
 * Response Bodies:
 *   200 OK       — { success: true, data: { ...book } }
 *   404 Not Found — { success: false, error: { message: 'Book not found', statusCode: 404 } }
 *
 * @example
 *   // Get book with ID 1
 *   curl http://localhost:3000/books/1
 */
router.get('/:id', async (req, res, next) => {
  try {
    // Convert the path parameter to a number. Express gives us strings from :id,
    // but our model expects a numeric ID for comparison (===). This prevents
    // type-coercion bugs where "1" === 1 would be false in strict mode.
    const id = parseInt(req.params.id, 10);

    // Validate that the parameter was actually a number. parseInt('abc') returns NaN,
    // which is not a valid book ID. We catch this early with a clear error message.
    if (isNaN(id)) {
      throw new NotFoundError('Book');
    }

    const book = BookModel.findById(id);

    // If no book was found, throw our custom NotFoundError. The error handler will
    // format this as a 404 JSON response automatically — no need for if/else here.
    if (!book) {
      throw new NotFoundError('Book');
    }

    res.json({ success: true, data: book });
  } catch (error) {
    next(error);
  }
});

// ─── POST /books — Create a new book ─────────────────────────────────────────
/**
 * @name POST /books
 * @description Create a new book resource. The server assigns the ID and timestamp.
 *
 * Request Body (JSON):
 *   - title  (string, required): Title of the book
 *   - author (string, required): Author of the book
 *   - genre  (string, optional): Genre/category of the book
 *
 * Response Bodies:
 *   201 Created — { success: true, data: { ...newBook } }
 *   400 Bad Request — { success: false, error: { message, statusCode: 400, details: [...] } }
 *
 * @example
 *   // Create a new book
 *   curl -X POST http://localhost:3000/books \
 *        -H "Content-Type: application/json" \
 *        -d '{"title": "The Hobbit", "author": "J.R.R. Tolkien", "genre": "Fantasy"}'
 */
router.post('/', validateCreateBook, async (req, res, next) => {
  try {
    // The validateCreateBook middleware runs first (it's listed before the handler).
    // If validation fails, it throws a ValidationError and the handler never executes.
    // This is called "middleware chaining" — Express runs middlewares in order.

    const newBook = BookModel.create(req.body);

    // 201 Created is the standard HTTP status for successful resource creation.
    // It tells the client "your request was processed and a new resource was created."
    // We also set the Location header to point to the newly created resource, which
    // is a REST best practice (clients can follow this link to GET the new book).
    res.status(201).header('Location', `/books/${newBook.id}`).json({
      success: true,
      data: newBook,
    });
  } catch (error) {
    next(error);
  }
});

// ─── PUT /books/:id — Update an existing book ────────────────────────────────
/**
 * @name PUT /books/:id
 * @description Fully update a book's data. All provided fields replace the old values.
 *
 * Path Parameters:
 *   - id (number): The unique identifier of the book to update
 *
 * Request Body (JSON):
 *   - title  (string, optional): New title
 *   - author (string, optional): New author
 *   - genre  (string, optional): New genre
 *
 * Response Bodies:
 *   200 OK       — { success: true, data: { ...updatedBook } }
 *   400 Bad Request — Validation error response
 *   404 Not Found — { success: false, error: { message: 'Book not found', statusCode: 404 } }
 *
 * @example
 *   // Update a book's title and genre
 *   curl -X PUT http://localhost:3000/books/1 \
 *        -H "Content-Type: application/json" \
 *        -d '{"title": "The Hobbit (Updated Edition)", "genre": "Adventure"}'
 */
router.put('/:id', validateUpdateBook, async (req, res, next) => {
  try {
    const id = parseInt(req.params.id, 10);

    if (isNaN(id)) {
      throw new NotFoundError('Book');
    }

    // Pass only the fields the client sent in req.body. The model's updateById
    // uses object spread to merge updates with existing data, preserving unchanged fields.
    const updatedBook = BookModel.updateById(id, req.body);

    if (!updatedBook) {
      throw new NotFoundError('Book');
    }

    res.json({ success: true, data: updatedBook });
  } catch (error) {
    next(error);
  }
});

// ─── DELETE /books/:id — Delete a book ───────────────────────────────────────
/**
 * @name DELETE /books/:id
 * @description Permanently remove a book from the store.
 *
 * Path Parameters:
 *   - id (number): The unique identifier of the book to delete
 *
 * Response Bodies:
 *   200 OK       — { success: true, message: 'Book deleted successfully' }
 *   404 Not Found — { success: false, error: { message: 'Book not found', statusCode: 404 } }
 *
 * @example
 *   // Delete book with ID 1
 *   curl -X DELETE http://localhost:3000/books/1
 */
router.delete('/:id', async (req, res, next) => {
  try {
    const id = parseInt(req.params.id, 10);

    if (isNaN(id)) {
      throw new NotFoundError('Book');
    }

    const deleted = BookModel.deleteById(id);

    if (!deleted) {
      throw new NotFoundError('Book');
    }

    // 200 OK with a confirmation message is appropriate for DELETE.
    // Some APIs return 204 No Content (empty body), but a confirmation message
    // is more user-friendly for educational purposes and API consumers.
    res.json({ success: true, message: 'Book deleted successfully' });
  } catch (error) {
    next(error);
  }
});

module.exports = router;
```

