## File 6: `src/routes/stats.js` — Statistics Endpoint

```javascript
/**
 * stats.js — Read-only statistics endpoint for the book collection
 *
 * WHY A SEPARATE STATS ENDPOINT?
 * -------------------------------
 * Statistics are a read-only aggregation over all data, not a CRUD operation on
 * a single resource. Keeping it separate from the books routes:
 *   1. Makes the API surface clearer (stats ≠ books)
 *   2. Allows different caching strategies (stats can be cached longer than individual records)
 *   3. Follows REST's principle that each endpoint represents a distinct resource
 *
 * This endpoint demonstrates how to compute derived data from the store — a
 * common pattern in real APIs where you need aggregates like counts, averages, etc.
 */

const express = require('express');
const BookModel = require('../models/book');

const router = express.Router();

/**
 * @name GET /stats
 * @description Return aggregate statistics about the book collection.
 *
 * Response Body (200 OK):
 * {
 *   success: true,
 *   data: {
 *     totalBooks: 42,
 *     totalAuthors: 30,
 *     genres: { Fantasy: 15, Mystery: 10, ... },
 *     averageTitleLength: 18.5
 *   }
 * }
 *
 * @example
 *   curl http://localhost:3000/stats
 */
router.get('/', (req, res) => {
  // Retrieve all books once — we need the full dataset for each statistic.
  const allBooks = BookModel.findAll();

  // Compute total number of books. This is a trivial count but demonstrates the
  // pattern: fetch data, transform it, return structured results.
  const totalBooks = allBooks.length;

  // Use a Set to collect unique author names. Sets automatically deduplicate,
  // which is more efficient than checking an array for each new author.
  const uniqueAuthors = new Set(allBooks.map((book) => book.author));
  const totalAuthors = uniqueAuthors.size;

  // Count occurrences of each genre using a reduce accumulator. This builds a
  // frequency map in a single pass through the data — O(n) time complexity.
  const genres = allBooks.reduce((acc, book) => {
    // Use 'Unknown' as fallback for books without a genre field.
    const genre = book.genre || 'Unknown';
    acc[genre] = (acc[genre] || 0) + 1;
    return acc;
  }, {});

  // Compute the average title length. We handle the edge case of zero books to
  // avoid division by zero, which would produce Infinity and confuse API consumers.
  const averageTitleLength =
    totalBooks > 0
      ? allBooks.reduce((sum, book) => sum + book.title.length, 0) / totalBooks
      : 0;

  res.json({
    success: true,
    data: {
      totalBooks,
      totalAuthors,
      genres,
      averageTitleLength: Math.round(averageTitleLength * 100) / 100, // Round to 2 decimal places
    },
  });
});

module.exports = router;
```

