## File 7: `src/server.js` — Application Entry Point

```javascript
/**
 * server.js — Express application bootstrap and configuration
 *
 * WHY SEPARATE SERVER SETUP FROM ROUTES?
 * ---------------------------------------
 * The server file is responsible for "wiring" the application together: registering
 * middleware, mounting routers, and starting the HTTP listener. Routes should not
 * know about HTTP servers — they only define what happens when a request arrives.
 * This separation of concerns makes each piece independently testable.
 *
 * WHY MIDDLEWARE ORDER MATTERS?
 * ------------------------------
 * Express executes middleware in the exact order it is registered. The order here is:
 *   1. body-parser → parses incoming JSON bodies so req.body is available
 *   2. express.json() → same as above, built-in since Express 4.16
 *   3. CORS → allows cross-origin requests (important for frontend development)
 *   4. Request logging → logs each request for debugging and monitoring
 *   5. Routes → our application handlers
 *   6. Error handler → catches errors from any route or middleware
 *
 * If we placed the error handler before routes, it would never see route errors.
 * If we placed routes before body-parser, req.body would be undefined.
 */

const express = require('express');
const { errorHandler } = require('./middleware/errorHandler');

// Create the Express application instance. This is our "app" object that holds
// all middleware, routes, and configuration. Think of it as the container for
// everything that makes up our API server.
const app = express();

// ─── Middleware Registration ──────────────────────────────────────────────────

/**
 * express.json() — Built-in middleware that parses incoming request bodies with
 * Content-Type: application/json. After this middleware runs, req.body contains
 * the parsed JSON object instead of a raw string.
 *
 * limit: '10kb' prevents clients from sending extremely large payloads that could
 * exhaust server memory. This is a simple DoS (Denial of Service) prevention measure.
 */
app.use(express.json({ limit: '10kb' }));

/**
 * CORS (Cross-Origin Resource Sharing) middleware — Allows our API to be called
 * from frontend applications running on different domains (e.g., a React app on
 * port 3000 calling this API on port 3001).
 *
 * In production, you would restrict origins to specific domains instead of using '*'.
 */
app.use((req, res, next) => {
  res.header('Access-Control-Allow-Origin', '*');
  res.header('Access-Control-Allow-Headers', 'Origin, X-Requested-With, Content-Type, Accept');
  res.header('Access-Control-Allow-Methods', 'GET, POST, PUT, DELETE, OPTIONS');

  // Handle preflight requests (OPTIONS) that browsers send before some cross-origin requests.
  if (req.method === 'OPTIONS') {
    return res.sendStatus(200);
  }
  next();
});

/**
 * Request logging middleware — Prints a concise log for every incoming request.
 * This is invaluable for debugging and monitoring in development.
 * Format: [TIMESTAMP] METHOD PATH → STATUS
 */
app.use((req, res, next) => {
  const timestamp = new Date().toISOString();
  console.log(`[${timestamp}] ${req.method} ${req.path}`);
  next(); // Must call next() to continue the middleware chain
});

// ─── Route Mounting ───────────────────────────────────────────────────────────

/**
 * Mount book routes at /books. All routes defined in books.js will be prefixed
 * with /books automatically. For example, router.get('/') becomes GET /books.
 *
 * Mounting stats at /stats keeps it separate from the books resource namespace.
 */
const booksRouter = require('./routes/books');
const statsRouter = require('./routes/stats');

app.use('/books', booksRouter);
app.use('/stats', statsRouter);

// ─── Root Endpoint ────────────────────────────────────────────────────────────
/**
 * GET / — Simple health check and API information endpoint.
 * Returns a welcome message with links to available endpoints.
 */
app.get('/', (req, res) => {
  res.json({
    success: true,
    message: 'Book REST API — Educational Example',
    endpoints: {
      books: {
        list: 'GET /books?author=...&genre=...',
        get: 'GET /books/:id',
        create: 'POST /books (JSON body: { title, author, genre })',
        update: 'PUT /books/:id (JSON body: { title?, author?, genre? })',
        delete: 'DELETE /books/:id',
      },
      stats: 'GET /stats',
    },
  });
});

// ─── 404 Handler for Undefined Routes ────────────────────────────────────────
/**
 * If a request reaches this point, no route matched. We return 404 with a JSON
 * response instead of Express's default HTML 404 page, keeping the API consistent.
 */
app.use((req, res) => {
  res.status(404).json({
    success: false,
    error: { message: `Route ${req.method} ${req.path} not found`, statusCode: 404 },
  });
});

// ─── Global Error Handler (MUST be last) ──────────────────────────────────────
/**
 * Register the error handler as the final middleware. Express requires error
 * handlers to have exactly 4 parameters (err, req, res, next) to distinguish
 * them from regular middleware. This is how Express knows to route errors here.
 */
app.use(errorHandler);

// ─── Server Startup ───────────────────────────────────────────────────────────
const PORT = process.env.PORT || 3000; // Use env var in production, default to 3000 locally

app.listen(PORT, () => {
  console.log(`📚 Book API running on http://localhost:${PORT}`);
  console.log(`   Try: curl http://localhost:${PORT}/`);
});
```

