```javascript
/**
 * ============================================================
 * ROTAS DE LIVROS — CRUD COMPLETO
 * ============================================================
 *
 * POR QUE usar um array em memória?
 * ----------------------------------
 * Para este exemplo educacional, usamos um array porque:
 *   1. Elimina a necessidade de configurar banco de dados
 *   2. Facilita o entendimento do fluxo da API
 *   3. Permite focar nos conceitos REST e Express
 *
 * Em produção, substituiríamos este array por uma camada de
 * persistência (MongoDB, PostgreSQL, etc.) mantendo a mesma interface.
 *
 * ESTRUTURA DO DADO LIVRO:
 * {
 *   id: number          — Identificador único auto-incrementado
 *   title: string       — Título do livro (obrigatório)
 *   author: string      — Autor do livro (obrigatório)
 *   isbn: string        — ISBN (opcional, mas recomendado)
 *   genre: string       — Gênero literário
 *   publishedYear: number — Ano de publicação
 *   price: number       — Preço em reais/dólares
 *   createdAt: string    — Timestamp ISO da criação
 *   updatedAt: string    — Timestamp ISO da última atualização
 * }
 */

const { AppError, NotFoundError, ValidationError } = require('../errors/customErrors');

// ============================================================
// DADOS EM MEMÓRIA
// ============================================================
// Usamos const porque a referência ao array não muda, mas seu conteúdo sim.
// Isso é intencional: o array em si é imutável (nunca reatribuímos),
// mas seus elementos são mutáveis (atualizamos livros existentes).

/** @type {Array<Object>} Lista de livros armazenados em memória */
const books = [
  {
    id: 1,
    title: 'O Senhor dos Anéis',
    author: 'J.R.R. Tolkien',
    isbn: '978-0618640157',
    genre: 'Fantasia',
    publishedYear: 1954,
    price: 89.90,
    createdAt: '2024-01-15T10:00:00.000Z',
    updatedAt: '2024-01-15T10:00:00.000Z',
  },
  {
    id: 2,
    title: '1984',
    author: 'George Orwell',
    isbn: '978-0451524935',
    genre: 'Distopia',
    publishedYear: 1949,
    price: 34.50,
    createdAt: '2024-01-15T10:00:00.000Z',
    updatedAt: '2024-01-15T10:00:00.000Z',
  },
  {
    id: 3,
    title: 'Dom Casmurro',
    author: 'Machado de Assis',
    isbn: '978-8594318602',
    genre: 'Romance',
    publishedYear: 1899,
    price: 29.90,
    createdAt: '2024-01-15T10:00:00.000Z',
    updatedAt: '2024-01-15T10:00:00.000Z',
  },
];

/** @type {number} Próximo ID a ser atribuído (auto-incremento simples) */
let nextId = 4;

// ============================================================
// FUNÇÕES AUXILIARES DE VALIDAÇÃO
// ============================================================

/**
 * Valida os campos obrigatórios de um livro.
 *
 * @param {Object} bookData - Dados do livro a serem validados
 * @returns {Array<string>} Lista de mensagens de erro (vazia se válido)
 */
function validateBook(bookData) {
  const errors = [];

  // Título é obrigatório e deve ter pelo menos 1 caractere
  if (!bookData.title || typeof bookData.title !== 'string' || bookData.title.trim() === '') {
    errors.push('O campo "title" é obrigatório e deve ser uma string não vazia');
  }

  // Autor é obrigatório
  if (!bookData.author || typeof bookData.author !== 'string' || bookData.author.trim() === '') {
    errors.push('O campo "author" é obrigatório e deve ser uma string não vazia');
  }

  // Preço, se fornecido, deve ser um número positivo
  if (bookData.price !== undefined && bookData.price !== null) {
    if (typeof bookData.price !== 'number' || bookData.price < 0) {
      errors.push('O campo "price" deve ser um número não negativo');
    }
  }

  // Ano de publicação, se fornecido, deve ser um número razoável
  if (bookData.publishedYear !== undefined && bookData.publishedYear !== null) {
    const currentYear = new Date().getFullYear();
    if (
      typeof bookData.publishedYear !== 'number' ||
      bookData.publishedYear < 1000 ||
      bookData.publishedYear > currentYear + 1
    ) {
      errors.push(`O campo "publishedYear" deve ser um número entre 1000 e ${currentYear + 1}`);
    }
  }

  return errors;
}

/**
 * Retorna o timestamp ISO atual.
 * Usamos Date.now() em vez de new Date() para garantir consistência
 * de timestamps dentro da mesma requisição.
 *
 * @returns {string} Timestamp ISO 8601
 */
function getTimestamp() {
  return new Date().toISOString();
}

// ============================================================
// ROTAS — GET /books (LISTAR TODOS OS LIVROS)
// ============================================================

/**
 * @route   GET /books
 * @desc    Lista todos os livros com filtragem opcional por query params
 * @access  Public
 *
 * QUERY PARAMS (opcionais):
 *   - author      : Filtra por autor (case-insensitive, partial match)
 *   - genre       : Filtra por gênero (exact match)
 *   - minPrice    : Preço mínimo (número)
 *   - maxPrice    : Preço máximo (número)
 *   - search      : Busca por título ou autor (partial match)
 *   - page        : Número da página (padrão: 1)
 *   - limit       : Itens por página (padrão: 10, máximo: 100)
 *
 * EXEMPLOS DE USO:
 *   GET /books                          → todos os livros
 *   GET /books?author=tolkien           → livros de Tolkien
 *   GET /books?genre=Fantasia&limit=5   → até 5 livros de fantasia
 *   GET /books?search=senhor&page=1     → busca por "senhor" no título/autor
 *
 * EXEMPLO CURL:
 *   curl -X GET "http://localhost:3000/books?genre=Fantasia&limit=5"
 */
const getAllBooks = (req, res) => {
  try {
    // Extrai parâmetros de query com valores padrão
    const { author, genre, minPrice, maxPrice, search, page = 1, limit = 10 } = req.query;

    // Começa com uma cópia do array para não mutar o original durante filtragem
    let filteredBooks = [...books];

    // Filtragem por autor (case-insensitive, partial match)
    if (author) {
      const authorLower = author.toLowerCase();
      filteredBooks = filteredBooks.filter((book) =>
        book.author.toLowerCase().includes(authorLower)
      );
    }

    // Filtragem por gênero (exact match, case-insensitive)
    if (genre) {
      const genreLower = genre.toLowerCase();
      filteredBooks = filteredBooks.filter(
        (book) => book.genre.toLowerCase() === genreLower
      );
    }

    // Filtragem por faixa de preço
    if (minPrice !== undefined) {
      const min = parseFloat(minPrice);
      filteredBooks = filteredBooks.filter((book) => book.price >= min);
    }
    if (maxPrice !== undefined) {
      const max = parseFloat(maxPrice);
      filteredBooks = filteredBooks.filter((book) => book.price <= max);
    }

    // Busca por título ou autor (partial match, case-insensitive)
    if (search) {
      const searchLower = search.toLowerCase();
      filteredBooks = filteredBooks.filter(
        (book) =>
          book.title.toLowerCase().includes(searchLower) ||
          book.author.toLowerCase().includes(searchLower)
      );
    }

    // Paginação: calcula índices de início e fim
    const pageNum = Math.max(1, parseInt(page));
    const limitNum = Math.min(Math.max(1, parseInt(limit)), 100); // Máximo 100 itens por página
    const totalItems = filteredBooks.length;
    const totalPages = Math.ceil(totalItems / limitNum);
    const startIndex = (pageNum - 1) * limitNum;
    const paginatedBooks = filteredBooks.slice(startIndex, startIndex + limitNum);

    // Resposta com metadados de paginação
    res.json({
      success: true,
      count: paginatedBooks.length,
      totalItems,
      totalPages,
      currentPage: pageNum,
      data: paginatedBooks,
    });
  } catch (error) {
    // Encaminha erros para o middleware de tratamento
    next(error);
  }
};

// ============================================================
// ROTAS — GET /books/:id (OBTER LIVRO POR ID)
// ============================================================

/**
 * @route   GET /books/:id
 * @desc    Retorna um único livro pelo seu ID
 * @access  Public
 *
 * PARAMS:
 *   - id (number|string): ID numérico do livro
 *
 * EXEMPLO CURL:
 *   curl -X GET "http://localhost:3000/books/1"
 *
 * RESPOSTA SUCESSO (200):
 *   {
 *     "success": true,
 *     "data": {
 *       "id": 1,
 *       "title": "O Senhor dos Anéis",
 *       ...
 *     }
 *   }
 *
 * RESPOSTA ERRO (404):
 *   {
 *     "status": "error",
 *     "statusCode": 404,
 *     "message": "Livro com ID 999 não encontrado"
 *   }
 */
const getBookById = (req, res, next) => {
  try {
    // Converte o ID para número e valida que é um inteiro positivo
    const id = parseInt(req.params.id);

    if (isNaN(id) || id < 1) {
      throw new ValidationError('O parâmetro "id" deve ser um número inteiro positivo');
    }

    // find() retorna undefined se não encontrar, ao invés de lançar exceção
    const book = books.find((b) => b.id === id);

    if (!book) {
      // Lançamos NotFoundError para tratamento centralizado pelo middleware
      throw new NotFoundError('Livro', id);
    }

    res.json({ success: true, data: book });
  } catch (error) {
    next(error);
  }
};

// ============================================================
// ROTAS — POST /books (CRIAR NOVO LIVRO)
// ============================================================

/**
 * @route   POST /books
 * @desc    Cria um novo livro no sistema
 * @access  Public
 *
 * BODY JSON:
 *   {
 *     "title": "Nome do Livro",       // obrigatório, string
 *     "author": "Nome do Autor",      // obrigatório, string
 *     "isbn": "978-0000000000",       // opcional, string
 *     "genre": "Gênero",              // opcional, string
 *     "publishedYear": 2024,          // opcional, number
 *     "price": 49.90                  // opcional, number >= 0
 *   }
 *
 * EXEMPLO CURL:
 *   curl -X POST "http://localhost:3000/books" \
 *        -H "Content-Type: application/json" \
 *        -d '{"title":"Admirável Mundo Novo","author":"Aldous Huxley","genre":"Distopia","publishedYear":1932,"price":42.50}'
 *
 * RESPOSTA SUCESSO (201 Created):
 *   {
 *     "success": true,
 *     "message": "Livro criado com sucesso",
 *     "data": { ... livro criado com id e timestamps ... }
 *   }
 */
const createBook = (req, res, next) => {
  try {
    // Valida os dados de entrada antes de processar
    const validationErrors = validateBook(req.body);

    if (validationErrors.length > 0) {
      throw new ValidationError('Validação falhou', validationErrors);
    }

    // Cria o novo livro com ID auto-incrementado e timestamps
    const newBook = {
      id: nextId++,
      title: req.body.title.trim(),
      author: req.body.author.trim(),
      isbn: req.body.isbn || null,
      genre: req.body.genre || null,
      publishedYear: req.body.publishedYear || null,
      price: req.body.price !== undefined ? req.body.price : 0,
      createdAt: getTimestamp(),
      updatedAt: getTimestamp(),
    };

    // Adiciona ao array (operação O(1) no final)
    books.push(newBook);

    // 201 Created indica que um novo recurso foi criado com sucesso
    res.status(201).json({
      success: true,
      message: 'Livro criado com sucesso',
      data: newBook,
    });
  } catch (error) {
    next(error);
  }
};

// ============================================================
// ROTAS — PUT /books/:id (ATUALIZAR LIVRO EXISTENTE)
// ============================================================

/**
 * @route   PUT /books/:id
 * @desc    Atualiza completamente um livro existente (full update)
 * @access  Public
 *
 * PARAMS:
 *   - id (number): ID do livro a atualizar
 *
 * BODY JSON:
 *   Todos os campos são opcionais na atualização parcial, mas pelo menos
 *   um campo deve ser fornecido. Campos não enviados mantêm o valor original.
 *
 * EXEMPLO CURL:
 *   curl -X PUT "http://localhost:3000/books/1" \
 *        -H "Content-Type: application/json" \
 *        -d '{"price": 79.90, "genre": "Fantasia Épica"}'
 *
 * RESPOSTA SUCESSO (200 OK):
 *   {
 *     "success": true,
 *     "message": "Livro atualizado com sucesso",
 *     "data": { ... livro atualizado ... }
 *   }
 */
const updateBook = (req, res, next) => {
  try {
    const id = parseInt(req.params.id);

    if (isNaN(id) || id < 1) {
      throw new ValidationError('O parâmetro "id" deve ser um número inteiro positivo');
    }

    // Encontra o índice do livro no array (mais eficiente que find() para mutação)
    const bookIndex = books.findIndex((b) => b.id === id);

    if (bookIndex === -1) {
      throw new NotFoundError('Livro', id);
    }

    // Valida apenas os campos que estão sendo enviados
    const validationErrors = validateBook(req.body);
    if (validationErrors.length > 0) {
      throw new ValidationError('Validação falhou', validationErrors);
    }

    // Atualiza apenas os campos fornecidos no body (partial update)
    // Isso preserva campos não enviados (isbn, genre, etc.)
    const updatedBook = {
      ...books[bookIndex], // Espelha todos os campos existentes
      title: req.body.title !== undefined ? req.body.title.trim() : books[bookIndex].title,
      author: req.body.author !== undefined ? req.body.author.trim() : books[bookIndex].author,
      isbn: req.body.isbn !== undefined ? req.body.isbn : books[bookIndex].isbn,
      genre: req.body.genre !== undefined ? req.body.genre : books[bookIndex].genre,
      publishedYear:
        req.body.publishedYear !== undefined ? req.body.publishedYear : books[bookIndex].publishedYear,
      price: req.body.price !== undefined ? req.body.price : books[bookIndex].price,
      updatedAt: getTimestamp(), // Atualiza timestamp de modificação
    };

    // Substitui o livro antigo pelo atualizado no array
    books[bookIndex] = updatedBook;

    res.json({
      success: true,
      message: 'Livro atualizado com sucesso',
      data: updatedBook,
    });
  } catch (error) {
    next(error);
  }
};

// ============================================================
// ROTAS — DELETE /books/:id (EXCLUIR LIVRO)
// ============================================================

/**
 * @route   DELETE /books/:id
 * @desc    Remove um livro do sistema permanentemente
 * @access  Public
 *
 * PARAMS:
 *   - id (number): ID do livro a excluir
 *
 * EXEMPLO CURL:
 *   curl -X DELETE "http://localhost:3000/books/2"
 *
 * RESPOSTA SUCESSO (200 OK):
 *   {
 *     "success": true,
 *     "message": "Livro excluído com sucesso",
 *     "data": { ... livro excluído ... }
 *   }
 *
 * NOTA: Em produção, considere usar soft-delete (marcar como inativo)
 *       ao invés de remover permanentemente do array.
 */
const deleteBook = (req, res, next) => {
  try {
    const id = parseInt(req.params.id);

    if (isNaN(id) || id < 1) {
      throw new ValidationError('O parâmetro "id" deve ser um número inteiro positivo');
    }

    const bookIndex = books.findIndex((b) => b.id === id);

    if (bookIndex === -1) {
      throw new NotFoundError('Livro', id);
    }

    // Splice remove o elemento do array e retorna um array com o elemento removido
    const [deletedBook] = books.splice(bookIndex, 1);

    res.json({
      success: true,
      message: 'Livro excluído com sucesso',
      data: deletedBook,
    });
  } catch (error) {
    next(error);
  }
};

// ============================================================
// ROTAS — GET /stats (ESTATÍSTICAS DOS LIVROS)
// ============================================================

/**
 * @route   GET /stats
 * @desc    Retorna estatísticas agregadas sobre o acervo de livros
 * @access  Public
 *
 * EXEMPLO CURL:
 *   curl -X GET "http://localhost:3000/stats"
 *
 * RESPOSTA (200 OK):
 *   {
 *     "success": true,
 *     "data": {
 *       "totalBooks": 3,
 *       "totalGenres": 3,
 *       "averagePrice": 51.43,
 *       "minPrice": 29.90,
 *       "maxPrice": 89.90,
 *       "oldestBook": { "title": "...", "year": 1899 },
 *       "newestBook": { "title": "...", "year": 1954 },
 *       "booksByGenre": { "Fantasia": 1, "Distopia": 2, "Romance": 1 }
 *     }
 *   }
 */
const getStats = (req, res) => {
  try {
    const totalBooks = books.length;

    if (totalBooks === 0) {
      // Retorna estatísticas zeradas quando não há livros
      return res.json({
        success: true,
        data: {
          totalBooks: 0,
          totalGenres: 0,
          averagePrice: 0,
          minPrice: 0,
          maxPrice: 0,
          oldestBook: null,
          newestBook: null,
          booksByGenre: {},
        },
      });
    }

    // Calcula estatísticas de preço usando reduce para eficiência (uma única passagem)
    const priceStats = books.reduce(
      (acc, book) => ({
        sum: acc.sum + book.price,
        min: Math.min(acc.min, book.price),
        max: Math.max(acc.max, book.price),
      }),
      { sum: 0, min: Infinity, max: -Infinity }
    );

    // Conta livros por gênero usando um objeto acumulador
    const booksByGenre = books.reduce((acc, book) => {
      const genre = book.genre || 'Sem gênero';
      acc[genre] = (acc[genre] || 0) + 1;
      return acc;
    }, {});

    // Encontra o livro mais antigo e mais recente por ano de publicação
    const oldestBook = books.reduce(
      (acc, book) => (book.publishedYear && book.publishedYear < acc.publishedYear ? book : acc),
      { publishedYear: Infinity }
    );
    const newestBook = books.reduce(
      (acc, book) => (book.publishedYear && book.publishedYear > acc.publishedYear ? book : acc),
      { publishedYear: -Infinity }
    );

    // Retorna todas as estatísticas calculadas
    res.json({
      success: true,
      data: {
        totalBooks,
        totalGenres: Object.keys(booksByGenre).length,
        averagePrice: parseFloat((priceStats.sum / totalBooks).toFixed(2)),
        minPrice: priceStats.min,
        maxPrice: priceStats.max,
        oldestBook: {
          title: oldestBook.title,
          author: oldestBook.author,
          year: oldestBook.publishedYear,
        },
        newestBook: {
          title: newestBook.title,
          author: newestBook.author,
          year: newestBook.publishedYear,
        },
        booksByGenre,
      },
    });
  } catch (error) {
    next(error);
  }
};

// ============================================================
// EXPORTAÇÃO DAS ROTAS
// ============================================================
// Usamos module.exports com objeto para exportar todas as rotas de uma vez.
// O app.js irá registrar cada rota individualmente, mantendo o controle
// sobre a ordem de middleware e tratamento de erros.

module.exports = {
  getAllBooks,
  getBookById,
  createBook,
  updateBook,
  deleteBook,
  getStats,
};
```

**Explicação detalhada das escolhas:**

1. **Array em memória**: Simples e eficiente para exemplos educacionais. Operações como `find`, `findIndex` e `splice` são O(n), aceitáveis para poucos registros.

2. **Validação antes do processamento**: Sempre validamos a entrada do cliente antes de qualquer operação, seguindo o princípio "never trust user input".

3. **Padrão try/catch + next()**: Cada handler usa try/catch e encaminha erros para `next(error)`, que é capturado pelo middleware de erros global. Isso evita repetição de código de tratamento.

4. **Partial update no PUT**: Usamos spread operator (`...books[bookIndex]`) para preservar campos não enviados, permitindo atualizações parciais.

5. **Estatísticas com `reduce`**: Usamos `reduce` para calcular múltiplas métricas em uma única passagem pelo array, otimizando performance.

