## Arquivo 5: `src/app.js`

```javascript
/**
 * ============================================================
 * APP PRINCIPAL — CONFIGURAÇÃO DO SERVIDOR EXPRESS
 * ============================================================
 *
 * POR QUE estruturar assim?
 * --------------------------
 * Esta é a "cola" que conecta todas as partes da API:
 *   1. Configura o Express com middlewares globais
 *   2. Registra as rotas na ordem correta
 *   3. Adiciona middleware de tratamento de erros por último
 *   4. Inicia o servidor na porta configurada
 *
 * ORDEM DOS MIDDLEWARES (IMPORTANTE):
 *   1. Middlewares globais (body-parser, CORS)
 *   2. Rotas da API
 *   3. Middleware de tratamento de erros (SEMPRE por último)
 *
 * Se o middleware de erro fosse registrado antes das rotas,
 * ele capturaria erros que ainda não aconteceram, causando
 * comportamento inesperado.
 */

const express = require('express');
const path = require('path');

// Importa as rotas e o middleware de erros
const {
  getAllBooks,
  getBookById,
  createBook,
  updateBook,
  deleteBook,
  getStats,
} = require('./routes/books');
const errorHandler = require('./middleware/errorHandler');

// ============================================================
// CONFIGURAÇÃO DO EXPRESS
// ============================================================

/** @type {import('express').Express} Instância do aplicativo Express */
const app = express();

// Porta do servidor: usa variável de ambiente ou padrão 3000
const PORT = process.env.PORT || 3000;

// ============================================================
// MIDDLEWARES GLOBAIS
// ============================================================

/**
 * body-parser: Parseia o corpo das requisições JSON.
 * Sem este middleware, req.body seria undefined.
 * express.json() é nativo do Express (não precisa de pacote extra).
 */
app.use(express.json());

/**
 * CORS: Permite requisições de qualquer origem (para desenvolvimento).
 * Em produção, substitua '*' por domínios específicos.
 */
app.use((req, res, next) => {
  res.header('Access-Control-Allow-Origin', '*');
  res.header('Access-Control-Allow-Headers', 'Origin, X-Requested-With, Content-Type, Accept');
  res.header('Access-Control-Allow-Methods', 'GET, POST, PUT, DELETE, OPTIONS');

  // Responde imediatamente a requisições OPTIONS (preflight do CORS)
  if (req.method === 'OPTIONS') {
    return res.sendStatus(200);
  }
  next();
});

/**
 * Logger simples: registra método, URL e timestamp de cada requisição.
 * Útil para debugging e monitoramento básico.
 */
app.use((req, res, next) => {
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.url}`);
  next();
});

// ============================================================
// ROTAS DA API
// ============================================================

/**
 * Rota raiz: informa que a API está no ar.
 */
app.get('/', (req, res) => {
  res.json({
    success: true,
    message: 'API de Livros — Servidor rodando!',
    endpoints: {
      docs: 'Veja o README.md para documentação completa',
      books: {
        GET: '/books',
        'GET :id': '/books/:id',
        POST: '/books',
        PUT: '/books/:id',
        DELETE: '/books/:id',
      },
      stats: 'GET /stats',
    },
  });
});

/**
 * Rota de saúde (health check): retorna 200 se o servidor está respondendo.
 * Útil para monitoramento e load balancers.
 */
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// --- Rotas de Livros ---

/**
 * GET /books — Lista todos os livros com filtragem e paginação
 * Documentação completa nos comentários do handler em routes/books.js
 */
app.get('/books', getAllBooks);

/**
 * GET /books/:id — Busca livro por ID
 */
app.get('/books/:id', getBookById);

/**
 * POST /books — Cria novo livro
 */
app.post('/books', createBook);

/**
 * PUT /books/:id — Atualiza livro existente
 */
app.put('/books/:id', updateBook);

/**
 * DELETE /books/:id — Exclui livro
 */
app.delete('/books/:id', deleteBook);

// --- Rota de Estatísticas ---

/**
 * GET /stats — Retorna estatísticas do acervo
 */
app.get('/stats', getStats);

// ============================================================
// TRATAMENTO DE ROTAS NÃO ENCONTRADAS (404)
// ============================================================

/**
 * Captura requisições para rotas que não foram definidas.
 * Lançamos um AppError para ser tratado pelo middleware de erros.
 */
app.use((req, res, next) => {
  const { AppError } = require('./errors/customErrors');
  next(new AppError(`Rota ${req.method} ${req.url} não encontrada`, 404));
});

// ============================================================
// MIDDLEWARE DE TRATAMENTO DE ERROS (SEMPRE POR ÚLTIMO)
// ============================================================
app.use(errorHandler);

// ============================================================
// INICIALIZAÇÃO DO SERVIDOR
// ============================================================

/**
 * Inicia o servidor e faz log de confirmação.
 * Usamos arrow function para manter o escopo léxico.
 */
app.listen(PORT, () => {
  console.log(`========================================`);
  console.log(`  API de Livros rodando na porta ${PORT}`);
  console.log(`  Ambiente: ${process.env.NODE_ENV || 'development'}`);
  console.log(`  Base URL: http://localhost:${PORT}`);
  console.log(`========================================`);
});

module.exports = app;
```

**Explicação das escolhas de arquitetura:**

1. **Ordem dos middlewares**: Middlewares globais → Rotas → 404 customizado → ErrorHandler. Esta ordem é crítica: o Express processa middlewares sequencialmente, e o handler de erros deve ser o último para capturar todos os erros.

2. **CORS inline**: Para um exemplo educacional, implementamos CORS manualmente sem pacote extra. Em produção, usaríamos `cors` npm package.

3. **Health check**: A rota `/health` é padrão em APIs profissionais para monitoramento por ferramentas como Docker healthchecks e Kubernetes probes.

4. **Rota 404 customizada**: Qualquer rota não definida gera um erro 404 estruturado, tratado uniformemente pelo middleware de erros.

