## File 2: `data/books.js` — In-Memory Data Store

```javascript
/**
 * @fileoverview In-memory data store for books.
 *
 * WHY IN-MEMORY?
 * For educational purposes, an in-memory array avoids the complexity of setting up a database
 * while still demonstrating CRUD operations. In production, you would replace this with a
 * database (MongoDB, PostgreSQL, etc.) and keep the same interface.
 *
 * DATA STRUCTURE CHOICES:
 * - Array of objects: Simple, ordered, easy to filter/sort.
 * - Each book has: id (unique identifier), title, author, genre, publishedYear, rating.
 * - IDs are auto-incremented integers for simplicity; in production, use UUIDs or ObjectId.
 */

// Seed data with sample books so the API is not empty on startup.
const books = [
  {
    id: 1,
    title: 'The Great Gatsby',
    author: 'F. Scott Fitzgerald',
    genre: 'Fiction',
    publishedYear: 1925,
    rating: 4.5
  },
  {
    id: 2,
    title: 'To Kill a Mockingbird',
    author: 'Harper Lee',
    genre: 'Fiction',
    publishedYear: 1960,
    rating: 4.8
  },
  {
    id: 3,
    title: '1984',
    author: 'George Orwell',
    genre: 'Dystopian',
    publishedYear: 1949,
    rating: 4.7
  },
  {
    id: 4,
    title: 'The Hobbit',
    author: 'J.R.R. Tolkien',
    genre: 'Fantasy',
    publishedYear: 1937,
    rating: 4.6
  },
  {
    id: 5,
    title: 'Dune',
    author: 'Frank Herbert',
    genre: 'Science Fiction',
    publishedYear: 1965,
    rating: 4.5
  }
];

/**
 * Get all books.
 * @returns {Array<Object>} Array of book objects.
 */
function getAllBooks() {
  return [...books]; // Return a copy to prevent external mutation
}

/**
 * Find a book by its ID.
 * @param {number} id - The unique identifier of the book.
 * @returns {Object|undefined} The book object if found, otherwise undefined.
 */
function getBookById(id) {
  return books.find(book => book.id === id);
}

/**
 * Add a new book to the store.
 * Assigns an auto-incremented ID based on the current maximum ID + 1.
 * @param {Object} book - The book object to add (without id).
 * @returns {Object} The newly created book with its assigned ID.
 */
function addBook(book) {
  const newId = books.length > 0 ? Math.max(...books.map(b => b.id)) + 1 : 1;
  const newBook = { ...book, id: newId };
  books.push(newBook);
  return newBook;
}

/**
 * Update an existing book by ID.
 * @param {number} id - The ID of the book to update.
 * @param {Object} updates - Fields to update (partial object).
 * @returns {Object|undefined} The updated book if found, otherwise undefined.
 */
function updateBook(id, updates) {
  const index = books.findIndex(book => book.id === id);
  if (index === -1) return undefined;

  // Merge existing data with updates (spread operator creates a shallow copy)
  books[index] = { ...books[index], ...updates };
  return books[index];
}

/**
 * Delete a book by ID.
 * @param {number} id - The ID of the book to delete.
 * @returns {boolean} True if the book was found and deleted, false otherwise.
 */
function deleteBook(id) {
  const index = books.findIndex(book => book.id === id);
  if (index === -1) return false;

  books.splice(index, 1);
  return true;
}

/**
 * Export all data-access functions for use in route handlers.
 */
module.exports = {
  getAllBooks,
  getBookById,
  addBook,
  updateBook,
  deleteBook
};
```

**Key Concepts Explained:**  
- **Immutability:** `getAllBooks()` returns a copy (`[...books]`) so route handlers can't accidentally mutate the internal array.  
- **Auto-increment IDs:** Simple for learning; production systems use UUIDs to avoid collisions in distributed environments.  
- **Shallow merge on update:** `{ ...existing, ...updates }` allows partial updates (PATCH-like behavior) while preserving unchanged fields.

