## File 3: `middleware/errors.js` — Custom Error Classes & Middleware

```javascript
/**
 * @fileoverview Custom error classes and Express error-handling middleware.
 *
 * WHY CUSTOM ERROR CLASSES?
 * Standard JavaScript errors don't carry HTTP status codes or meaningful messages.
 * Custom classes let us attach statusCode, isOperational (to distinguish programming bugs
 * from expected errors), and a clear message — all in one object.
 *
 * WHY SEPARATE MIDDLEWARE?
 * Express has a special 4-argument error middleware signature: (err, req, res, next).
 * Placing it last ensures ALL routes funnel through this handler, providing centralized
 * error formatting and logging. This follows the "single responsibility" principle.
 */

/**
 * Base class for all application errors.
 * Extends Error to maintain compatibility with JavaScript's error handling.
 */
class AppError extends Error {
  /**
   * @param {string} message - Human-readable error description.
   * @param {number} statusCode - HTTP status code (e.g., 400, 404).
   */
  constructor(message, statusCode) {
    super(message); // Call parent Error constructor
    this.statusCode = statusCode;
    this.isOperational = true; // Expected error, not a bug

    // Capture stack trace for debugging (optional in production)
    Error.captureStackTrace(this, this.constructor);
  }
}

/**
 * 404 Not Found — Resource does not exist.
 */
class NotFoundError extends AppError {
  constructor(resource) {
    super(`${resource} not found`, 404);
  }
}

/**
 * 400 Bad Request — Invalid input data.
 */
class ValidationError extends AppError {
  constructor(message) {
    super(message, 400);
  }
}

/**
 * 500 Internal Server Error — Unexpected failure.
 */
class InternalServerError extends AppError {
  constructor(message = 'Internal server error') {
    super(message, 500);
  }
}

/**
 * Express error-handling middleware.
 * MUST be registered AFTER all routes (placed last in app.use() chain).
 *
 * @param {Error} err - The error object thrown by a route or middleware.
 * @param {Object} req - Express request object.
 * @param {Object} res - Express response object.
 * @param {Function} next - Express next function (unused here).
 */
function errorHandler(err, req, res, next) {
  // Log error for debugging (in production, use a proper logging service)
  console.error(`[ERROR] ${err.statusCode || 500}: ${err.message}`);

  // Build a consistent JSON response shape
  const response = {
    success: false,
    error: {
      message: err.message,
      statusCode: err.statusCode
    }
  };

  // Only include stack trace in development (security: don't leak internals in production)
  if (process.env.NODE_ENV !== 'production' && err.stack) {
    response.error.stack = err.stack;
  }

  res.status(err.statusCode || 500).json(response);
}

/**
 * Export error classes and middleware for use throughout the application.
 */
module.exports = {
  AppError,
  NotFoundError,
  ValidationError,
  InternalServerError,
  errorHandler
};
```

**Why This Pattern?**  
- **Centralized handling:** One place to format all errors → consistent API responses.  
- **`isOperational`:** Lets you distinguish between "user sent bad data" (expected) vs. "code has a bug" (unexpected).  
- **Stack trace security:** Hidden in production to prevent leaking internal paths/logic.

