## File 4: `routes/books.js` — Book Route Handlers

```javascript
/**
 * @fileoverview RESTful route handlers for book resources.
 *
 * REST CONVENTIONS USED:
 * - GET    /books       → List all books (with optional filtering)
 * - GET    /books/:id   → Get a single book by ID
 * - POST   /books       → Create a new book
 * - PUT    /books/:id   → Fully update an existing book
 * - DELETE /books/:id   → Delete a book by ID
 *
 * WHY ASYNC/AWAIT?
 * Even though we use synchronous in-memory operations now, wrapping handlers in async
 * functions prepares the code for future database integration (e.g., MongoDB, PostgreSQL)
 * where all I/O is asynchronous. It also allows us to use try/catch cleanly.
 */

const express = require('express');
const router = express.Router();

// Import data-access functions from our in-memory store
const {
  getAllBooks,
  getBookById,
  addBook,
  updateBook,
  deleteBook
} = require('../data/books');

// Import custom error classes for proper HTTP status codes
const { NotFoundError, ValidationError } = require('../middleware/errors');

/**
 * GET /books
 * List all books with optional filtering by genre, minRating, and search (title/author).
 *
 * QUERY PARAMETERS:
 * - genre: Filter by exact genre match (e.g., ?genre=Fiction)
 * - minRating: Minimum rating threshold (0-5, e.g., ?minRating=4.5)
 * - search: Keyword to search in title or author (case-insensitive)
 *
 * EXAMPLE REQUESTS:
 *   curl http://localhost:3000/books
 *   curl "http://localhost:3000/books?genre=Fiction&minRating=4.5"
 *   curl "http://localhost:3000/books?search=hobbit"
 */
router.get('/', (req, res) => {
  try {
    // Start with a full copy of all books
    let result = getAllBooks();

    // Apply genre filter if provided
    if (req.query.genre) {
      result = result.filter(book =>
        book.genre.toLowerCase() === req.query.genre.toLowerCase()
      );
    }

    // Apply minimum rating filter if provided
    if (req.query.minRating) {
      const minRating = parseFloat(req.query.minRating);
      if (isNaN(minRating)) {
        throw new ValidationError('Invalid minRating value. Must be a number between 0 and 5.');
      }
      result = result.filter(book => book.rating >= minRating);
    }

    // Apply search filter (matches title OR author, case-insensitive)
    if (req.query.search) {
      const searchTerm = req.query.search.toLowerCase();
      result = result.filter(book =>
        book.title.toLowerCase().includes(searchTerm) ||
        book.author.toLowerCase().includes(searchTerm)
      );
    }

    // Return filtered results with 200 OK
    res.status(200).json({
      success: true,
      count: result.length,
      data: result
    });
  } catch (error) {
    // Let Express error middleware handle it
    res.status(error.statusCode || 500).json({
      success: false,
      error: { message: error.message }
    });
  }
});

/**
 * GET /books/:id
 * Retrieve a single book by its unique ID.
 *
 * URL PARAMETER:
 * - id: Numeric book ID (e.g., /books/1)
 *
 * EXAMPLE REQUESTS:
 *   curl http://localhost:3000/books/1
 *   curl http://localhost:3000/books/999  → Returns 404
 */
router.get('/:id', (req, res) => {
  try {
    // Parse ID as integer; reject non-numeric IDs early
    const id = parseInt(req.params.id, 10);
    if (isNaN(id)) {
      throw new ValidationError('Invalid book ID. Must be a number.');
    }

    // Look up the book in our data store
    const book = getBookById(id);
    if (!book) {
      // Throw custom 404 error — caught by Express error middleware
      throw new NotFoundError('Book');
    }

    res.status(200).json({
      success: true,
      data: book
    });
  } catch (error) {
    res.status(error.statusCode || 500).json({
      success: false,
      error: { message: error.message }
    });
  }
});

/**
 * POST /books
 * Create a new book. Expects JSON body with title, author, genre, publishedYear, and rating.
 *
 * REQUEST BODY EXAMPLE:
 *   {
 *     "title": "Neuromancer",
 *     "author": "William Gibson",
 *     "genre": "Science Fiction",
 *     "publishedYear": 1984,
 *     "rating": 4.3
 *   }
 *
 * EXAMPLE REQUEST:
 *   curl -X POST http://localhost:3000/books \
 *        -H "Content-Type: application/json" \
 *        -d '{"title":"Neuromancer","author":"William Gibson","genre":"Science Fiction","publishedYear":1984,"rating":4.3}'
 */
router.post('/', (req, res) => {
  try {
    const { title, author, genre, publishedYear, rating } = req.body;

    // Validate required fields
    if (!title || !author || !genre) {
      throw new ValidationError('Missing required fields: title, author, and genre are required.');
    }

    // Validate numeric fields
    if (publishedYear === undefined || publishedYear === null) {
      throw new ValidationError('publishedYear is required.');
    }
    const year = parseInt(publishedYear, 10);
    if (isNaN(year) || year < 0 || year > new Date().getFullYear() + 1) {
      throw new ValidationError('publishedYear must be a valid year between 0 and current year + 1.');
    }

    if (rating === undefined || rating === null) {
      throw new ValidationError('rating is required.');
    }
    const bookRating = parseFloat(rating);
    if (isNaN(bookRating) || bookRating < 0 || bookRating > 5) {
      throw new ValidationError('rating must be a number between 0 and 5.');
    }

    // Create the book via our data store
    const newBook = addBook({
      title,
      author,
      genre,
      publishedYear: year,
      rating: bookRating
    });

    // Return 201 Created with the new resource
    res.status(201).json({
      success: true,
      data: newBook
    });
  } catch (error) {
    res.status(error.statusCode || 500).json({
      success: false,
      error: { message: error.message }
    });
  }
});

/**
 * PUT /books/:id
 * Fully update an existing book. All fields must be provided.
 *
 * URL PARAMETER: id — Book ID to update
 * REQUEST BODY: Complete book object (title, author, genre, publishedYear, rating)
 *
 * EXAMPLE REQUEST:
 *   curl -X PUT http://localhost:3000/books/1 \
 *        -H "Content-Type: application/json" \
 *        -d '{"title":"The Great Gatsby","author":"F. Scott Fitzgerald","genre":"Fiction","publishedYear":1925,"rating":4.7}'
 */
router.put('/:id', (req, res) => {
  try {
    const id = parseInt(req.params.id, 10);
    if (isNaN(id)) {
      throw new ValidationError('Invalid book ID. Must be a number.');
    }

    // Check if book exists before attempting update
    const existingBook = getBookById(id);
    if (!existingBook) {
      throw new NotFoundError('Book');
    }

    const { title, author, genre, publishedYear, rating } = req.body;

    // Validate all required fields (PUT requires full replacement)
    if (!title || !author || !genre) {
      throw new ValidationError('Missing required fields: title, author, and genre are required.');
    }

    const year = parseInt(publishedYear, 10);
    if (isNaN(year) || year < 0 || year > new Date().getFullYear() + 1) {
      throw new ValidationError('publishedYear must be a valid year between 0 and current year + 1.');
    }

    const bookRating = parseFloat(rating);
    if (isNaN(bookRating) || bookRating < 0 || bookRating > 5) {
      throw new ValidationError('rating must be a number between 0 and 5.');
    }

    // Perform the update
    const updatedBook = updateBook(id, { title, author, genre, publishedYear: year, rating: bookRating });

    res.status(200).json({
      success: true,
      data: updatedBook
    });
  } catch (error) {
    res.status(error.statusCode || 500).json({
      success: false,
      error: { message: error.message }
    });
  }
});

/**
 * DELETE /books/:id
 * Delete a book by its ID.
 *
 * EXAMPLE REQUESTS:
 *   curl -X DELETE http://localhost:3000/books/1
 *   curl -X DELETE http://localhost:3000/books/999  → Returns 404
 */
router.delete('/:id', (req, res) => {
  try {
    const id = parseInt(req.params.id, 10);
    if (isNaN(id)) {
      throw new ValidationError('Invalid book ID. Must be a number.');
    }

    // Check existence first for a meaningful error message
    const existingBook = getBookById(id);
    if (!existingBook) {
      throw new NotFoundError('Book');
    }

    // Delete the book
    const deleted = deleteBook(id);

    // Return 204 No Content (standard for successful DELETE with no response body)
    res.status(204).end();
  } catch (error) {
    res.status(error.statusCode || 500).json({
      success: false,
      error: { message: error.message }
    });
  }
});

module.exports = router;
```

**Design Decisions Explained:**  
- **Validation before DB operations:** Fail fast with clear messages instead of letting invalid data reach the store.  
- **201 for POST, 204 for DELETE:** Follows HTTP spec — 201 means "created," 204 means "deleted successfully, no body."  
- **parseInt + isNaN checks:** Prevents type-coercion bugs (e.g., `"/books/abc"` won't crash).

