## File 5: `routes/stats.js` — Statistics Endpoint

```javascript
/**
 * @fileoverview Statistics endpoint for book collection analytics.
 *
 * WHY A SEPARATE STATS ENDPOINT?
 * Keeping stats separate from CRUD routes follows REST principles: each resource has its own namespace.
 * /stats is a derived resource (computed from books), not a core entity, so it lives in its own route file.
 */

const express = require('express');
const router = express.Router();

// Import data-access functions
const { getAllBooks } = require('../data/books');

/**
 * GET /stats
 * Return aggregate statistics about the book collection.
 *
 * STATISTICS PROVIDED:
 * - totalBooks: Total number of books in the collection
 * - averageRating: Mean rating across all books (rounded to 2 decimals)
 * - genres: Object mapping each genre to its book count
 * - oldestBook: Title and year of the earliest published book
 * - newestBook: Title and year of the most recently published book
 *
 * EXAMPLE REQUEST:
 *   curl http://localhost:3000/stats
 *
 * EXAMPLE RESPONSE:
 *   {
 *     "success": true,
 *     "data": {
 *       "totalBooks": 5,
 *       "averageRating": 4.62,
 *       "genres": { "Fiction": 2, "Dystopian": 1, "Fantasy": 1, "Science Fiction": 1 },
 *       "oldestBook": { "title": "The Great Gatsby", "year": 1925 },
 *       "newestBook": { "title": "To Kill a Mockingbird", "year": 1960 }
 *     }
 *   }
 */
router.get('/', (req, res) => {
  try {
    const books = getAllBooks();

    // Handle empty collection gracefully
    if (books.length === 0) {
      return res.status(200).json({
        success: true,
        data: {
          totalBooks: 0,
          averageRating: 0,
          genres: {},
          oldestBook: null,
          newestBook: null
        }
      });
    }

    // Calculate average rating
    const totalRating = books.reduce((sum, book) => sum + book.rating, 0);
    const averageRating = parseFloat((totalRating / books.length).toFixed(2));

    // Count books per genre
    const genres = books.reduce((acc, book) => {
      acc[book.genre] = (acc[book.genre] || 0) + 1;
      return acc;
    }, {});

    // Find oldest and newest books by publishedYear
    const oldestBook = books.reduce((prev, current) =>
      prev.publishedYear < current.publishedYear ? prev : current
    );
    const newestBook = books.reduce((prev, current) =>
      prev.publishedYear > current.publishedYear ? prev : current
    );

    res.status(200).json({
      success: true,
      data: {
        totalBooks: books.length,
        averageRating,
        genres,
        oldestBook: {
          title: oldestBook.title,
          year: oldestBook.publishedYear
        },
        newestBook: {
          title: newestBook.title,
          year: newestBook.publishedYear
        }
      }
    });
  } catch (error) {
    res.status(500).json({
      success: false,
      error: { message: 'Failed to calculate statistics' }
    });
  }
});

module.exports = router;
```

**Why `reduce()` for stats?**  
- **Efficiency:** Single pass through the array for multiple calculations (average, genre counts, min/max).  
- **Functional style:** No mutable state — each reduce returns a new accumulator.

