## File 6: `server.js` — Express Application Entry Point

```javascript
/**
 * @fileoverview Main Express server that wires together routes, middleware, and error handling.
 *
 * MIDDLEWARE ORDER MATTERS IN EXPRESS:
 * 1. Body-parser (express.json()) — Parses incoming JSON request bodies
 * 2. Route handlers — Your application logic
 * 3. Error-handling middleware — Catches errors from routes
 *
 * WHY THIS ORDER?
 * Express executes middleware top-to-bottom. If error middleware were placed before routes,
 * it would never see route-generated errors. Body-parser must come first so routes can access req.body.
 */

const express = require('express');
const path = require('path');

// Import route modules
const bookRoutes = require('./routes/books');
const statsRoutes = require('./routes/stats');

// Import error-handling middleware
const { errorHandler } = require('./middleware/errors');

// Create Express application instance
const app = express();

// Set port from environment variable or default to 3000
const PORT = process.env.PORT || 3000;

/**
 * MIDDLEWARE: Parse JSON request bodies.
 * Without this, req.body would be undefined for POST/PUT requests.
 */
app.use(express.json());

/**
 * MIDDLEWARE: Log every request (useful for debugging).
 * In production, consider using a proper logging library like winston or pino.
 */
app.use((req, res, next) => {
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.url}`);
  next(); // Pass control to the next middleware/route
});

/**
 * ROUTES: Mount route handlers under their respective namespaces.
 * - /books → all book CRUD operations
 * - /stats → statistics endpoint
 */
app.use('/books', bookRoutes);
app.use('/stats', statsRoutes);

/**
 * ROOT ROUTE: Welcome message for API discovery.
 */
app.get('/', (req, res) => {
  res.json({
    success: true,
    message: '📚 Book REST API is running!',
    endpoints: {
      books: {
        list: 'GET /books',
        getById: 'GET /books/:id',
        create: 'POST /books',
        update: 'PUT /books/:id',
        delete: 'DELETE /books/:id'
      },
      stats: 'GET /stats'
    }
  });
});

/**
 * 404 HANDLER: Catch-all for undefined routes.
 * Placed AFTER all route definitions so it only catches truly missing paths.
 */
app.use((req, res) => {
  res.status(404).json({
    success: false,
    error: { message: `Route ${req.method} ${req.url} not found` }
  });
});

/**
 * ERROR HANDLING MIDDLEWARE: Centralized error formatter.
 * MUST be the LAST middleware (after all routes and 404 handler).
 * Express recognizes this by its 4-parameter signature.
 */
app.use(errorHandler);

/**
 * START THE SERVER
 */
app.listen(PORT, () => {
  console.log(`✅ Server running on http://localhost:${PORT}`);
  console.log(`📖 API Documentation: http://localhost:${PORT}`);
});

module.exports = app;
```

**Critical Concepts:**  
- **`app.use()` order:** Middleware executes in registration order. Error handler last → catches everything.  
- **4-parameter error middleware:** Express only routes errors to functions with `(err, req, res, next)` signature.  
- **Environment variables:** `process.env.PORT` allows deployment platforms (Heroku, etc.) to override the port.

