## Arquivo 2: `src/models/bookStore.js`

```javascript
/**
 * @fileoverview Armazenamento em memória dos livros.
 *
 * Escolha da estrutura de dados: usamos um ARRAY simples porque:
 *   1. Para fins educacionais, arrays são mais intuitivos que objetos/mapas.
 *   2. O volume de dados é pequeno (biblioteca fictícia), então a complexidade
 *      O(n) de buscas lineares é irrelevante.
 *   3. Arrays preservam ordem de inserção, o que facilita a listagem cronológica.
 *
 * Em produção, substituiríamos por um banco de dados relacional (PostgreSQL)
 * ou NoSQL (MongoDB), com índices adequados para consultas frequentes.
 */

/**
 * @typedef {Object} Book
 * @property {number} id - Identificador único auto-incrementado.
 * @property {string} title - Título do livro (obrigatório, 1-200 caracteres).
 * @property {string} author - Autor do livro (obrigatório, 1-150 caracteres).
 * @property {number} [year] - Ano de publicação (opcional, 1000-2099).
 * @property {string} [genre] - Gênero literário (opcional, ex: "Ficção", "Não-ficção").
 * @property {boolean} [available] - Disponibilidade para empréstimo (padrão: true).
 * @property {string} createdAt - Timestamp ISO da criação.
 * @property {string} updatedAt - Timestamp ISO da última atualização.
 */

/**
 * Array em memória que armazena todos os livros.
 * Inicializamos com alguns registros de exemplo para facilitar testes imediatos.
 *
 * Por que inicializar com dados? Para que o endpoint GET /books retorne resultados
 * sem necessidade de criar livros manualmente primeiro — útil para demonstrações.
 */
const books = [
  {
    id: 1,
    title: "Dom Casmurro",
    author: "Machado de Assis",
    year: 1899,
    genre: "Romance",
    available: true,
    createdAt: new Date().toISOString(),
    updatedAt: new Date().toISOString()
  },
  {
    id: 2,
    title: "O Senhor dos Anéis",
    author: "J.R.R. Tolkien",
    year: 1954,
    genre: "Fantasia",
    available: false,
    createdAt: new Date().toISOString(),
    updatedAt: new Date().toISOString()
  },
  {
    id: 3,
    title: "1984",
    author: "George Orwell",
    year: 1949,
    genre: "Distopia",
    available: true,
    createdAt: new Date().toISOString(),
    updatedAt: new Date().toISOString()
  }
];

/**
 * Contador interno para geração de IDs únicos.
 * Usamos um contador em vez de UUIDs porque:
 *   - IDs numéricos são mais legíveis e compactos (boa prática REST).
 *   - Evita colisões sem necessidade de bibliotecas externas.
 *   - Em arrays pequenos, a verificação de unicidade é barata o suficiente.
 */
let nextId = 4;

/**
 * Retorna uma cópia profunda do array de livros.
 * Sempre retornamos cópias para evitar mutação acidental pelo chamador.
 *
 * @returns {Book[]} Cópia dos livros armazenados.
 */
function getAll() {
  return books.map(book => ({ ...book }));
}

/**
 * Busca um livro por ID usando busca linear.
 * Para arrays grandes, poderíamos usar um Map<id, Book> para O(1).
 *
 * @param {number} id - ID do livro a ser encontrado.
 * @returns {Book | undefined} Livro encontrado ou undefined se não existir.
 */
function getById(id) {
  const index = books.findIndex(book => book.id === id);
  if (index === -1) return undefined;
  return { ...books[index] }; // Retorna cópia para imutabilidade
}

/**
 * Cria um novo livro no array e retorna uma cópia.
 * O timestamp de criação é definido no momento da inserção.
 *
 * @param {Omit<Book, 'id' | 'createdAt' | 'updatedAt'>} bookData - Dados do livro.
 * @returns {Book} Livro criado com ID e timestamps atribuídos.
 */
function create(bookData) {
  const newBook = {
    id: nextId++,
    ...bookData,
    available: bookData.available ?? true, // Padrão: disponível
    createdAt: new Date().toISOString(),
    updatedAt: new Date().toISOString()
  };
  books.push(newBook);
  return { ...newBook };
}

/**
 * Atualiza um livro existente pelo ID.
 * Se o livro não existir, retorna undefined.
 * O timestamp updatedAt é atualizado automaticamente.
 *
 * @param {number} id - ID do livro a atualizar.
 * @param {Partial<Omit<Book, 'id' | 'createdAt'>>} updates - Campos a atualizar.
 * @returns {Book | undefined} Livro atualizado ou undefined se não encontrado.
 */
function update(id, updates) {
  const index = books.findIndex(book => book.id === id);
  if (index === -1) return undefined;

  // Mescla os dados existentes com as atualizações (exceção: campos de sistema)
  books[index] = {
    ...books[index],
    ...updates,
    id, // Garante que o ID não seja alterado
    updatedAt: new Date().toISOString()
  };

  return { ...books[index] };
}

/**
 * Remove um livro do array pelo ID.
 * Retorna true se removido com sucesso, false caso contrário.
 *
 * @param {number} id - ID do livro a remover.
 * @returns {boolean} True se removido, false se não encontrado.
 */
function remove(id) {
  const index = books.findIndex(book => book.id === id);
  if (index === -1) return false;
  books.splice(index, 1);
  return true;
}

/**
 * Exporta todas as funções do store como um módulo.
 * Usamos exports nominais para clareza e facilidade de importação seletiva.
 */
module.exports = { getAll, getById, create, update, remove };
```

