## Arquivo 3: `src/middleware/errorHandler.js`

```javascript
/**
 * @fileoverview Middleware centralizado de tratamento de erros.
 *
 * Por que um middleware dedicado?
 *   - Centraliza a lógica de formatação de erros, evitando repetição.
 *   - Permite diferentes estratégias de resposta (JSON, HTML, logs).
 *   - Facilita o teste unitário da camada de erro isoladamente.
 *
 * O Express identifica middlewares de erro pela assinatura:
 *   (err, req, res, next) => {}  — note os 4 parâmetros obrigatórios.
 */

/**
 * Classe base para erros personalizados da API.
 * Herdar de Error garante compatibilidade com stack traces nativos do Node.js.
 *
 * @extends Error
 */
class ApiError extends Error {
  /**
   * @param {number} statusCode - Código HTTP da resposta (4xx = cliente, 5xx = servidor).
   * @param {string} message - Mensagem de erro legível para o consumidor da API.
   * @param {string[]} [errors] - Lista opcional de erros detalhados (para validação).
   */
  constructor(statusCode, message, errors) {
    super(message); // Chama construtor de Error com a mensagem
    this.statusCode = statusCode;
    this.errors = errors || [];

    // Mantém o stack trace correto mesmo após herança customizada
    if (Error.captureStackTrace) {
      Error.captureStackTrace(this, this.constructor);
    }
  }
}

/**
 * Erro para recursos não encontrados.
 * Convenção REST: 404 Not Found indica que o recurso solicitado não existe.
 */
class NotFoundError extends ApiError {
  constructor(resource, id) {
    super(404, `${resource} com ID ${id} não encontrado`);
    this.resource = resource;
    this.id = id;
  }
}

/**
 * Erro para dados de entrada inválidos.
 * Convenção REST: 400 Bad Request indica que o cliente enviou dados incorretos.
 */
class ValidationError extends ApiError {
  constructor(message, errors) {
    super(400, message || "Dados de entrada inválidos", errors);
  }
}

/**
 * Erro para operações não permitidas.
 * Convenção REST: 405 Method Not Allowed indica que o método HTTP é inválido.
 */
class MethodNotAllowedError extends ApiError {
  constructor(method) {
    super(405, `Método ${method} não permitido para este endpoint`);
  }
}

/**
 * Middleware de tratamento de erros global.
 * Deve ser registrado APÓS todas as rotas para capturar erros lançados durante o processamento.
 *
 * @param {Error} err - Instância de ApiError (ou Error genérico) capturada pelo Express.
 * @param {import('express').Request} req - Objeto de requisição Express.
 * @param {import('express').Response} res - Objeto de resposta Express.
 * @param {import('express').NextFunction} next - Função next do middleware chain.
 */
function errorHandler(err, req, res, next) {
  // Fallback para erros não classificados (500 Internal Server Error)
  const statusCode = err.statusCode || 500;
  const isClientError = statusCode >= 400 && statusCode < 500;

  // Log do erro no servidor — importante para debugging em produção
  console.error(`[${new Date().toISOString()}] ${err.name}: ${err.message}`);
  if (err.errors?.length > 0) {
    console.error("Detalhes:", JSON.stringify(err.errors, null, 2));
  }

  // Resposta padronizada em JSON seguindo convenções REST
  res.status(statusCode).json({
    success: false,
    error: {
      type: err.name,
      message: err.message,
      ...(isClientError && err.errors?.length > 0
        ? { details: err.errors } // Inclui detalhes apenas para erros do cliente
        : {}),
      ...(process.env.NODE_ENV === "development"
        ? { stack: err.stack } // Stack trace apenas em desenvolvimento (segurança)
        : {})
    },
    timestamp: new Date().toISOString(),
    path: req.originalUrl,
    method: req.method
  });
}

/**
 * Middleware para capturar rotas inexistentes (404).
 * Colocado após todas as rotas definidas — se nenhuma rota corresponder,
 * o Express continua o chain e este middleware intercepta.
 *
 * @param {import('express').Request} req
 * @param {import('express').Response} res
 * @param {import('express').NextFunction} next
 */
function notFoundHandler(req, res, next) {
  // Só lançamos erro se a rota existir mas o método for inválido;
  // caso contrário, é uma rota realmente inexistente.
  next(new NotFoundError("Rota", req.originalUrl));
}

module.exports = {
  ApiError,
  NotFoundError,
  ValidationError,
  MethodNotAllowedError,
  errorHandler,
  notFoundHandler
};
```

