## Arquivo 4: `src/middleware/validate.js`

```javascript
/**
 * @fileoverview Middleware de validação de entrada para criação e atualização de livros.
 *
 * Por que validar no middleware e não no controller?
 *   - Separação de responsabilidades: o controller foca na lógica de negócio,
 *     o middleware garante a qualidade dos dados antes de qualquer processamento.
 *   - Reusabilidade: a mesma validação pode ser aplicada em múltiplos endpoints.
 *   - Feedback imediato ao cliente com mensagens claras sobre o que está errado.
 */

const { ValidationError } = require("./errorHandler");

/**
 * Regras de validação para criação de livro (POST /books).
 * Todos os campos são obrigatórios exceto year, genre e available.
 *
 * @type {Object<string, Function>} Mapeamento campo -> função validadora.
 */
const createRules = {
  title: (value) => {
    if (typeof value !== "string" || value.trim().length === 0) {
      return "Título é obrigatório e deve ser uma string não vazia";
    }
    if (value.length > 200) return "Título deve ter no máximo 200 caracteres";
    return null; // null = válido
  },
  author: (value) => {
    if (typeof value !== "string" || value.trim().length === 0) {
      return "Autor é obrigatório e deve ser uma string não vazia";
    }
    if (value.length > 150) return "Autor deve ter no máximo 150 caracteres";
    return null;
  },
  year: (value) => {
    if (value === undefined || value === null) return null; // Opcional
    const num = Number(value);
    if (!Number.isInteger(num)) return "Ano deve ser um número inteiro";
    if (num < 1000 || num > 2099) return "Ano deve estar entre 1000 e 2099";
    return null;
  },
  genre: (value) => {
    if (value === undefined || value === null) return null; // Opcional
    if (typeof value !== "string" || value.trim().length === 0) {
      return "Gênero deve ser uma string não vazia";
    }
    return null;
  },
  available: (value) => {
    if (value === undefined || value === null) return null; // Opcional
    if (typeof value !== "boolean") return "Disponibilidade deve ser um booleano";
    return null;
  }
};

/**
 * Regras de validação para atualização parcial (PUT /books/:id).
 * Todos os campos são opcionais — apenas os enviados serão validados.
 *
 * @type {Object<string, Function>}
 */
const updateRules = {
  title: createRules.title,
  author: createRules.author,
  year: createRules.year,
  genre: createRules.genre,
  available: createRules.available
};

/**
 * Middleware que valida os campos do corpo da requisição (req.body).
 * Lança ValidationError com todos os erros acumulados se houver qualquer invalidação.
 *
 * @param {Object} rules - Regras de validação (createRules ou updateRules).
 * @returns {Function} Middleware Express.
 */
function validateBody(rules) {
  return (req, res, next) => {
    const errors = [];

    for (const [field, validator] of Object.entries(rules)) {
      const value = req.body[field];
      // Para update: campos não enviados são ignorados (undefined)
      if (field !== "title" && field !== "author" && value === undefined) continue;
      const error = validator(value);
      if (error) errors.push({ field, message: error });
    }

    if (errors.length > 0) {
      return next(new ValidationError("Validação falhou", errors));
    }

    // Limpa campos whitespace de strings
    for (const field of ["title", "author", "genre"]) {
      if (typeof req.body[field] === "string") {
        req.body[field] = req.body[field].trim();
      }
    }

    next();
  };
}

/**
 * Middleware que valida se o parâmetro de rota :id é um número inteiro válido.
 * Express passa params como strings, então fazemos a conversão e verificação.
 *
 * @returns {Function} Middleware Express.
 */
function validateIdParam() {
  return (req, res, next) => {
    const id = Number(req.params.id);
    if (!Number.isInteger(id) || id < 1) {
      return next(new ValidationError("ID inválido", [
        { field: "id", message: "O ID deve ser um número inteiro positivo" }
      ]));
    }
    // Converte para number para uso posterior nos controllers
    req.params.id = id;
    next();
  };
}

module.exports = { validateBody, validateIdParam, createRules, updateRules };
```

