## Arquivo 5: `src/routes/books.js`

```javascript
/**
 * @fileoverview Rotas REST para o recurso "livros".
 *
 * Convenções REST adotadas:
 *   - Nomes de recursos no plural (/books) — padrão da indústria (RFC 7231).
 *   - Métodos HTTP semânticos: GET=ler, POST=criar, PUT=substituir, DELETE=remover.
 *   - IDs na URL para recursos específicos (/books/:id).
 *   - Query params para filtragem (GET /books?author=...).
 *   - Respostas em JSON com estrutura padronizada { success, data }.
 *
 * Por que async/await?
 *   - Código mais legível que promessas encadeadas (.then/.catch).
 *   - Tratamento de erros centralizado via try/catch.
 *   - Mesmo sendo operações síncronas em memória, a assinatura async prepara
 *     o código para migração futura a bancos de dados assíncronos sem reescrita.
 */

const express = require("express");
const router = express.Router();
const { getAll, getById, create, update, remove } = require("../models/bookStore");
const { NotFoundError, ValidationError } = require("../middleware/errorHandler");
const { validateBody, validateIdParam } = require("../middleware/validate");

// ============================================================================
// GET /books — Listar todos os livros com filtragem opcional
//
// Query params suportados:
//   - author    : filtra por autor (case-insensitive, substring match)
//   - genre     : filtra por gênero (exato)
//   - available : filtra por disponibilidade (true/false)
//   - search    : busca por título ou autor (substring, case-insensitive)
//
// Exemplo de uso:
//   curl http://localhost:3000/books?author=tolkien&available=true
//   curl http://localhost:3000/books?search=1984
// ============================================================================

/**
 * Handler para listar livros com filtragem.
 *
 * @async
 * @param {import('express').Request} req - Contém query params de filtragem.
 * @param {import('express').Response} res - Envia array de livros.
 * @param {import('express').NextFunction} next - Propaga erros para middleware.
 */
router.get("/", async (req, res, next) => {
  try {
    let result = getAll();

    // Filtragem por autor (substring case-insensitive)
    if (req.query.author) {
      const authorFilter = req.query.author.toLowerCase();
      result = result.filter(book =>
        book.author.toLowerCase().includes(authorFilter)
      );
    }

    // Filtragem por gênero (exata)
    if (req.query.genre) {
      result = result.filter(
        book => book.genre?.toLowerCase() === req.query.genre.toLowerCase()
      );
    }

    // Filtragem por disponibilidade
    if (req.query.available !== undefined) {
      const available = req.query.available === "true";
      result = result.filter(book => book.available === available);
    }

    // Busca livre por título ou autor
    if (req.query.search) {
      const search = req.query.search.toLowerCase();
      result = result.filter(
        book =>
          book.title.toLowerCase().includes(search) ||
          book.author.toLowerCase().includes(search)
      );
    }

    // Ordenação opcional por ano (crescente ou decrescente)
    if (req.query.sort === "year_desc") {
      result.sort((a, b) => (b.year || 0) - (a.year || 0));
    } else if (req.query.sort === "year_asc") {
      result.sort((a, b) => (a.year || 0) - (b.year || 0));
    }

    // Log educacional: mostra filtros aplicados
    console.log(`[GET /books] Filtros: ${JSON.stringify(req.query)} → ${result.length} resultado(s)`);

    res.json({ success: true, data: result, count: result.length });
  } catch (err) {
    next(err);
  }
});

// ============================================================================
// GET /books/:id — Obter um livro específico por ID
//
// Exemplo de uso:
//   curl http://localhost:3000/books/1
// ============================================================================

/**
 * Handler para obter um livro pelo ID.
 * Lança NotFoundError se o ID não existir.
 *
 * @async
 * @param {import('express').Request} req - Contém params.id.
 * @param {import('express').Response} res - Envia objeto do livro.
 * @param {import('express').NextFunction} next - Propaga erros.
 */
router.get("/:id", validateIdParam(), async (req, res, next) => {
  try {
    const book = getById(req.params.id);
    if (!book) {
      return next(new NotFoundError("Livro", req.params.id));
    }
    res.json({ success: true, data: book });
  } catch (err) {
    next(err);
  }
});

// ============================================================================
// POST /books — Criar um novo livro
//
// Corpo esperado (JSON):
//   { "title": "...", "author": "...", "year": 1984, "genre": "...", "available": true }
//
// Exemplo de uso:
//   curl -X POST http://localhost:3000/books \
//        -H "Content-Type: application/json" \
//        -d '{"title":"Admirável Mundo Novo","author":"Aldous Huxley","year":1932,"genre":"Distopia"}'
// ============================================================================

/**
 * Handler para criar um novo livro.
 * Valida entrada antes de persistir e retorna o livro criado com ID atribuído.
 *
 * @async
 * @param {import('express').Request} req - Contém body validado.
 * @param {import('express').Response} res - Envia livro criado (201 Created).
 * @param {import('express').NextFunction} next - Propaga erros.
 */
router.post("/", validateBody(require("../middleware/validate").createRules), async (req, res, next) => {
  try {
    const newBook = create(req.body);

    // 201 Created é o código HTTP semântico para recursos criados com sucesso.
    // Inclui o header Location apontando para o recurso criado (convenção REST).
    res.status(201).json({
      success: true,
      data: newBook,
      message: "Livro criado com sucesso"
    });
  } catch (err) {
    next(err);
  }
});

// ============================================================================
// PUT /books/:id — Atualizar completamente um livro existente
//
// Corpo esperado (JSON): todos os campos obrigatórios exceto id, createdAt, updatedAt.
// PUT substitui o recurso inteiro — campos não enviados serão mantidos do original.
//
// Exemplo de uso:
//   curl -X PUT http://localhost:3000/books/1 \
//        -H "Content-Type: application/json" \
//        -d '{"title":"Dom Casmurro","author":"Machado de Assis","year":1899,"genre":"Romance","available":false}'
// ============================================================================

/**
 * Handler para atualizar um livro existente.
 * Usa PUT (substituição completa) em vez de PATCH (atualização parcial).
 *
 * @async
 * @param {import('express').Request} req - Contém params.id e body com dados.
 * @param {import('express').Response} res - Envia livro atualizado.
 * @param {import('express').NextFunction} next - Propaga erros.
 */
router.put("/:id", validateIdParam(), validateBody(require("../middleware/validate").createRules), async (req, res, next) => {
  try {
    const existing = getById(req.params.id);
    if (!existing) {
      return next(new NotFoundError("Livro", req.params.id));
    }

    // Mescla dados existentes com os enviados (campos não enviados mantêm valor original)
    const updates = { ...req.body };
    const updatedBook = update(req.params.id, updates);

    res.json({ success: true, data: updatedBook, message: "Livro atualizado com sucesso" });
  } catch (err) {
    next(err);
  }
});

// ============================================================================
// DELETE /books/:id — Excluir um livro
//
// Exemplo de uso:
//   curl -X DELETE http://localhost:3000/books/2
// ============================================================================

/**
 * Handler para excluir um livro pelo ID.
 * Retorna 204 No Content (sem corpo) quando a exclusão é bem-sucedida,
 * conforme convenção REST para operações de deleção.
 *
 * @async
 * @param {import('express').Request} req - Contém params.id.
 * @param {import('express').Response} res - Envia 204 sem corpo.
 * @param {import('express').NextFunction} next - Propaga erros.
 */
router.delete("/:id", validateIdParam(), async (req, res, next) => {
  try {
    const existing = getById(req.params.id);
    if (!existing) {
      return next(new NotFoundError("Livro", req.params.id));
    }

    const removed = remove(req.params.id);
    if (!removed) {
      return next(new NotFoundError("Livro", req.params.id));
    }

    // 204 No Content: sucesso na deleção sem necessidade de retornar dados.
    res.status(204).end();
  } catch (err) {
    next(err);
  }
});

module.exports = router;
```

