```javascript
/**
 * @fileoverview Rotas para estatísticas da biblioteca.
 *
 * Por que uma rota separada?
 *   - Estatísticas não são um recurso CRUD tradicional — usam GET mas retornam
 *     dados agregados, não entidades individuais.
 *   - Separação de responsabilidades: rotas de livros focam em CRUD, esta rota
 *     foca em análise de dados.
 *   - Facilita a adição futura de métricas adicionais sem poluir as rotas principais.
 */

const express = require("express");
const router = express.Router();
const { getAll } = require("../models/bookStore");

// ============================================================================
// GET /stats — Retornar estatísticas da biblioteca
//
// Resposta inclui:
//   - totalBooks       : número total de livros cadastrados
//   - availableBooks   : livros disponíveis para empréstimo
//   - unavailableBooks : livros indisponíveis
//   - booksByGenre     : contagem por gênero (objeto)
//   - booksByAuthor    : top 5 autores com mais livros
//   - oldestBook       : livro mais antigo (por year)
//   - newestBook       : livro mais recente (por year)
//
// Exemplo de uso:
//   curl http://localhost:3000/stats
// ============================================================================

/**
 * Handler para calcular e retornar estatísticas da biblioteca.
 * Todas as contagens são feitas em memória a partir do array de livros.
 *
 * @async
 * @param {import('express').Request} req - Requisição (sem params especiais).
 * @param {import('express').Response} res - Envia objeto de estatísticas.
 * @param {import('express').NextFunction} next - Propaga erros.
 */
router.get("/", async (req, res, next) => {
  try {
    const books = getAll();

    // Total de livros
    const totalBooks = books.length;

    // Livros disponíveis vs indisponíveis
    const availableBooks = books.filter(b => b.available).length;
    const unavailableBooks = totalBooks - availableBooks;

    // Contagem por gênero — usamos reduce para construir o mapa em uma passada O(n)
    const booksByGenre = books.reduce((acc, book) => {
      const genre = book.genre || "Sem gênero";
      acc[genre] = (acc[genre] || 0) + 1;
      return acc;
    }, {});

    // Top autores por quantidade de livros
    // Usamos reduce para agrupar, depois sort para ordenar — O(n log n) no pior caso.
    const authorCounts = books.reduce((acc, book) => {
      acc[book.author] = (acc[book.author] || 0) + 1;
      return acc;
    }, {});

    const topAuthors = Object.entries(authorCounts)
      .sort((a, b) => b[1] - a[1]) // Ordena decrescente por contagem
      .slice(0, 5)                 // Top 5 apenas
      .map(([author, count]) => ({ author, count }));

    // Livro mais antigo e mais recente (por year)
    const booksWithYear = books.filter(b => b.year);
    const oldestBook = booksWithYear.length > 0
      ? booksWithYear.reduce((min, b) => (!min.year || b.year < min.year ? b : min))
      : null;

    const newestBook = booksWithYear.length > 0
      ? booksWithYear.reduce((max, b) => (!max.year || b.year > max.year ? b : max))
      : null;

    res.json({
      success: true,
      data: {
        totalBooks,
        availableBooks,
        unavailableBooks,
        availabilityRate: totalBooks > 0
          ? parseFloat(((availableBooks / totalBooks) * 100).toFixed(2))
          : 0,
        booksByGenre,
        topAuthors,
        oldestBook: oldestBook ? { title: oldestBook.title, author: oldestBook.author, year: oldestBook.year } : null,
        newestBook: newestBook ? { title: newestBook.title, author: newestBook.author, year: newestBook.year } : null,
        generatedAt: new Date().toISOString()
      }
    });
  } catch (err) {
    next(err);
  }
});

module.exports = router;
```

