## Arquivo 7: `src/app.js`

```javascript
/**
 * @fileoverview Ponto de entrada da aplicação Express.
 *
 * Arquitetura adotada:
 *   1. Configuração do Express (parsers, CORS básico).
 *   2. Registro das rotas como middlewares.
 *   3. Middleware de tratamento de erros (deve ser o último).
 *   4. Inicialização do servidor na porta configurada.
 *
 * Por que usar express.json() e express.urlencoded()?
 *   - Express não faz parsing automático do corpo das requisições.
 *   - express.json() converte JSON do body em objeto JavaScript (req.body).
 *   - express.urlencoded() permite formulários HTML com encoding URL.
 *   - Sem esses middlewares, req.body seria undefined e a validação falharia.
 */

const express = require("express");
const bookRoutes = require("./routes/books");
const statsRoutes = require("./routes/stats");
const { errorHandler, notFoundHandler } = require("./middleware/errorHandler");

// Cria a aplicação Express — instância única que gerencia o roteamento e middlewares.
const app = express();

// ============================================================================
// Configuração dos middlewares globais
// ============================================================================

/**
 * Parser de JSON com limite de 100KB por corpo.
 * O limite previne ataques de negação de serviço (DoS) via payloads gigantes.
 */
app.use(express.json({ limit: "100kb" }));

/**
 * Parser de formulários URL-encoded (para compatibilidade com testes manuais).
 */
app.use(express.urlencoded({ extended: true, limit: "100kb" }));

// ============================================================================
// Registro das rotas
//
 * Por que registrar rotas como app.use('/prefixo', router)?
 *   - O Express encadeia middlewares em ordem de registro.
 *   - Rotas são middlewares especiais que correspondem a métodos + caminhos.
 *   - Separar em routers (arquivos distintos) mantém o código modular e testável.
 * ============================================================================

/**
 * Rota principal para demonstração — retorna informações sobre a API.
 * Útil para descoberta automática (conceito de HATEOAS simplificado).
 */
app.get("/", (req, res) => {
  res.json({
    success: true,
    message: "API de Livros — Exemplo Educacional",
    version: "1.0.0",
    endpoints: {
      books: {
        list: "GET /books",
        getById: "GET /books/:id",
        create: "POST /books",
        update: "PUT /books/:id",
        delete: "DELETE /books/:id"
      },
      stats: "GET /stats"
    },
    examples: {
      listAll: 'curl http://localhost:3000/books',
      filterByAuthor: 'curl "http://localhost:3000/books?author=tolkien"',
      createBook: `curl -X POST http://localhost:3000/books \\
  -H "Content-Type: application/json" \\
  -d '{"title":"O Hobbit","author":"J.R.R. Tolkien","year":1937,"genre":"Fantasia"}'`,
      getStats: 'curl http://localhost:3000/stats'
    }
  });
});

// Registra as rotas de livros e estatísticas nos respectivos prefixos.
app.use("/books", bookRoutes);
app.use("/stats", statsRoutes);

// ============================================================================
// Middlewares de tratamento de erros (ordem importa!)
// ============================================================================

/**
 * Middleware 404 para rotas inexistentes.
 * Deve vir APÓS todas as rotas definidas — caso contrário, interceptaria tudo.
 */
app.use(notFoundHandler);

/**
 * Middleware global de tratamento de erros.
 * Captura erros lançados por qualquer middleware/rota anterior.
 * Assinatura com 4 parâmetros é o que diferencia middlewares de erro no Express.
 */
app.use(errorHandler);

// ============================================================================
// Inicialização do servidor
// ============================================================================

/**
 * Porta padrão: 3000 para desenvolvimento, pode ser sobrescrita por variável de ambiente.
 * A lógica de inicialização é envolta em try/catch para tratamento limpo de falhas.
 */
const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  console.log(`✅ Servidor rodando em http://localhost:${PORT}`);
  console.log(`📚 API de Livros — Exemplo Educacional`);
  console.log(`📖 Endpoints disponíveis:`);
  console.log(`   GET    http://localhost:${PORT}/          — Documentação da API`);
  console.log(`   GET    http://localhost:${PORT}/books     — Listar livros`);
  console.log(`   POST   http://localhost:${PORT}/books     — Criar livro`);
  console.log(`   PUT    http://localhost:${PORT}/books/:id — Atualizar livro`);
  console.log(`   DELETE http://localhost:${PORT}/books/:id — Excluir livro`);
  console.log(`   GET    http://localhost:${PORT}/stats     — Estatísticas`);
});

module.exports = app;
```

