## 2️⃣ `server.js` — Complete Application Code

```javascript
/**
 * ============================================================================
 * BOOK REST API — EDUCATIONAL EXAMPLE (VERBOSE STYLE)
 * ============================================================================
 * 
 * This file implements a complete REST API for managing books with:
 *   - In-memory storage using an array of objects
 *   - Full CRUD operations (Create, Read, Update, Delete)
 *   - Filtering and statistics endpoints
 *   - Custom error classes and middleware
 *   - Comprehensive JSDoc documentation
 * 
 * Design choices explained throughout the code.
 */

// ============================================================================
// SECTION 1: IMPORTS & CONFIGURATION
// ============================================================================

/**
 * Import Express — the web framework that handles routing, middleware, and
 * request/response lifecycle. We destructure only what we need to keep the
 * namespace clean.
 */
const express = require('express');

/**
 * Import CORS middleware to allow cross-origin requests during development.
 * In production, you would configure this more restrictively (specific origins,
 * methods, headers).
 */
const cors = require('cors');

/**
 * Create an Express application instance. This is the heart of our API — all
 * routes and middleware are attached to this object.
 */
const app = express();

/**
 * Configure the port for the server. We use process.env.PORT with a fallback
 * to 3000 so the app can be deployed on platforms like Heroku (which set PORT)
 * while still working locally without configuration.
 */
const PORT = process.env.PORT || 3000;

// ============================================================================
// SECTION 2: MIDDLEWARE SETUP
// ============================================================================

/**
 * Middleware: Parse JSON request bodies.
 * 
 * WHY THIS IS NECESSARY:
 * When a client sends a POST or PUT request with JSON data (e.g., creating a
 * book), Express needs to parse the raw HTTP body into a JavaScript object.
 * Without this middleware, req.body would be undefined.
 * 
 * LIMITATION: This only handles application/json content type. For file uploads
 * or form data, we'd need additional parsers like multer or express-formidable.
 */
app.use(express.json());

/**
 * Middleware: Enable CORS with default settings.
 * 
 * WHY THIS IS NECESSARY:
 * Browsers enforce the Same-Origin Policy, which blocks requests to different
 * domains/ports by default. During development (e.g., testing from a browser
 * console or Postman), we need CORS enabled so our API can be accessed freely.
 * 
 * SECURITY NOTE: In production, replace this with specific origin configuration:
 *   app.use(cors({ origin: 'https://yourdomain.com', methods: ['GET', 'POST'] }))
 */
app.use(cors());

/**
 * Middleware: Log every request for debugging and monitoring.
 * 
 * WHY THIS PATTERN:
 * Request logging is a standard practice in production APIs. It helps with:
 *   - Debugging issues by tracing request flow
 *   - Monitoring API usage patterns
 *   - Auditing security events
 * 
 * The log format includes timestamp, HTTP method, URL, and response status.
 */
app.use((req, res, next) => {
  const timestamp = new Date().toISOString();
  console.log(`[${timestamp}] ${req.method} ${req.url}`);
  next(); // Pass control to the next middleware/route handler
});

// ============================================================================
// SECTION 3: CUSTOM ERROR CLASSES
// ============================================================================

/**
 * Custom Error Class: NotFoundError
 * 
 * WHY CUSTOM ERRORS:
 * Standard JavaScript Error objects don't carry HTTP status codes. By creating
 * custom error classes, we can attach a statusCode property that our error
 * handling middleware can read to return the appropriate HTTP response.
 * 
 * This follows the "fail fast" principle — if a resource isn't found, we throw
 * immediately rather than checking return values everywhere.
 */
class NotFoundError extends Error {
  /**
   * @param {string} message - Human-readable error description
   * @param {number} statusCode - HTTP status code (default: 404)
   */
  constructor(message = 'Resource not found', statusCode = 404) {
    super(message); // Call parent Error constructor with the message
    this.statusCode = statusCode; // Attach HTTP status for middleware to use
    this.name = 'NotFoundError'; // Helpful for debugging stack traces
  }
}

/**
 * Custom Error Class: ValidationError
 * 
 * WHY SEPARATE FROM NotFoundError:
 * Validation errors (400 Bad Request) are fundamentally different from not-
 * found errors (404). Clients need to know whether their input was wrong or
 * the resource doesn't exist, so they can fix their code accordingly.
 */
class ValidationError extends Error {
  /**
   * @param {string} message - Human-readable error description
   * @param {Object} details - Additional validation failure details
   * @param {number} statusCode - HTTP status code (default: 400)
   */
  constructor(message = 'Validation failed', details = {}, statusCode = 400) {
    super(message);
    this.statusCode = statusCode;
    this.name = 'ValidationError';
    this.details = details; // Store which fields failed and why
  }
}

/**
 * Custom Error Class: InternalServerError
 * 
 * WHY THIS EXISTS:
 * We don't want to leak internal implementation details to API consumers. If
 * something unexpected goes wrong (database connection lost, etc.), we return
 * a generic 500 error with our custom message instead of exposing stack traces.
 */
class InternalServerError extends Error {
  constructor(message = 'Internal server error', statusCode = 500) {
    super(message);
    this.statusCode = statusCode;
    this.name = 'InternalServerError';
  }
}

// ============================================================================
// SECTION 4: IN-MEMORY DATA STORE
// ============================================================================

/**
 * In-memory storage array for books.
 * 
 * WHY AN ARRAY (NOT AN OBJECT MAP):
 * Arrays are chosen over objects/maps for several reasons:
 *   1. Simplicity: No need to manage keys or worry about object prototype issues
 *   2. Order preservation: Arrays maintain insertion order (useful for pagination)
 *   3. Native methods: filter(), find(), map() make operations concise
 *   4. Educational clarity: Easier to understand than hash maps for beginners
 * 
 * PRODUCTION NOTE: In a real application, you would use a database (PostgreSQL,
 * MongoDB, etc.) with proper indexing, persistence, and concurrency control.
 */
const books = [
  {
    id: 1,
    title: 'The Great Gatsby',
    author: 'F. Scott Fitzgerald',
    genre: 'Fiction',
    publishedYear: 1925,
    rating: 4.5
  },
  {
    id: 2,
    title: 'To Kill a Mockingbird',
    author: 'Harper Lee',
    genre: 'Fiction',
    publishedYear: 1960,
    rating: 4.8
  },
  {
    id: 3,
    title: 'A Brief History of Time',
    author: 'Stephen Hawking',
    genre: 'Science',
    publishedYear: 1988,
    rating: 4.7
  }
];

/**
 * Auto-incrementing ID counter.
 * 
 * WHY THIS PATTERN:
 * Using a simple counter ensures unique IDs without requiring UUID libraries.
 * In production, you'd use database auto-increment or UUID v4 for distributed
 * systems. This keeps the example lightweight and easy to understand.
 */
let nextId = 4; // Start after the last manually added book ID

// ============================================================================
// SECTION 5: VALIDATION HELPERS
// ============================================================================

/**
 * Validate book creation/update data.
 * 
 * WHY SEPARATE FUNCTION:
 * Validation logic is reused across POST and PUT endpoints. Extracting it into
 * a helper function follows DRY (Don't Repeat Yourself) principles and makes
 * the code easier to test and maintain.
 * 
 * VALIDATION RULES:
 *   - title: Required, string, minimum 1 character
 *   - author: Required, string, minimum 1 character
 *   - genre: Optional, but if provided must be a non-empty string
 *   - publishedYear: Optional, but if provided must be a valid year (1000-2100)
 *   - rating: Optional, but if provided must be between 0 and 5
 */
function validateBookData(data, isUpdate = false) {
  const errors = {};

  // For POST requests, title and author are required.
  // For PUT requests, they're still recommended but we allow partial updates.
  if (!isUpdate) {
    if (!data.title || typeof data.title !== 'string' || data.title.trim() === '') {
      errors.title = 'Title is required and must be a non-empty string';
    }
    if (!data.author || typeof data.author !== 'string' || data.author.trim() === '') {
      errors.author = 'Author is required and must be a non-empty string';
    }
  }

  // Optional fields validation (only check if provided)
  if (data.genre !== undefined) {
    if (typeof data.genre !== 'string' || data.genre.trim() === '') {
      errors.genre = 'Genre must be a non-empty string if provided';
    }
  }

  if (data.publishedYear !== undefined) {
    const year = Number(data.publishedYear);
    if (!Number.isInteger(year) || year < 1000 || year > 2100) {
      errors.publishedYear = 'Published year must be an integer between 1000 and 2100';
    }
  }

  if (data.rating !== undefined) {
    const rating = Number(data.rating);
    if (typeof rating !== 'number' || rating < 0 || rating > 5) {
      errors.rating = 'Rating must be a number between 0 and 5';
    }
  }

  // If any validation errors exist, throw a ValidationError with details.
  // This stops execution immediately and jumps to our error handling middleware.
  if (Object.keys(errors).length > 0) {
    throw new ValidationError('Invalid book data', errors);
  }
}

// ============================================================================
// SECTION 6: ROUTE HANDLERS — BOOKS COLLECTION
// ============================================================================

/**
 * GET /books — List all books with optional filtering.
 * 
 * QUERY PARAMETERS (all optional):
 *   - genre: Filter by exact genre match (e.g., ?genre=Fiction)
 *   - author: Filter by author name substring (case-insensitive, e.g., ?author=lee)
 *   - minRating: Minimum rating filter (0-5, e.g., ?minRating=4.0)
 * 
 * WHY QUERY PARAMETERS INSTEAD OF PATH VARIABLES:
 * Filtering is an optional operation that doesn't change the resource identity.
 * Query parameters are the REST convention for filtering, sorting, and pagination.
 * Path variables should only identify specific resources.
 */
app.get('/books', (req, res, next) => {
  try {
    // Start with all books as our base dataset.
    let result = [...books];

    // Apply genre filter if provided.
    // WHY TOLOWERCASE(): Makes the filter case-insensitive for better UX.
    // A user typing "fiction" should get the same results as "Fiction".
    if (req.query.genre) {
      const genreFilter = req.query.genre.toLowerCase();
      result = result.filter(book => book.genre.toLowerCase() === genreFilter);
    }

    // Apply author filter with substring matching.
    // WHY SUBSTRING MATCHING: Users might not remember the full author name.
    // "lee" should match "Harper Lee". This is more forgiving than exact match.
    if (req.query.author) {
      const authorFilter = req.query.author.toLowerCase();
      result = result.filter(book => 
        book.author.toLowerCase().includes(authorFilter)
      );
    }

    // Apply minimum rating filter.
    // WHY PARSE AS FLOAT: Ratings are decimal numbers, not integers.
    const minRating = parseFloat(req.query.minRating);
    if (!isNaN(minRating)) {
      result = result.filter(book => book.rating >= minRating);
    }

    // Return the filtered results with a 200 OK status.
    // WHY 200 INSTEAD OF 204: We're returning data, so 200 is appropriate.
    // 204 No Content would be used if we returned no body (e.g., successful delete).
    res.status(200).json({
      success: true,
      count: result.length,
      data: result
    });
  } catch (error) {
    // Pass any unexpected errors to our global error handler.
    next(error);
  }
});

/**
 * GET /books/:id — Get a single book by its ID.
 * 
 * WHY USE FIND() INSTEAD OF FOR LOOP:
 * Array.find() is more concise and readable than manual iteration. It returns
 * the first element that satisfies the condition, or undefined if none found.
 * This is the idiomatic JavaScript approach for searching arrays.
 */
app.get('/books/:id', (req, res, next) => {
  try {
    // Parse the ID from the URL parameter to a number.
    // WHY PARSEINT(): URL parameters are always strings. We need numbers for
    // comparison with our numeric IDs. Using parseInt with radix 10 ensures
    // we get base-10 integers (not octal or hex).
    const id = parseInt(req.params.id, 10);

    // Check if the ID is a valid number.
    // WHY THIS CHECK: If someone sends /books/abc, parseInt returns NaN.
    // We should catch this before calling find() to provide a clear error.
    if (isNaN(id)) {
      throw new ValidationError('Invalid book ID format', { id: 'Must be a number' });
    }

    // Search for the book with matching ID.
    const book = books.find(b => b.id === id);

    // If not found, throw our custom NotFoundError.
    // WHY THROW INSTEAD OF RETURNING 404 DIRECTLY: Throwing allows us to use
    // a single error handling middleware for all errors, keeping route handlers
    // clean and focused on business logic.
    if (!book) {
      throw new NotFoundError(`Book with ID ${id} not found`);
    }

    res.status(200).json({
      success: true,
      data: book
    });
  } catch (error) {
    next(error);
  }
});

/**
 * POST /books — Create a new book.
 * 
 * REQUEST BODY EXAMPLE:
 * {
 *   "title": "1984",
 *   "author": "George Orwell",
 *   "genre": "Dystopian",
 *   "publishedYear": 1949,
 *   "rating": 4.6
 * }
 * 
 * WHY RETURN 201 CREATED:
 * HTTP 201 indicates that a new resource was successfully created. This is the
 * REST convention for POST requests that create resources. The response should
 * include the Location header pointing to the new resource (we do this below).
 */
app.post('/books', (req, res, next) => {
  try {
    // Validate the incoming request body.
    // WHY VALIDATE BEFORE PROCESSING: Fail fast principle — catch invalid data
    // immediately rather than processing it and failing later. This saves
    // computational resources and provides clearer error messages to clients.
    validateBookData(req.body, false);

    // Create a new book object with an auto-incremented ID.
    const newBook = {
      id: nextId++, // Increment after assignment to ensure uniqueness
      title: req.body.title,
      author: req.body.author,
      genre: req.body.genre || null, // Allow null if not provided
      publishedYear: req.body.publishedYear || null,
      rating: req.body.rating || null
    };

    // Add the new book to our in-memory array.
    books.push(newBook);

    // Return 201 Created with the new resource and Location header.
    // WHY LOCATION HEADER: REST convention requires this for created resources.
    // It tells clients where to find the newly created resource (useful for
    // subsequent PUT/DELETE operations).
    res.status(201).json({
      success: true,
      data: newBook,
      location: `/books/${newBook.id}`
    });
  } catch (error) {
    next(error);
  }
});

// ============================================================================
// SECTION 7: ROUTE HANDLERS — SINGLE BOOK OPERATIONS
// ============================================================================

/**
 * PUT /books/:id — Update an existing book (full replacement).
 * 
 * WHY PUT INSTEAD OF PATCH:
 * PUT is used for full resource replacement. If a client sends a PUT request,
 * they're saying "replace this entire resource with what I'm sending." This
 * means all required fields must be present. For partial updates, we would use
 * PATCH instead (not implemented here to keep the example focused).
 * 
 * REQUEST BODY EXAMPLE:
 * {
 *   "title": "The Great Gatsby (Updated)",
 *   "author": "F. Scott Fitzgerald",
 *   "genre": "Classic Fiction",
 *   "publishedYear": 1925,
 *   "rating": 4.6
 * }
 */
app.put('/books/:id', (req, res, next) => {
  try {
    // Parse and validate the ID.
    const id = parseInt(req.params.id, 10);
    if (isNaN(id)) {
      throw new ValidationError('Invalid book ID format', { id: 'Must be a number' });
    }

    // Find the existing book before attempting any updates.
    // WHY FIND FIRST: We need to verify the resource exists before modifying it.
    // This prevents accidentally creating resources through update operations.
    const bookIndex = books.findIndex(b => b.id === id);
    if (bookIndex === -1) {
      throw new NotFoundError(`Book with ID ${id} not found`);
    }

    // Validate the incoming data.
    validateBookData(req.body, true); // true = partial update allowed

    // Create the updated book object by merging old and new data.
    // WHY SPREAD OPERATOR (...): This creates a shallow copy of the existing
    // book, then overwrites properties with values from req.body. This ensures
    // we don't mutate the original object reference unexpectedly.
    const updatedBook = {
      ...books[bookIndex], // Copy all existing properties
      title: req.body.title || books[bookIndex].title,
      author: req.body.author || books[bookIndex].author,
      genre: req.body.genre !== undefined ? req.body.genre : books[bookIndex].genre,
      publishedYear: req.body.publishedYear !== undefined ? req.body.publishedYear : books[bookIndex].publishedYear,
      rating: req.body.rating !== undefined ? req.body.rating : books[bookIndex].rating
    };

    // Replace the old book in the array with the updated version.
    books[bookIndex] = updatedBook;

    res.status(200).json({
      success: true,
      data: updatedBook
    });
  } catch (error) {
    next(error);
  }
});

/**
 * DELETE /books/:id — Delete a book by ID.
 * 
 * WHY USE FILTER() INSTEAD OF SPlice():
 * Array.filter() creates a new array without the deleted element, which is
 * more functional and avoids index shifting issues. For small arrays (like our
 * example), the performance difference is negligible. In production with large
 * datasets, splice() might be slightly more efficient.
 */
app.delete('/books/:id', (req, res, next) => {
  try {
    // Parse and validate the ID.
    const id = parseInt(req.params.id, 10);
    if (isNaN(id)) {
      throw new ValidationError('Invalid book ID format', { id: 'Must be a number' });
    }

    // Find the index of the book to delete.
    const bookIndex = books.findIndex(b => b.id === id);
    if (bookIndex === -1) {
      throw new NotFoundError(`Book with ID ${id} not found`);
    }

    // Remove the book from the array.
    // WHY SPlice(): For deletion, splice() is more appropriate than filter()
    // because we're modifying the existing array in place (no need to create
    // a new array when removing just one element).
    books.splice(bookIndex, 1);

    // Return 204 No Content — standard for successful DELETE operations.
    // WHY 204 INSTEAD OF 200: There's no body to return (the resource is gone),
    // so 204 is the semantically correct status code. It also prevents clients
    // from trying to parse a non-existent response body.
    res.status(204).send();
  } catch (error) {
    next(error);
  }
});

// ============================================================================
// SECTION 8: ROUTE HANDLER — STATISTICS ENDPOINT
// ============================================================================

/**
 * GET /stats — Return aggregate statistics about the book collection.
 * 
 * WHY SEPARATE ENDPOINT INSTEAD OF INCLUDING IN LIST:
 * Statistics are derived data, not raw resources. REST best practices suggest
 * keeping resource endpoints focused on individual resources and using separate
 * endpoints for aggregated/derived data. This keeps the API clean and allows
 * clients to request only what they need.
 */
app.get('/stats', (req, res, next) => {
  try {
    // Calculate total number of books.
    const totalBooks = books.length;

    // Calculate average rating using reduce() for accumulation.
    // WHY REDUCE(): This is the functional programming approach for computing
    // a single value from an array. It's more concise than a traditional loop
    // and clearly expresses the intent: "reduce this array to a sum."
    const totalRating = books.reduce((sum, book) => sum + book.rating, 0);
    const averageRating = totalBooks > 0 ? (totalRating / totalBooks).toFixed(2) : 0;

    // Find the most common genre using a frequency map.
    // WHY FREQUENCY MAP: Counting occurrences is more efficient than nested loops.
    // We create an object where keys are genres and values are counts, then find
    // the key with the highest value.
    const genreCounts = {};
    books.forEach(book => {
      if (book.genre) {
        genreCounts[book.genre] = (genreCounts[book.genre] || 0) + 1;
      }
    });

    // Find the genre with the maximum count.
    let mostCommonGenre = 'N/A';
    let maxCount = 0;
    Object.entries(genreCounts).forEach(([genre, count]) => {
      if (count > maxCount) {
        maxCount = count;
        mostCommonGenre = genre;
      }
    });

    // Return statistics with a 200 OK status.
    res.status(200).json({
      success: true,
      data: {
        totalBooks,
        averageRating: parseFloat(averageRating),
        mostCommonGenre,
        genreDistribution: genreCounts
      }
    });
  } catch (error) {
    next(error);
  }
});

// ============================================================================
// SECTION 9: ERROR HANDLING MIDDLEWARE
// ============================================================================

/**
 * Global error handling middleware.
 * 
 * WHY THIS IS NECESSARY:
 * Without a centralized error handler, every route would need its own try/catch
 * and response logic. This middleware catches all errors (including those thrown
 * by next(error)) and returns consistent JSON error responses.
 * 
 * IMPORTANT: Error handling middleware must have 4 parameters (err, req, res, next)
 * to be recognized by Express as an error handler. Regular middleware has 3.
 */
app.use((err, req, res, next) => {
  // Log the full error for debugging (stack trace included).
  console.error('Error:', err.name, '-', err.message);
  if (process.env.NODE_ENV === 'development' && err.stack) {
    console.error(err.stack); // Only show stack in development
  }

  // Determine the status code from our custom error classes.
  // FALLBACK TO 500: If an unknown error type is thrown, default to 500.
  const statusCode = err.statusCode || 500;

  // Build a consistent JSON error response.
  // WHY CONSISTENT FORMAT: Clients can rely on the same structure for all errors,
  // making error handling in frontend code simpler and more predictable.
  const errorResponse = {
    success: false,
    error: err.name || 'Error',
    message: err.message,
    ...(err.details && { details: err.details }) // Include validation details if present
  };

  res.status(statusCode).json(errorResponse);
});

// ============================================================================
// SECTION 10: 404 HANDLER FOR UNRECOGNIZED ROUTES
// ============================================================================

/**
 * Catch-all middleware for undefined routes.
 * 
 * WHY THIS IS NECESSARY:
 * If a client requests a route that doesn't exist (e.g., /books/999 when no
 * book with ID 999 exists, or /unknown), Express won't match any route and
 * will return its default 404 page. This middleware ensures we return our own
 * consistent JSON error format instead.
 */
app.use((req, res, next) => {
  // Throw a NotFoundError to trigger our error handling middleware.
  // WHY THROW INSTEAD OF RESPONDING DIRECTLY: This keeps the error flow
  // consistent — all errors go through the same middleware for formatting.
  next(new NotFoundError(`Route ${req.method} ${req.url} not found`));
});

// ============================================================================
// SECTION 11: SERVER STARTUP
// ============================================================================

/**
 * Start the HTTP server and listen on the configured port.
 * 
 * WHY ASYNC/AWAIT PATTERN:
 * While Express's listen() is synchronous, using async/await for startup
 * allows us to add initialization logic (database connections, etc.) in the
 * future without restructuring the code. It's a forward-thinking pattern.
 */
async function startServer() {
  try {
    app.listen(PORT, () => {
      console.log(`📚 Book API server running on http://localhost:${PORT}`);
      console.log(`📖 Available endpoints:`);
      console.log(`   GET    /books          - List all books (with optional filters)`);
      console.log(`   GET    /books/:id      - Get a single book by ID`);
      console.log(`   POST   /books          - Create a new book`);
      console.log(`   PUT    /books/:id      - Update an existing book`);
      console.log(`   DELETE /books/:id      - Delete a book`);
      console.log(`   GET    /stats          - Get collection statistics`);
    });
  } catch (error) {
    console.error('Failed to start server:', error.message);
    process.exit(1); // Exit with error code if startup fails
  }
}

// Start the server when this module is executed.
startServer();

/**
 * ============================================================================
 * END OF SERVER.JS
 * ============================================================================
 * 
 * SUMMARY OF DESIGN PATTERNS USED:
 * 
 * 1. REST Conventions:
 *    - GET for reading resources (idempotent, safe)
 *    - POST for creating resources
 *    - PUT for full resource replacement
 *    - DELETE for removing resources
 *    - Proper HTTP status codes (200, 201, 204, 400, 404, 500)
 * 
 * 2. Error Handling:
 *    - Custom error classes with statusCode properties
 *    - Centralized error handling middleware
 *    - Consistent JSON error response format
 *    - Validation errors include field-specific details
 * 
 * 3. Code Organization:
 *    - Clear section comments for logical grouping
 *    - JSDoc comments on every function and endpoint
 *    - Helper functions for reusable logic (validation)
 *    - Separation of concerns (routes, validation, error handling)
 * 
 * 4. Security Considerations (for production):
 *    - Input validation on all user-supplied data
 *    - CORS configured restrictively in production
 *    - No stack traces exposed in production responses
 *    - Rate limiting and authentication would be added
 * 
 * NEXT STEPS FOR PRODUCTION:
 *    1. Replace in-memory storage with a database (PostgreSQL/MongoDB)
 *    2. Add authentication/authorization (JWT, OAuth)
 *    3. Implement rate limiting (express-rate-limit)
 *    4. Add request validation library (Joi, Zod)
 *    5. Set up logging service (Winston, Pino)
 *    6. Add API documentation (Swagger/OpenAPI)
 *    7. Write unit/integration tests (Jest, Supertest)
 */
```

