## Arquivo 2: `src/errors/customErrors.js`

```javascript
/**
 * ============================================================================
 * CLASSES DE ERRO PERSONALIZADAS
 * ============================================================================
 *
 * POR QUE CRIAR CLASSES DE ERRO PERSONALIZADAS?
 * ----------------------------------------------
 * Em vez de lançar erros genéricos com `throw new Error("mensagem")`, criamos
 * classes que estendem a classe nativa `Error`. Isso nos permite:
 *
 * 1. IDENTIFICAR O TIPO DE ERRO PROGRAMATICAMENTE — podemos usar `instanceof`
 *    para distinguir entre "recurso não encontrado", "requisição inválida", etc.
 *
 * 2. INCLUIR CAMPOS ADICIONAIS — como `statusCode` (código HTTP) e `isOperational`
 *    (para diferenciar erros de negócio de bugs do sistema).
 *
 * 3. MELHORAR O TRATAMENTO CENTRALIZADO — o middleware de erro pode inspecionar
 *    a classe do erro para decidir qual resposta enviar ao cliente.
 *
 * PADRÃO ADOTADO: Erros "operacionais" são aqueles esperados no fluxo normal da
 * aplicação (ex: recurso não encontrado). Erros "não operacionais" são bugs que
 * devem ser tratados como 500 Internal Server Error.
 */

/**
 * Classe base para erros operacionais da API.
 *
 * Erros operacionais são aqueles que ocorrem durante a execução normal do programa,
 * mas representam condições excepcionais (ex: usuário não encontrado). Eles NÃO
 * indicam bugs no código e devem retornar códigos HTTP apropriados ao cliente.
 */
class AppError extends Error {
  /**
   * Construtor da classe base AppError.
   *
   * @param {string} message - Mensagem de erro descritiva para o cliente.
   * @param {number} statusCode - Código HTTP a ser retornado (ex: 400, 404).
   */
  constructor(message, statusCode) {
    super(message); // Chama o construtor da classe Error nativa

    // Define o código HTTP como propriedade da instância.
    // Usamos Object.defineProperty para que a propriedade não seja enumerável
    // (não apareça em JSON.stringify ou for...in), mantendo a saída limpa.
    this.statusCode = statusCode;

    // Marca este erro como "operacional" — significa que é um erro esperado,
    // não um bug. O middleware de erro usará esse flag para decidir se loga
    // o erro no servidor ou apenas retorna a resposta ao cliente.
    this.isOperational = true;

    // Captura o stack trace no momento da criação do erro.
    // Isso é importante para debugging, mesmo em erros operacionais.
    Error.captureStackTrace(this, this.constructor);
  }
}

/**
 * Erro lançado quando um recurso solicitado não é encontrado.
 *
 * Exemplo de uso: ao buscar um livro por ID que não existe no array.
 * Retorna HTTP 404 Not Found.
 */
class NotFoundError extends AppError {
  /**
   * @param {string} resource - Nome do recurso (ex: "Livro") para a mensagem.
   * @param {*} id - ID do recurso que não foi encontrado.
   */
  constructor(resource, id) {
    // A mensagem é construída dinamicamente com o nome do recurso e o ID.
    super(`${resource} com ID ${id} não encontrado`, 404);

    // Nome da classe para identificação em logs e tratamentos específicos.
    this.name = 'NotFoundError';
  }
}

/**
 * Erro lançado quando os dados enviados na requisição são inválidos.
 *
 * Exemplo de uso: ao criar um livro sem título ou com preço negativo.
 * Retorna HTTP 400 Bad Request.
 */
class ValidationError extends AppError {
  /**
   * @param {string} message - Mensagem descritiva do erro de validação.
   * @param {Object} [details] - Detalhes adicionais sobre quais campos falharam.
   */
  constructor(message, details = {}) {
    super(message, 400);
    this.name = 'ValidationError';

    // Armazena detalhes da validação (ex: quais campos e por quê) para
    // permitir que o cliente corrija exatamente o problema.
    this.details = details;
  }
}

/**
 * Erro lançado quando uma operação de escrita falha inesperadamente.
 *
 * Exemplo de uso: falha ao salvar em banco de dados (neste exemplo, erro
 * interno do array). Retorna HTTP 500 Internal Server Error.
 */
class InternalError extends AppError {
  /**
   * @param {string} message - Mensagem descritiva do erro interno.
   * @param {Error} [originalError] - O erro original que causou a falha.
   */
  constructor(message, originalError = null) {
    super(message, 500);
    this.name = 'InternalError';

    // Armazena o erro original para logging completo no servidor.
    // Isso ajuda os desenvolvedores a diagnosticarem problemas sem expor
    // detalhes internos ao cliente final.
    if (originalError) {
      this.originalError = originalError;
    }
  }
}

// Exporta todas as classes de erro para uso nos módulos de rota e middleware.
module.exports = { AppError, NotFoundError, ValidationError, InternalError };
```

