## Arquivo 3: `src/middleware/errorHandler.js`

```javascript
/**
 * ============================================================================
 * MIDDLEWARE DE TRATAMENTO DE ERROS
 * ============================================================================
 *
 * POR QUE UM MIDDLEWARE DE ERRO?
 * --------------------------------
 * Em Express, middlewares de tratamento de erro têm uma assinatura especial:
 *   (err, req, res, next) => { ... }
 *
 * O framework identifica automaticamente esses middlewares pelo número de
 * parâmetros e os executa quando `next(err)` é chamado ou quando um erro
 * não tratado é lançado.
 *
 * PADRÃO ADOTADO: Centralizamos todo o tratamento de erros em UM único lugar.
 * Isso evita duplicação de código e garante consistência nas respostas de erro.
 *
 * FLUXO DE DECISÃO DO MIDDLEWARE:
 * 1. Se for um erro operacional (AppError) → retorna JSON com statusCode correto.
 * 2. Se for erro de validação → inclui detalhes dos campos inválidos.
 * 3. Se for erro não operacional (bug) → loga no servidor, retorna 500 genérico.
 * 4. Para erros desconhecidos → loga stack trace completo e retorna 500.
 */

const { AppError, ValidationError } = require('../errors/customErrors');

/**
 * Middleware central de tratamento de erros.
 *
 * @param {Error} err - O erro lançado durante o processamento da requisição.
 * @param {import('express').Request} req - Objeto de requisição do Express.
 * @param {import('express').Response} res - Objeto de resposta do Express.
 * @param {import('express').NextFunction} next - Função para passar ao próximo middleware.
 */
const errorHandler = (err, req, res, next) => {
  // REGRA DE OURO: Nunca expor stack traces ou detalhes internos ao cliente final.
  // Isso é uma prática de segurança — informações internas podem revelar
  // estrutura do projeto, caminhos de arquivos, versões de bibliotecas, etc.

  console.error('=== ERRO CAPTURADO ===');
  console.error(`Método: ${req.method}`);
  console.error(`URL: ${req.originalUrl}`);
  console.error(`Mensagem: ${err.message}`);
  if (err.stack) {
    console.error('Stack Trace:\n', err.stack);
  }

  // CASO 1: Erro operacional conhecido (AppError ou subclasses)
  if (err instanceof AppError) {
    // Para erros de validação, incluímos os detalhes dos campos problemáticos.
    // Isso permite que o cliente corrija exatamente o que está errado.
    const response = {
      status: 'error',
      statusCode: err.statusCode,
      message: err.message,
    };

    // Se houver detalhes de validação (ex: quais campos falharam), incluí-los.
    if (err instanceof ValidationError && Object.keys(err.details).length > 0) {
      response.details = err.details;
    }

    return res.status(err.statusCode).json(response);
  }

  // CASO 2: Erro não operacional — bug no código ou falha inesperada.
  // Retornamos uma mensagem genérica ao cliente (sem detalhes internos)
  // mas logamos o stack trace completo para os desenvolvedores.
  console.error('ERRO NÃO OPERACIONAL DETECTADO — POSSÍVEL BUG NO CÓDIGO');

  return res.status(500).json({
    status: 'error',
    statusCode: 500,
    message: 'Erro interno do servidor. A equipe de desenvolvimento foi notificada.',
    // Em produção, NUNCA inclua o stack trace na resposta ao cliente.
    // O campo "debug" é apenas para ambiente de desenvolvimento.
    ...(process.env.NODE_ENV !== 'production' && { debug: err.message }),
  });
};

module.exports = errorHandler;
```

