/**
 * ============================================================================
 * ROTAS DE LIVROS — CRUD COMPLETO
 * ============================================================================
 *
 * POR QUE ARQUIVO DE ROTA SEPARADO?
 * ----------------------------------
 * Separar as rotas em um arquivo dedicado segue o princípio de responsabilidade
 * única (Single Responsibility Principle). O arquivo `app.js` cuida da configuração
 * do servidor, enquanto este módulo cuida exclusivamente da lógica de negócio
 * relacionada a livros. Isso facilita:
 * - Manutenção: alterações nas rotas ficam isoladas.
 * - Testabilidade: podemos testar as rotas independentemente.
 * - Escalabilidade: ao crescer, podemos dividir em sub-rotas (ex: /books/:id/reviews).
 *
 * PADRÃO REST ADOTADO:
 * - GET    /books       → Listar todos os livros (com filtragem opcional)
 * - GET    /books/:id   → Obter um livro específico
 * - POST   /books       → Criar um novo livro
 * - PUT    /books/:id   → Atualizar completamente um livro existente
 * - DELETE /books/:id   → Excluir um livro
 * - GET    /stats       → Estatísticas agregadas dos livros
 *
 * Cada rota segue convenções HTTP:
 * - GET: apenas leitura, nunca modifica dados.
 * - POST: cria recurso, retorna 201 Created com o corpo do novo recurso.
 * - PUT: substituição completa (o cliente envia todos os campos).
 * - DELETE: remove recurso, retorna 204 No Content (sem corpo na resposta).
 */

const express = require('express');

// Importamos as classes de erro personalizadas para uso nas rotas.
const { NotFoundError, ValidationError } = require('../errors/customErrors');

// ============================================================================
// ESTRUTURA DE DADOS EM MEMÓRIA
// ============================================================================
//
 * POR QUE UM ARRAY?
 * -----------------
 * Para este exemplo educacional, usamos um array em memória porque:
 * 1. SIMPLICIDADE: não requer configuração de banco de dados.
 * 2. TRANSPARÊNCIA: é fácil visualizar e entender os dados.
 * 3. PERFORMANCE ADEQUADA: para centenas/milhares de registros, arrays são
 *    suficientemente rápidos para operações CRUD básicas.
 *
 * POR QUE CADA LIVRO TEM PROPRIEDADES ESPECÍFICAS?
 * -------------------------------------------------
 * - id (number): identificador único gerado automaticamente. Usamos um contador
 *   simples porque é suficiente para o exemplo. Em produção, usaríamos UUIDs
 *   ou IDs do banco de dados.
 * - title (string): obrigatório, máximo 200 caracteres.
 * - author (string): obrigatório.
 * - isbn (string): opcional, mas se fornecido, deve ter formato válido.
 * - price (number): obrigatório, deve ser positivo.
 * - publishedYear (number): ano de publicação, entre 1450 e o ano atual.
 * - genre (string): gênero literário.
 * - createdAt / updatedAt: timestamps para auditoria e controle de versão.
 */

/**
 * Array que armazena todos os livros em memória.
 *
 * Usamos `let` ao invés de `const` porque o array será modificado
 * (empurrar novos elementos, filtrar, etc.). O array em si é uma referência
 * que pode ser reatribuída, mas usamos métodos mutadores do array (splice, push)
 * para manter a mesma referência.
 */
let books = [
  {
    id: 1,
    title: 'O Senhor dos Anéis',
    author: 'J.R.R. Tolkien',
    isbn: '978-0618640157',
    price: 89.90,
    publishedYear: 1954,
    genre: 'Fantasia',
    createdAt: '2024-01-15T10:00:00.000Z',
    updatedAt: '2024-01-15T10:00:00.000Z',
  },
  {
    id: 2,
    title: '1984',
    author: 'George Orwell',
    isbn: '978-0451524935',
    price: 34.90,
    publishedYear: 1949,
    genre: 'Distopia',
    createdAt: '2024-01-16T14:30:00.000Z',
    updatedAt: '2024-01-16T14:30:00.000Z',
  },
  {
    id: 3,
    title: 'Dom Casmurro',
    author: 'Machado de Assis',
    isbn: null,
    price: 29.90,
    publishedYear: 1899,
    genre: 'Romance',
    createdAt: '2024-01-17T09:15:00.000Z',
    updatedAt: '2024-01-17T09:15:00.000Z',
  },
];

/**
 * Contador para gerar IDs únicos.
 *
 * Começamos em 4 porque os livros iniciais já usam IDs 1, 2 e 3.
 * Em um sistema real, o banco de dados geraria esses IDs automaticamente.
 */
let nextId = 4;

// ============================================================================
 * CRIAR O ROTEADOR EXPRESS
 * ============================================================================
 * `express.Router()` cria um manipulador de rotas modular e reutilizável.
 * Isso permite que agrupemos rotas relacionadas e as montemos em diferentes
 * caminhos no aplicativo principal.
 */
const router = express.Router();

// ============================================================================
 * FUNÇÕES DE VALIDAÇÃO
 * ============================================================================
 * Separar a validação das rotas mantém o código limpo e reutilizável.
 * Se precisarmos validar um livro em múltiplos lugares (criar, atualizar),
 * podemos chamar estas funções de qualquer lugar.
 */

/**
 * Valida os dados de criação de um novo livro.
 *
 * @param {Object} data - Dados enviados pelo cliente no corpo da requisição.
 * @returns {Object|null} - Objeto com erros de validação (chave: campo, valor: mensagem)
 *                          ou null se todos os campos forem válidos.
 */
function validateCreateBook(data) {
  const errors = {};

  // VALIDAÇÃO DO TÍTULO: obrigatório e não vazio.
  if (!data.title || data.title.trim() === '') {
    errors.title = 'O título é obrigatório';
  } else if (data.title.length > 200) {
    errors.title = 'O título deve ter no máximo 200 caracteres';
  }

  // VALIDAÇÃO DO AUTOR: obrigatório e não vazio.
  if (!data.author || data.author.trim() === '') {
    errors.author = 'O autor é obrigatório';
  } else if (data.author.length > 150) {
    errors.author = 'O autor deve ter no máximo 150 caracteres';
  }

  // VALIDAÇÃO DO PREÇO: obrigatório e deve ser um número positivo.
  if (data.price === undefined || data.price === null) {
    errors.price = 'O preço é obrigatório';
  } else if (typeof data.price !== 'number' || data.price < 0) {
    errors.price = 'O preço deve ser um número positivo';
  }

  // VALIDAÇÃO DO ANO DE PUBLICAÇÃO: se fornecido, deve estar no intervalo razoável.
  if (data.publishedYear !== undefined && data.publishedYear !== null) {
    const currentYear = new Date().getFullYear();
    if (!Number.isInteger(data.publishedYear) ||
        data.publishedYear < 1450 ||
        data.publishedYear > currentYear) {
      errors.publishedYear = `O ano deve ser um inteiro entre 1450 e ${currentYear}`;
    }
  }

  // VALIDAÇÃO DO ISBN: se fornecido, deve ter formato válido (10 ou 13 dígitos).
  if (data.isbn !== undefined && data.isbn !== null && data.isbn !== '') {
    const isbnClean = String(data.isbn).replace(/[-\s]/g, '');
    if (!/^\d{10}$/.test(isbnClean) && !/^\d{13}$/.test(isbnClean)) {
      errors.isbn = 'O ISBN deve ter 10 ou 13 dígitos numéricos';
    }
  }

  // Retorna null se não houver erros (objeto vazio), senão retorna os erros.
  return Object.keys(errors).length > 0 ? errors : null;
}

/**
 * Valida os dados de atualização parcial de um livro.
 *
 * Diferente da criação, na atualização todos os campos são opcionais.
 * O cliente pode enviar apenas os campos que deseja alterar.
 *
 * @param {Object} data - Dados parciais enviados pelo cliente.
 * @returns {Object|null} - Erros de validação ou null se válido.
 */
function validateUpdateBook(data) {
  const errors = {};

  // Cada campo é validado apenas se for fornecido (não undefined/null).
  if (data.title !== undefined) {
    if (typeof data.title !== 'string' || data.title.trim() === '') {
      errors.title = 'O título deve ser uma string não vazia';
    } else if (data.title.length > 200) {
      errors.title = 'O título deve ter no máximo 200 caracteres';
    }
  }

  if (data.author !== undefined) {
    if (typeof data.author !== 'string' || data.author.trim() === '') {
      errors.author = 'O autor deve ser uma string não vazia';
    } else if (data.author.length > 150) {
      errors.author = 'O autor deve ter no máximo 150 caracteres';
    }
  }

  if (data.price !== undefined) {
    if (typeof data.price !== 'number' || data.price < 0) {
      errors.price = 'O preço deve ser um número positivo';
    }
  }

  if (data.publishedYear !== undefined) {
    const currentYear = new Date().getFullYear();
    if (!Number.isInteger(data.publishedYear) ||
        data.publishedYear < 1450 ||
        data.publishedYear > currentYear) {
      errors.publishedYear = `O ano deve ser um inteiro entre 1450 e ${currentYear}`;
    }
  }

  if (data.isbn !== undefined && data.isbn !== null && data.isbn !== '') {
    const isbnClean = String(data.isbn).replace(/[-\s]/g, '');
    if (!/^\d{10}$/.test(isbnClean) && !/^\d{13}$/.test(isbnClean)) {
      errors.isbn = 'O ISBN deve ter 10 ou 13 dígitos numéricos';
    }
  }

  return Object.keys(errors).length > 0 ? errors : null;
}

// ============================================================================
 * ROTAS — LISTAR TODOS OS LIVROS (GET /books)
 * ============================================================================
 *
 * EXEMPLO DE SOLICITAÇÃO:
 * -----------------------
 * curl -X GET "http://localhost:3000/books"
 * curl -X GET "http://localhost:3000/books?genre=Fantasia&minPrice=20&maxPrice=50"
 * curl -X GET "http://localhost:3000/books?search=tolkien&page=1&limit=10"
 */
router.get('/books', (req, res) => {
  /**
   * PARÂMETROS DE FILTRAGEM (query string):
   * - genre: filtra por gênero literário (case-insensitive).
   * - search: busca por título ou autor (substring match).
   * - minPrice / maxPrice: faixa de preço.
   * - publishedYear: ano exato de publicação.
   * - page / limit: paginação para grandes conjuntos de dados.
   *
   * POR QUE USAR QUERY STRING AO INVÉS DE CORPO?
   * ---------------------------------------------
   * Em HTTP, GET é um método de leitura/solicitação. Dados de filtragem são
   * parte da URL (query string), não do corpo. Isso permite:
   * - URLs cacheáveis (importantes para performance).
   * - Históricos de navegação funcionais.
   * - Conformidade com a semântica HTTP.
   */

  // Desestruturamos os parâmetros de query com valores padrão.
  const {
    genre,
    search,
    minPrice,
    maxPrice,
    publishedYear,
    page = '1',
    limit = '10',
  } = req.query;

  // Começamos com uma cópia do array original para não mutá-lo durante o filtro.
  let filteredBooks = [...books];

  // FILTRO POR GÊNERO: comparação case-insensitive (toLowerCase).
  if (genre) {
    filteredBooks = filteredBooks.filter(
      book => book.genre.toLowerCase() === genre.toLowerCase()
    );
  }

  // FILTRO POR BUSCA: procura o termo no título OU no autor.
  if (search) {
    const searchLower = search.toLowerCase();
    filteredBooks = filteredBooks.filter(
      book =>
        book.title.toLowerCase().includes(searchLower) ||
        book.author.toLowerCase().includes(searchLower)
    );
  }

  // FILTRO POR FAIXA DE PREÇO: converte strings de query para números.
  if (minPrice !== undefined) {
    const min = parseFloat(minPrice);
    if (!isNaN(min)) {
      filteredBooks = filteredBooks.filter(book => book.price >= min);
    }
  }

  if (maxPrice !== undefined) {
    const max = parseFloat(maxPrice);
    if (!isNaN(max)) {
      filteredBooks = filteredBooks.filter(book => book.price <= max);
    }
  }

  // FILTRO POR ANO DE PUBLICAÇÃO.
  if (publishedYear !== undefined) {
    const year = parseInt(publishedYear, 10);
    if (!isNaN(year)) {
      filteredBooks = filteredBooks.filter(book => book.publishedYear === year);
    }
  }

  // PAGINAÇÃO: calcula o índice de início e fim com base na página e limite.
  const pageNum = parseInt(page, 10) || 1;
  const limitNum = parseInt(limit, 10) || 10;
  const startIndex = (pageNum - 1) * limitNum;
  const endIndex = startIndex + limitNum;

  // `.slice()` retorna uma fatia do array sem modificá-lo.
  const paginatedBooks = filteredBooks.slice(startIndex, endIndex);

  // Retorna a resposta com os livros e metadados de paginação.
  // Isso permite que o cliente navegue entre páginas e saiba quantos resultados existem.
  return res.json({
    status: 'success',
    total: filteredBooks.length,           // Total após filtragem (antes da paginação)
    page: pageNum,
    limit: limitNum,
    totalPages: Math.ceil(filteredBooks.length / limitNum),
    data: paginatedBooks,
  });
});

// ============================================================================
 * ROTAS — OBTER LIVRO POR ID (GET /books/:id)
 * ============================================================================
 *
 * EXEMPLO DE SOLICITAÇÃO:
 * -----------------------
 * curl -X GET "http://localhost:3000/books/1"
 */
router.get('/books/:id', (req, res, next) => {
  /**
   * POR QUE USAR `next()` PARA ERROS EM ROTAS SÍNCRONAS?
   * ---------------------------------------------------
   * Mesmo em rotas que não usam async/await, podemos chamar `next(err)` para
   * encadear o erro ao middleware de tratamento de erros. Isso mantém a lógica
   * de tratamento de erros centralizada.
   */

  // Converte o ID da URL (que vem como string) para número.
  const id = parseInt(req.params.id, 10);

  // Busca o livro pelo ID usando `.find()` — retorna o PRIMEIRO elemento que
  // satisfaz a condição, ou undefined se nenhum for encontrado.
  const book = books.find(book => book.id === id);

  // Se não encontrou, lançamos um NotFoundError que será capturado pelo middleware.
  if (!book) {
    return next(new NotFoundError('Livro', id));
  }

  // Retorna o livro com status 200 OK.
  return res.json({
    status: 'success',
    data: book,
  });
});

// ============================================================================
 * ROTAS — CRIAR NOVO LIVRO (POST /books)
 * ============================================================================
 *
 * EXEMPLO DE SOLICITAÇÃO:
 * -----------------------
 * curl -X POST "http://localhost:3000/books" \
 *   -H "Content-Type: application/json" \
 *   -d '{"title":"Admirável Mundo Novo","author":"Aldous Huxley","price":45.90,"genre":"Distopia"}'
 */
router.post('/books', (req, res, next) => {
  /**
   * POR QUE USAR `req.body`?
   * ------------------------
   * O Express precisa de um middleware como `express.json()` para parsear o corpo
   * das requisições com Content-Type: application/json. Sem ele, `req.body` seria
   * undefined. Esse middleware já está configurado no app.js.
   */

  // Valida os dados enviados pelo cliente.
  const validationErrors = validateCreateBook(req.body);

  if (validationErrors) {
    // Se houver erros de validação, lançamos um ValidationError que inclui
    // os detalhes de quais campos falharam e por quê.
    return next(new ValidationError('Dados inválidos na criação do livro', validationErrors));
  }

  // Cria o novo livro com timestamp atual.
  const newBook = {
    id: nextId++,                              // ID único incrementado automaticamente.
    title: req.body.title.trim(),              // Remove espaços extras no início/fim.
    author: req.body.author.trim(),
    isbn: req.body.isbn || null,               // Se não fornecido, usa null.
    price: req.body.price,
    publishedYear: req.body.publishedYear || null,
    genre: req.body.genre || null,
    createdAt: new Date().toISOString(),       // Formato ISO 8601 para compatibilidade.
    updatedAt: new Date().toISOString(),
  };

  // Adiciona o livro ao array usando `.push()` — método mutador do array.
  books.push(newBook);

  /**
   * POR QUE RETORNAR 201 CREATED?
   * ------------------------------
   * O código 201 indica que um novo recurso foi criado com sucesso. É a convenção
   * REST para POST que cria recursos. O corpo da resposta inclui o recurso criado
   * para que o cliente possa confirmar os dados (incluindo o ID gerado automaticamente).
   */
  return res.status(201).json({
    status: 'created',
    data: newBook,
  });
});

// ============================================================================
 * ROTAS — ATUALIZAR LIVRO EXISTENTE (PUT /books/:id)
 * ============================================================================
 *
 * EXEMPLO DE SOLICITAÇÃO:
 * -----------------------
 * curl -X PUT "http://localhost:3000/books/1" \
 *   -H "Content-Type: application/json" \
 *   -d '{"title":"O Senhor dos Anéis (Ed. Definitiva)","price":99.90}'
 */
router.put('/books/:id', (req, res, next) => {
  /**
   * DIFERENÇA ENTRE PUT E PATCH:
   * ----------------------------
   * - PUT: substituição COMPLETA do recurso. O cliente deve enviar todos os campos.
   * - PATCH: atualização PARCIAL. O cliente envia apenas os campos que deseja alterar.
   *
   * Neste exemplo, usamos PUT mas permitimos atualização parcial (comportamento
   * similar a PATCH) para maior flexibilidade. Em um sistema real, você escolheria
   * um dos dois padrões e se manteria consistente.
   */

  const id = parseInt(req.params.id, 10);

  // Encontra o índice do livro no array (não apenas o objeto).
  // Usamos `.findIndex()` porque precisaremos do índice para substituir o elemento.
  const bookIndex = books.findIndex(book => book.id === id);

  if (bookIndex === -1) {
    return next(new NotFoundError('Livro', id));
  }

  // Valida os dados enviados (todos os campos são opcionais no PUT parcial).
  const validationErrors = validateUpdateBook(req.body);

  if (validationErrors) {
    return next(new ValidationError('Dados inválidos na atualização do livro', validationErrors));
  }

  // Cria o objeto atualizado mesclando os dados existentes com os novos.
  // O operador spread (`...`) cria uma cópia rasa do objeto existente.
  const updatedBook = {
    ...books[bookIndex],                       // Copia todos os campos existentes.
    title: req.body.title !== undefined ? req.body.title.trim() : books[bookIndex].title,
    author: req.body.author !== undefined ? req.body.author.trim() : books[bookIndex].author,
    isbn: req.body.isbn !== undefined ? req.body.isbn : books[bookIndex].isbn,
    price: req.body.price !== undefined ? req.body.price : books[bookIndex].price,
    publishedYear: req.body.publishedYear !== undefined ? req.body.publishedYear : books[bookIndex].publishedYear,
    genre: req.body.genre !== undefined ? req.body.genre : books[bookIndex].genre,
    updatedAt: new Date().toISOString(),       // Atualiza o timestamp de modificação.
  };

  // Substitui o livro antigo pelo atualizado no array.
  books[bookIndex] = updatedBook;

  return res.json({
    status: 'updated',
    data: updatedBook,
  });
});

// ============================================================================
 * ROTAS — EXCLUIR LIVRO (DELETE /books/:id)
 * ============================================================================
 *
 * EXEMPLO DE SOLICITAÇÃO:
 * -----------------------
 * curl -X DELETE "http://localhost:3000/books/1"
 */
router.delete('/books/:id', (req, res, next) => {
  const id = parseInt(req.params.id, 10);

  // Encontra o índice do livro a ser excluído.
  const bookIndex = books.findIndex(book => book.id === id);

  if (bookIndex === -1) {
    return next(new NotFoundError('Livro', id));
  }

  // `.splice()` remove elementos de um array e retorna os elementos removidos.
  // `[0]` pega o primeiro (e único) elemento removido para retornar na resposta.
  const deletedBook = books.splice(bookIndex, 1)[0];

  /**
   * POR QUE RETORNAR 204 NO CONTENT?
   * ---------------------------------
   * O código 204 indica que a operação foi bem-sucedida mas não há conteúdo
   * para retornar no corpo da resposta. Isso é eficiente (menos dados na rede)
   * e segue a convenção REST para DELETE.
   */
  return res.status(204).send();
});

// ============================================================================
 * ROTAS — ESTATÍSTICAS DOS LIVROS (GET /stats)
 * ============================================================================
 *
 * EXEMPLO DE SOLICITAÇÃO:
 * -----------------------
 * curl -X GET "http://localhost:3000/stats"
 */
router.get('/stats', (req, res) => {
  /**
   * POR QUE USAR `.reduce()` PARA CÁLCULOS AGREGADOS?
   * -------------------------------------------------
   * `.reduce()` é ideal para transformar um array em um único valor acumulado.
   * É mais eficiente que usar loops `for` porque percorre o array uma única vez,
   * calculando todas as métricas simultaneamente.
   */

  const stats = books.reduce(
    (acc, book) => {
      acc.totalBooks++;
      acc.totalPrice += book.price;

      // Acumula o ano mais recente e o mais antigo.
      if (!acc.oldestYear || book.publishedYear < acc.oldestYear) {
        acc.oldestYear = book.publishedYear;
      }
      if (!acc.newestYear || book.publishedYear > acc.newestYear) {
        acc.newestYear = book.publishedYear;
      }

      // Agrupa livros por gênero e conta quantos existem em cada.
      if (!acc.byGenre[book.genre]) {
        acc.byGenre[book.genre] = 0;
      }
      acc.byGenre[book.genre]++;

      return acc;
    },
    {
      // Valores iniciais do acumulador.
      totalBooks: 0,
      totalPrice: 0,
      oldestYear: null,
      newestYear: null,
      byGenre: {},
    }
  );

  // Calcula o preço médio com precisão de 2 casas decimais.
  const averagePrice = stats.totalBooks > 0
    ? parseFloat((stats.totalPrice / stats.totalBooks).toFixed(2))
    : 0;

  return res.json({
    status: 'success',
    data: {
      totalBooks: stats.totalBooks,
      averagePrice,
      oldestPublicationYear: stats.oldestYear,
      newestPublicationYear: stats.newestYear,
      booksByGenre: stats.byGenre,
    },
  });
});

// Exporta o roteador para ser montado no app.js.
module.exports = router;
```

