## Arquivo 5: `src/app.js`

```javascript
/**
 * ============================================================================
 * CONFIGURAÇÃO DO SERVIDOR EXPRESS
 * ============================================================================
 *
 * POR QUE SEPARAR A CONFIGURAÇÃO DAS ROTAS?
 * ------------------------------------------
 * O arquivo `app.js` é o ponto de entrada da aplicação. Ele configura:
 * 1. Middlewares globais (parse de JSON, logging, tratamento de erros).
 * 2. Roteamento principal (montagem das rotas do módulo books.js).
 * 3. Tratamento de rotas não encontradas (404).
 *
 * Isso segue o padrão de separação de preocupações: configuração ≠ lógica de negócio.
 */

const express = require('express');
const router = require('./routes/books');
const errorHandler = require('./middleware/errorHandler');
const { InternalError } = require('./errors/customErrors');

// Cria a aplicação Express — é uma função que retorna um objeto app.
const app = express();

// ============================================================================
 * MIDDLEWARES GLOBAIS
 * ============================================================================

/**
 * express.json() — Middleware para parsear corpos de requisição JSON.
 *
 * Sem este middleware, `req.body` seria undefined em requisições POST/PUT.
 * Este middleware analisa automaticamente o header Content-Type e converte
 * o corpo da requisição (string) em um objeto JavaScript.
 */
app.use(express.json());

/**
 * Middleware de logging simples para depuração.
 *
 * Loga cada requisição com método, URL e timestamp.
 * Em produção, considere usar bibliotecas como `morgan` ou `pino`.
 */
app.use((req, res, next) => {
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.originalUrl}`);
  next(); // Passa para o próximo middleware/rota.
});

// ============================================================================
 * MONTAGEM DAS ROTAS
 * ============================================================================
 *
 * `app.use('/api', router)` monta todas as rotas definidas em books.js
 * sob o prefixo `/api`. Isso significa que:
 * - GET /books  →  GET /api/books
 * - POST /books →  POST /api/books
 *
 * POR QUE USAR UM PREFIXO `/api`?
 * --------------------------------
 * 1. Separa rotas da API de outras rotas (ex: página inicial, health check).
 * 2. Facilita versionamento futuro (ex: `/api/v1/`, `/api/v2/`).
 * 3. É uma convenção amplamente adotada na indústria.
 */
app.use('/api', router);

// ============================================================================
 * TRATAMENTO DE ROTAS NÃO ENCONTRADAS (404)
 * ============================================================================
 *
 * Este middleware é colocado APÓS todas as rotas definidas. Se nenhuma rota
 * corresponder à URL solicitada, este middleware será executado.
 *
 * IMPORTANTE: Ele deve vir ANTES do middleware de tratamento de erros,
 * caso contrário o erro 404 seria capturado pelo handler de erros de forma
 * genérica em vez de retornarmos uma resposta JSON estruturada.
 */
app.use((req, res, next) => {
  // Lançamos um NotFoundError usando nossa classe personalizada.
  // Isso permite que o middleware de erro trate consistentemente tanto
  // erros de rotas quanto erros de negócio (recurso não encontrado).
  next(new NotFoundError('Rota', `${req.method} ${req.originalUrl}`));
});

// ============================================================================
 * MIDDLEWARE DE TRATAMENTO DE ERROS
 * ============================================================================
 *
 * Deve ser o ÚLTIMO middleware registrado. Express o identifica pelo número
 * de parâmetros (4) e o executa quando um erro é passado para `next(err)`.
 */
app.use(errorHandler);

// ============================================================================
 * INICIALIZAÇÃO DO SERVIDOR
 * ============================================================================

/**
 * Porta do servidor. Usa variável de ambiente PORT ou padrão 3000.
 * Variáveis de ambiente são a prática recomendada para configuração sensível
 * ao ambiente (portas, chaves API, etc.) — seguem a metodologia 12-Factor App.
 */
const PORT = process.env.PORT || 3000;

/**
 * Inicia o servidor e ouve na porta configurada.
 *
 * Usamos `async/await` aqui porque é um padrão moderno para operações assíncronas.
 * Embora esta função não tenha operações async reais, ela demonstra o padrão
 * que seria usado se precisássemos conectar a um banco de dados, por exemplo.
 */
async function startServer() {
  try {
    await new Promise((resolve) => {
      app.listen(PORT, () => {
        console.log(`========================================`);
        console.log(`  API de Livros rodando na porta ${PORT}`);
        console.log(`  Ambiente: ${process.env.NODE_ENV || 'development'}`);
        console.log(`  Endpoints disponíveis:`);
        console.log(`    GET    /api/books          - Listar livros`);
        console.log(`    GET    /api/books/:id      - Obter livro por ID`);
        console.log(`    POST   /api/books          - Criar livro`);
        console.log(`    PUT    /api/books/:id      - Atualizar livro`);
        console.log(`    DELETE /api/books/:id      - Excluir livro`);
        console.log(`    GET    /api/stats          - Estatísticas`);
        console.log(`========================================`);
        resolve();
      });
    });
  } catch (error) {
    // Se o servidor não conseguir iniciar (ex: porta já em uso), logamos e saímos.
    console.error('Falha ao iniciar o servidor:', error.message);
    process.exit(1); // Sai do processo com código de erro.
  }
}

// Chama a função assíncrona de inicialização.
startServer();

module.exports = app; // Exporta para testes unitários.
```

