## File 2: `server.js` — Main Entry Point

```javascript
/**
 * ============================================================================
 * FILE: server.js
 * DESCRIPTION: Main entry point for the Book Management REST API.
 *              Sets up Express, registers routes, error-handling middleware,
 *              and starts the HTTP server on a configurable port.
 *
 * DESIGN DECISIONS:
 *   - We use synchronous app.use() calls because route registration is not
 *     async; keeping it flat improves readability.
 *   - The PORT defaults to 3000 but can be overridden via the PORT env var,
 *     which is a common pattern for deployment flexibility (12-factor app).
 *   - We place error-handling middleware AFTER all routes so Express knows
 *     these are "catch-all" handlers (they must have 4 parameters).
 * ============================================================================
 */

// ─────────────────────────────────────────────────────────────────────────────
// SECTION 1: IMPORTS
// ─────────────────────────────────────────────────────────────────────────────

const express = require('express');
const bookRoutes = require('./routes/books');
const statsRoutes = require('./routes/stats');

// ─────────────────────────────────────────────────────────────────────────────
// SECTION 2: APP INITIALIZATION
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Create an Express application instance.
 *
 * Why express()? Express provides a lightweight, unopinionated framework for
 * building HTTP servers. It handles routing, middleware composition, and request
 */response lifecycle management so we can focus on business logic.
 */
const app = express();

// ─────────────────────────────────────────────────────────────────────────────
// SECTION 3: MIDDLEWARE CONFIGURATION
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Body-parser middleware.
 *
 * Express 4.x does not include body parsing by default. We add:
 *   - express.json(): Parses incoming requests with JSON payloads into
 *     req.body (an object). Without this, POST/PUT bodies would be undefined.
 *   - express.urlencoded(): Parses URL-encoded form data (application/x-www-form-urlencoded).
 *
 * These are placed BEFORE route registration so every route can access parsed
 * request bodies.
 */
app.use(express.json());
app.use(express.urlencoded({ extended: true }));

// ─────────────────────────────────────────────────────────────────────────────
// SECTION 4: ROUTE REGISTRATION
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Register route handlers.
 *
 * We mount routes under '/api' to namespace our API. This is a common convention
 * that allows us to later add versioning (e.g., /api/v2) or serve non-API content
 * from the root path without conflicts.
 */
app.use('/api/books', bookRoutes);   // All book CRUD operations
app.use('/api/stats', statsRoutes);  // Statistics endpoint

// ─────────────────────────────────────────────────────────────────────────────
// SECTION 5: ROOT HEALTH CHECK (OPTIONAL BUT HELPFUL)
// ─────────────────────────────────────────────────────────────────────────────

/**
 * GET /api — Root health check.
 *
 * Returns a simple JSON response to confirm the server is running.
 * Useful for load balancers, Kubernetes probes, or quick manual verification.
 */
app.get('/api', (req, res) => {
  res.json({
    message: 'Book Management API is running.',
    endpoints: {
      books: '/api/books',
      stats: '/api/stats'
    }
  });
});

// ─────────────────────────────────────────────────────────────────────────────
// SECTION 6: ERROR-HANDLING MIDDLEWARE (MUST BE LAST)
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Global error-handling middleware.
 *
 * Express identifies error-handling middleware by the presence of FOUR parameters
 * (err, req, res, next). If a route or middleware calls next(err), execution
 * jumps to this handler instead of sending a default 404.
 *
 * We log the error stack for debugging and return a sanitized JSON response so
 * internal details don't leak to clients.
 */
app.use((err, req, res, next) => {
  // Log full error details server-side (never expose stack traces to clients)
  console.error('[ERROR]', err.name, '-', err.message);
  if (process.env.NODE_ENV !== 'production') {
    console.error(err.stack);
  }

  // Default to 500 Internal Server Error for unexpected errors
  const statusCode = err.statusCode || 500;

  res.status(statusCode).json({
    success: false,
    error: {
      message: err.message,
      ...(process.env.NODE_ENV !== 'production' && { stack: err.stack })
    }
  });
});

// ─────────────────────────────────────────────────────────────────────────────
// SECTION 7: 404 HANDLER FOR UNRECOGNIZED ROUTES
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Catch-all for undefined routes.
 *
 * If no route matches the requested URL, we manually invoke next() with an
 * error so the global error handler formats a consistent JSON response instead
 * of Express's default HTML 404 page.
 */
app.use((req, res, next) => {
  const err = new Error(`Route not found: ${req.method} ${req.originalUrl}`);
  err.statusCode = 404;
  next(err);
});

// ─────────────────────────────────────────────────────────────────────────────
// SECTION 8: SERVER STARTUP
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Start the HTTP server.
 *
 * PORT defaults to 3000 but can be overridden via environment variable.
 * The callback logs a confirmation message with the actual port in use.
 */
const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  console.log(`✅ Server running on http://localhost:${PORT}`);
  console.log(`📚 API base:   http://localhost:${PORT}/api`);
  console.log(`📖 Books:      http://localhost:${PORT}/api/books`);
  console.log(`📊 Stats:      http://localhost:${PORT}/api/stats`);
});
```

