## File 3: `models/books.js` — In-Memory Data Store

```javascript
/**
 * ============================================================================
 * FILE: models/books.js
 * DESCRIPTION: In-memory data store for book records.
 *
 * WHY IN-MEMORY?
 *   For an educational example, an in-memory array avoids the complexity of
 *   setting up a database while still demonstrating CRUD semantics. In production,
 *   you would replace this with a real database (PostgreSQL, MongoDB, etc.).
 *
 * DATA STRUCTURE CHOICES:
 *   - Each book is a plain JavaScript object for simplicity and readability.
 *   - IDs are auto-incrementing integers starting at 1. This avoids the need
 *     for UUID libraries and keeps examples easy to follow. In production,
 *     use UUIDs or database-generated IDs to prevent ID collisions in distributed
 *     systems.
 *   - We store books in a module-scoped array so all route handlers share the
 *     same data without needing global variables or dependency injection.
 * ============================================================================
 */

// ─────────────────────────────────────────────────────────────────────────────
// SECTION 1: DATA STORE INITIALIZATION
// ─────────────────────────────────────────────────────────────────────────────

/**
 * In-memory array holding all book records.
 *
 * Each element is an object with the shape:
 *   {
 *     id: number,          // Unique identifier (auto-increment)
 *     title: string,       // Book title
 *     author: string,      // Author name
 *     genre: string,       // Genre/category
 *     publishedYear: number, // Year of publication
 *     createdAt: string    // ISO timestamp of creation
 *   }
 */
const books = [];

/**
 * Auto-increment counter for generating unique book IDs.
 *
 * Starting at 1 ensures IDs are human-friendly in examples. We increment this
 * every time a new book is created. Note: this resets on server restart, which
 * is acceptable for an in-memory demo but would be problematic in production
 * without persistence.
 */
let nextId = 1;

// ─────────────────────────────────────────────────────────────────────────────
// SECTION 2: SEED DATA (OPTIONAL — HELPS WITH TESTING)
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Pre-populate the store with sample books so the API isn't empty on startup.
 *
 * This makes it easier to test GET /books and filtering without first creating
 * data via POST. In production, you'd load from a database instead.
 */
const seedBooks = [
  {
    id: nextId++,
    title: 'The Great Gatsby',
    author: 'F. Scott Fitzgerald',
    genre: 'Fiction',
    publishedYear: 1925,
    createdAt: new Date().toISOString()
  },
  {
    id: nextId++,
    title: 'To Kill a Mockingbird',
    author: 'Harper Lee',
    genre: 'Fiction',
    publishedYear: 1960,
    createdAt: new Date().toISOString()
  },
  {
    id: nextId++,
    title: 'A Brief History of Time',
    author: 'Stephen Hawking',
    genre: 'Science',
    publishedYear: 1988,
    createdAt: new Date().toISOString()
  }
];

// Add seed data to the store
books.push(...seedBooks);

// ─────────────────────────────────────────────────────────────────────────────
// SECTION 3: EXPORTED FUNCTIONS
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Retrieve all books from the in-memory store.
 *
 * @returns {Array<Object>} A shallow copy of the books array to prevent
 *                          external mutation of the internal state.
 */
function getAllBooks() {
  return [...books]; // Return a copy, not the original reference
}

/**
 * Find a single book by its numeric ID.
 *
 * @param {number} id - The unique identifier of the book to find.
 * @returns {Object|undefined} The book object if found, otherwise undefined.
 */
function getBookById(id) {
  return books.find(book => book.id === id);
}

/**
 * Add a new book to the store.
 *
 * @param {Object} bookData - The book data to insert (without id or createdAt).
 * @returns {Object} The newly created book object with assigned id and timestamp.
 */
function createBook(bookData) {
  const newBook = {
    ...bookData,                    // Spread in the provided fields
    id: nextId++,                   // Assign auto-incremented ID
    createdAt: new Date().toISOString() // Record creation timestamp
  };
  books.push(newBook);
  return newBook;
}

/**
 * Update an existing book by its ID.
 *
 * @param {number} id - The ID of the book to update.
 * @param {Object} updates - Fields to overwrite (partial update supported).
 * @returns {Object|undefined} The updated book object, or undefined if not found.
 */
function updateBook(id, updates) {
  const index = books.findIndex(book => book.id === id);
  if (index === -1) return undefined;

  // Merge existing data with updates (preserves fields not in the update payload)
  books[index] = { ...books[index], ...updates };
  return books[index];
}

/**
 * Delete a book by its ID.
 *
 * @param {number} id - The ID of the book to remove.
 * @returns {boolean} True if the book was found and deleted, false otherwise.
 */
function deleteBook(id) {
  const index = books.findIndex(book => book.id === id);
  if (index === -1) return false;

  books.splice(index, 1); // Remove exactly one element at the found index
  return true;
}

/**
 * Compute aggregate statistics about the book collection.
 *
 * @returns {Object} Statistics including total count, average published year,
 *                   and a breakdown by genre.
 */
function getStats() {
  const total = books.length;

  // Guard against empty store to avoid division by zero
  if (total === 0) {
    return {
      totalBooks: 0,
      averagePublishedYear: null,
      genres: {}
    };
  }

  // Calculate the arithmetic mean of published years
  const totalYear = books.reduce((sum, book) => sum + book.publishedYear, 0);
  const averagePublishedYear = Math.round(totalYear / total);

  // Group books by genre and count occurrences
  const genres = {};
  books.forEach(book => {
    genres[book.genre] = (genres[book.genre] || 0) + 1;
  });

  return {
    totalBooks: total,
    averagePublishedYear,
    genres
  };
}

// ─────────────────────────────────────────────────────────────────────────────
// SECTION 4: MODULE EXPORTS
// ─────────────────────────────────────────────────────────────────────────────

module.exports = {
  getAllBooks,
  getBookById,
  createBook,
  updateBook,
  deleteBook,
  getStats
};
