## File 4: `errors/CustomError.js` — Custom Error Classes

```javascript
/**
 * ============================================================================
 * FILE: errors/CustomError.js
 * DESCRIPTION: Custom error classes for consistent API error responses.
 *
 * WHY CUSTOM ERROR CLASSES?
 *   Built-in JavaScript errors (Error, TypeError, etc.) don't carry HTTP status
 *   codes or structured message fields. By creating domain-specific error classes,
 *   we can:
 *     1. Attach a statusCode for immediate response mapping.
 *     2. Include an errorCode string for client-side handling.
 *     3. Distinguish between different failure modes in middleware.
 *
 * INHERITANCE PATTERN:
 *   We extend the built-in Error class and override the constructor to set
 *   name, message, statusCode, and errorCode. Calling super(message) ensures
 *   the stack trace is captured correctly by V8/Node.js.
 * ============================================================================
 */

/**
 * Base custom error class.
 *
 * All API errors should extend this class to ensure consistent shape:
 *   { name, message, statusCode, errorCode }
 */
class ApiError extends Error {
  /**
   * @param {string} message - Human-readable error description.
   * @param {number} statusCode - HTTP status code (e.g., 400, 404, 500).
   * @param {string} errorCode - Machine-readable error identifier.
   */
  constructor(message, statusCode, errorCode) {
    super(message); // Captures stack trace via Error constructor

    // Preserve the custom name for instanceof checks and logging
    this.name = 'ApiError';
    this.statusCode = statusCode;
    this.errorCode = errorCode;
  }
}

/**
 * Client error — the request was malformed or contained invalid data.
 * Use for validation failures, missing fields, or bad query parameters.
 */
class ValidationError extends ApiError {
  constructor(message, details = null) {
    super(message, 400, 'VALIDATION_ERROR');
    this.name = 'ValidationError';
    this.details = details; // Optional: array of field-specific errors
  }
}

/**
 * Resource not found — the requested entity does not exist.
 */
class NotFoundError extends ApiError {
  constructor(resource = 'Resource') {
    super(`${resource} not found`, 404, 'NOT_FOUND');
    this.name = 'NotFoundError';
  }
}

/**
 * Conflict error — the request conflicts with current state.
 * Used when a duplicate resource already exists.
 */
class ConflictError extends ApiError {
  constructor(message = 'Resource already exists') {
    super(message, 409, 'CONFLICT');
    this.name = 'ConflictError';
  }
}

module.exports = { ApiError, ValidationError, NotFoundError, ConflictError };
```

