## File 5: `middleware/validation.js` — Request Validation Middleware

```javascript
/**
 * ============================================================================
 * FILE: middleware/validation.js
 * DESCRIPTION: Reusable validation middleware for book creation and update.
 *
 * WHY SEPARATE VALIDATION MIDDLEWARE?
 *   Keeping validation logic in a dedicated module promotes:
 *     - DRY (Don't Repeat Yourself): Same rules apply to POST and PUT.
 *     - Testability: Validation can be unit-tested independently of routes.
 *     - Clarity: Route handlers stay focused on orchestration, not parsing.
 *
 * PATTERN USED: Express Middleware Signature
 *   (req, res, next) => { ... }
 *   If validation passes, call next() to proceed to the route handler.
 *   If it fails, invoke next(new ValidationError(...)) to jump to error handling.
 * ============================================================================
 */

const { ValidationError } = require('../errors/CustomError');

/**
 * Validate book creation payload (POST /books).
 *
 * Required fields: title, author, genre, publishedYear.
 * All string fields are trimmed and checked for non-empty content.
 * publishedYear must be a positive integer between 0 and the current year + 1.
 *
 * @param {Object} req - Express request object (we only read req.body).
 * @param {Object} _res - Express response object (unused in validation middleware).
 * @param {Function} next - Express next middleware function.
 */
function validateCreateBook(req, _res, next) {
  const { title, author, genre, publishedYear } = req.body;

  // Collect all validation errors before throwing so the client sees every issue
  const errors = [];

  if (!title || typeof title !== 'string' || title.trim() === '') {
    errors.push({ field: 'title', message: 'Title is required and must be a non-empty string.' });
  }

  if (!author || typeof author !== 'string' || author.trim() === '') {
    errors.push({ field: 'author', message: 'Author is required and must be a non-empty string.' });
  }

  if (!genre || typeof genre !== 'string' || genre.trim() === '') {
    errors.push({ field: 'genre', message: 'Genre is required and must be a non-empty string.' });
  }

  const year = Number(publishedYear);
  const currentYear = new Date().getFullYear();
  if (
    !Number.isInteger(year) ||
    year < 0 ||
    year > currentYear + 1
  ) {
    errors.push({
      field: 'publishedYear',
      message: `Published year must be an integer between 0 and ${currentYear + 1}.`
    });
  }

  // If any errors were collected, throw a single ValidationError with all details
  if (errors.length > 0) {
    return next(new ValidationError('Invalid book data. See details for field-level errors.', errors));
  }

  // Validation passed — attach cleaned data to req.body for the route handler
  req.body.title = title.trim();
  req.body.author = author.trim();
  req.body.genre = genre.trim();
  req.body.publishedYear = year;

  next(); // Proceed to the route handler
}

/**
 * Validate book update payload (PUT /books/:id).
 *
 * Unlike creation, all fields are optional for a partial update. However, if
 * provided, each field must still conform to the same type/format rules.
 *
 * @param {Object} req - Express request object.
 * @param {Object} _res - Express response object (unused).
 * @param {Function} next - Express next middleware function.
 */
function validateUpdateBook(req, _res, next) {
  const updates = req.body;
  const errors = [];

  // Only validate fields that were actually provided in the request body
  if (updates.title !== undefined) {
    if (typeof updates.title !== 'string' || updates.title.trim() === '') {
      errors.push({ field: 'title', message: 'Title must be a non-empty string.' });
    } else {
      updates.title = updates.title.trim();
    }
  }

  if (updates.author !== undefined) {
    if (typeof updates.author !== 'string' || updates.author.trim() === '') {
      errors.push({ field: 'author', message: 'Author must be a non-empty string.' });
    } else {
      updates.author = updates.author.trim();
    }
  }

  if (updates.genre !== undefined) {
    if (typeof updates.genre !== 'string' || updates.genre.trim() === '') {
      errors.push({ field: 'genre', message: 'Genre must be a non-empty string.' });
    } else {
      updates.genre = updates.genre.trim();
    }
  }

  if (updates.publishedYear !== undefined) {
    const year = Number(updates.publishedYear);
    const currentYear = new Date().getFullYear();
    if (!Number.isInteger(year) || year < 0 || year > currentYear + 1) {
      errors.push({
        field: 'publishedYear',
        message: `Published year must be an integer between 0 and ${currentYear + 1}.`
      });
    } else {
      updates.publishedYear = year;
    }
  }

  if (errors.length > 0) {
    return next(new ValidationError('Invalid update data. See details for field-level errors.', errors));
  }

  // Pass cleaned updates back through req.body
  req.body = updates;
  next();
}

module.exports = { validateCreateBook, validateUpdateBook };
