## File 6: `routes/books.js` — Book CRUD Routes

```javascript
/**
 * ============================================================================
 * FILE: routes/books.js
 * DESCRIPTION: RESTful route handlers for book resources.
 *
 * ROUTE CONVENTIONS FOLLOWED:
 *   GET    /books          → List all books (with optional query filters)
 *   GET    /books/:id      → Get a single book by ID
 *   POST   /books          → Create a new book
 *   PUT    /books/:id      → Fully update an existing book
 *   DELETE /books/:id      → Delete a book by ID
 *
 * WHY REST CONVENTIONS?
 *   REST (Representational State Transfer) uses standard HTTP methods to map
 *   to CRUD operations. This makes the API intuitive, cacheable, and compatible
 *   with tools like curl, Postman, and frontend frameworks out of the box.
 *
 * ASYNC/AWAIT PATTERN:
 *   All handlers are async functions even though our data store is synchronous.
 *   This is intentional: it prepares the code for a future migration to an
 *   asynchronous database (e.g., MongoDB, PostgreSQL) without requiring route
 *   rewrites. It also ensures unhandled promise rejections don't crash the server.
 *
 * RESPONSE FORMAT:
 *   Every successful response wraps data in { success: true, data: ... } for
 *   consistency. Errors are caught by the global middleware and returned as
 *   { success: false, error: { message, errorCode } }.
 * ============================================================================
 */

const express = require('express');
const router = express.Router(); // Creates a standalone route handler

// Import our in-memory data store functions
const { getAllBooks, getBookById, createBook, updateBook, deleteBook } = require('../models/books');

// Import validation middleware
const { validateCreateBook, validateUpdateBook } = require('../middleware/validation');

// Import custom error classes
const { NotFoundError } = require('../errors/CustomError');

// ─────────────────────────────────────────────────────────────────────────────
// GET /api/books — List all books with optional filtering
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Retrieve a list of all books, optionally filtered by query parameters.
 *
 * QUERY PARAMETERS (all optional):
 *   - genre:     Filter by exact genre match (e.g., ?genre=Fiction)
 *   - author:    Filter by author name substring (case-insensitive)
 *   - minYear:   Minimum published year (inclusive)
 *   - maxYear:   Maximum published year (inclusive)
 *
 * EXAMPLES:
 *   GET /api/books                          → All books
 *   GET /api/books?genre=Science            → Only Science books
 *   GET /api/books?author=hawking           → Books by authors containing "hawking"
 *   GET /api/books?minYear=1950&maxYear=2000 → Books published 1950–2000
 *
 * curl example:
 *   curl http://localhost:3000/api/books?genre=Fiction
 */
router.get('/', async (req, res) => {
  try {
    // Destructure query parameters with defaults to avoid undefined values
    const { genre, author, minYear, maxYear } = req.query;

    // Start with a full copy of the store
    let result = getAllBooks();

    // Apply filters only if the corresponding query parameter is present
    if (genre) {
      result = result.filter(book => book.genre.toLowerCase() === genre.toLowerCase());
    }

    if (author) {
      const authorLower = author.toLowerCase();
      result = result.filter(book => book.author.toLowerCase().includes(authorLower));
    }

    if (minYear) {
      result = result.filter(book => book.publishedYear >= Number(minYear));
    }

    if (maxYear) {
      result = result.filter(book => book.publishedYear <= Number(maxYear));
    }

    // Return the (possibly filtered) list wrapped in our standard response shape
    res.json({
      success: true,
      count: result.length,
      data: result
    });
  } catch (error) {
    // This should rarely be reached since getAllBooks is synchronous, but we
    // keep the try/catch for consistency with other async handlers.
    next(error);
  }
});

// ─────────────────────────────────────────────────────────────────────────────
// GET /api/books/:id — Get a single book by ID
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Retrieve a single book by its numeric ID.
 *
 * PARAMETER:
 *   - id (URL parameter): The unique identifier of the book.
 *
 * EXAMPLES:
 *   GET /api/books/1
 *   GET /api/books/999  → Returns 404 if not found
 *
 * curl example:
 *   curl http://localhost:3000/api/books/1
 */
router.get('/:id', async (req, res, next) => {
  try {
    const id = Number(req.params.id);

    // Validate that the ID is a positive integer
    if (!Number.isInteger(id) || id < 1) {
      return next(new NotFoundError('Book'));
    }

    const book = getBookById(id);

    // If not found, throw a NotFoundError so the global handler formats the response
    if (!book) {
      return next(new NotFoundError('Book'));
    }

    res.json({
      success: true,
      data: book
    });
  } catch (error) {
    next(error); // Pass to global error handler
  }
});

// ─────────────────────────────────────────────────────────────────────────────
// POST /api/books — Create a new book
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Create a new book record.
 *
 * REQUEST BODY (JSON):
 *   {
 *     "title": "String",        // Required
 *     "author": "String",       // Required
 *     "genre": "String",        // Required
 *     "publishedYear": 2023     // Required, integer
 *   }
 *
 * The server automatically assigns an `id` and `createdAt` timestamp.
 *
 * EXAMPLES:
 *   curl -X POST http://localhost:3000/api/books \
 *        -H "Content-Type: application/json" \
 *        -d '{"title":"1984","author":"George Orwell","genre":"Fiction","publishedYear":1949}'
 */
router.post('/', validateCreateBook, async (req, res, next) => {
  try {
    // Validation middleware has already cleaned req.body; pass it directly to the store
    const newBook = createBook(req.body);

    // 201 Created is the semantically correct status for a newly created resource
    res.status(201).json({
      success: true,
      data: newBook
    });
  } catch (error) {
    next(error);
  }
});

// ─────────────────────────────────────────────────────────────────────────────
// PUT /api/books/:id — Fully update an existing book
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Replace all fields of an existing book with the provided data.
 *
 * This is a FULL update (not patch). Every field in the request body will
 * overwrite the corresponding field in the stored record. Fields omitted from
 * the body are NOT preserved — use this only when you intend to replace the
 * entire resource.
 *
 * REQUEST BODY (JSON):
 *   {
 *     "title": "String",
 *     "author": "String",
 *     "genre": "String",
 *     "publishedYear": 2023
 *   }
 *
 * EXAMPLES:
 *   curl -X PUT http://localhost:3000/api/books/1 \
 *        -H "Content-Type: application/json" \
 *        -d '{"title":"The Great Gatsby (Updated)","author":"F. Scott Fitzgerald","genre":"Classic","publishedYear":1925}'
 */
router.put('/:id', validateUpdateBook, async (req, res, next) => {
  try {
    const id = Number(req.params.id);

    if (!Number.isInteger(id) || id < 1) {
      return next(new NotFoundError('Book'));
    }

    // updateBook returns undefined if the book doesn't exist
    const updatedBook = updateBook(id, req.body);

    if (!updatedBook) {
      return next(new NotFoundError('Book'));
    }

    res.json({
      success: true,
      message: 'Book updated successfully.',
      data: updatedBook
    });
  } catch (error) {
    next(error);
  }
});

// ─────────────────────────────────────────────────────────────────────────────
// DELETE /api/books/:id — Delete a book by ID
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Permanently remove a book from the store.
 *
 * This operation is irreversible. Consider adding soft-delete (setting an
 * `deletedAt` timestamp) in production instead of hard deletion.
 *
 * EXAMPLES:
 *   curl -X DELETE http://localhost:3000/api/books/1
 */
router.delete('/:id', async (req, res, next) => {
  try {
    const id = Number(req.params.id);

    if (!Number.isInteger(id) || id < 1) {
      return next(new NotFoundError('Book'));
    }

    const deleted = deleteBook(id);

    if (!deleted) {
      return next(new NotFoundError('Book'));
    }

    // 204 No Content is standard for successful deletions with no response body
    res.status(204).send();
  } catch (error) {
    next(error);
  }
});

module.exports = router;
```

