```javascript
/**
 * ============================================================================
 * FILE: routes/stats.js
 * DESCRIPTION: Read-only endpoint returning aggregate statistics about the
 *              book collection. Useful for dashboards, monitoring, or API
 *              discovery.
 *
 * DESIGN RATIONALE:
 *   - Stats are read-only (GET only), so no validation middleware is needed.
 *   - We return computed metrics rather than raw counts to save clients from
 *     having to process the full dataset themselves.
 *   - The endpoint is mounted at /api/stats to keep it separate from resource
 *     routes, following REST best practices where stats/metrics are typically
 *     top-level resources.
 * ============================================================================
 */

const express = require('express');
const router = express.Router();
const { getStats } = require('../models/books');

/**
 * GET /api/stats — Return aggregate statistics.
 *
 * RESPONSE SHAPE:
 *   {
 *     "success": true,
 *     "data": {
 *       "totalBooks": 3,
 *       "averagePublishedYear": 1924,
 *       "genres": {
 *         "Fiction": 2,
 *         "Science": 1
 *       }
 *     }
 *   }
 *
 * curl example:
 *   curl http://localhost:3000/api/stats
 */
router.get('/', async (_req, res, next) => {
  try {
    const stats = getStats();

    res.json({
      success: true,
      data: stats
    });
  } catch (error) {
    next(error);
  }
});

module.exports = router;
```

