## Arquivo 2: `src/models/book.js`

```javascript
/**
 * ============================================================
 * MODEL: Livro (Book)
 * ============================================================
 *
 * Este arquivo define a estrutura de dados para o modelo "Livro"
 * e fornece funções utilitárias para manipulação do array em memória.
 *
 * POR QUE USAR UM ARRAY EM MEMÓRIA?
 * ---------------------------------
 * Para fins educacionais, um array em memória é suficiente porque:
 *   1. Não requer configuração de banco de dados (SQL/NoSQL).
 *   2. Permite focar nos conceitos de REST, rotas e middleware.
 *   3. Operações são O(1) para push/pop e O(n) para busca — aceitável
 *      para volumes pequenos de dados em exemplos.
 *
 * PARA PRODUÇÃO, substitua estas funções por chamadas a um banco
 * de dados real (MongoDB, PostgreSQL, etc.) mantendo a mesma interface.
 * ============================================================
 */

/**
 * Array que armazena todos os livros em memória.
 *
 * Escolha: Usamos um array simples porque:
 *   - A ordem de inserção é preservada (diferente de objetos).
 *   - Permite iteração fácil para listagem e estatísticas.
 *   - Cada elemento é um objeto com propriedades tipadas, facilitando
 *     a validação e documentação JSDoc.
 *
 * @type {Array<Book>}
 */
const books = [];

/**
 * Gera um ID único simples baseado em timestamp + contador.
 *
 * Escolha: Em vez de UUIDs complexos (que exigiriam uma biblioteca
 * externa), usamos um contador incremental com prefixo numérico.
 * Isso é suficiente para exemplos e evita dependências extras.
 *
 * @returns {number} ID único do livro.
 */
let nextId = 1;

function generateId() {
  return nextId++;
}

/**
 * Encontra um livro pelo seu ID.
 *
 * Escolha: Usamos Array.find() que retorna o primeiro elemento que
 * satisfaz a condição, ou undefined se não encontrar. É mais legível
 * que um loop for tradicional e segue convenções modernas de JavaScript.
 *
 * @param {number} id - O ID do livro a ser encontrado.
 * @returns {Book|undefined} O livro encontrado ou undefined.
 */
function findById(id) {
  return books.find((book) => book.id === id);
}

/**
 * Cria um novo livro e o adiciona ao array.
 *
 * Escolha: Retornamos o livro criado (com ID atribuído) para que a
 * rota POST possa responder com o recurso criado no corpo da resposta,
 * seguindo a convenção REST de retornar 201 Created + representação do recurso.
 *
 * @param {BookData} bookData - Dados do novo livro.
 * @returns {Book} O livro criado com ID atribuído.
 */
function create(bookData) {
  const newBook = {
    id: generateId(),
    title: bookData.title,
    author: bookData.author,
    year: bookData.year,
    genre: bookData.genre,
    createdAt: new Date().toISOString(), // ISO 8601 para consistência de fuso horário
    updatedAt: new Date().toISOString(),
  };

  books.push(newBook);
  return newBook;
}

/**
 * Atualiza um livro existente pelo ID.
 *
 * Escolha: Usamos Object.assign() para mesclar os campos fornecidos
 * com o objeto existente, preservando campos não enviados (partial update).
 * Isso permite que o cliente envie apenas os campos que deseja alterar.
 *
 * @param {number} id - O ID do livro a ser atualizado.
 * @param {BookData} updates - Os campos a serem atualizados.
 * @returns {Book|undefined} O livro atualizado ou undefined se não encontrado.
 */
function updateById(id, updates) {
  const book = findById(id);
  if (!book) return undefined;

  // Atualiza apenas os campos fornecidos (partial update)
  Object.assign(book, updates, { updatedAt: new Date().toISOString() });
  return book;
}

/**
 * Remove um livro do array pelo ID.
 *
 * Escolha: Usamos filter() para criar um novo array sem o elemento removido.
 * Isso é imutável e evita efeitos colaterais indesejados em iterações.
 *
 * @param {number} id - O ID do livro a ser removido.
 * @returns {boolean} True se o livro foi encontrado e removido, false caso contrário.
 */
function deleteById(id) {
  const index = books.findIndex((book) => book.id === id);
  if (index === -1) return false;

  books.splice(index, 1);
  return true;
}

/**
 * Calcula estatísticas agregadas sobre os livros.
 *
 * Escolha: Retornamos um objeto com métricas úteis que demonstram
 * como processar dados em lote — algo comum em APIs reais.
 *
 * @returns {Stats} Objeto contendo as estatísticas dos livros.
 */
function getStatistics() {
  const total = books.length;

  // Agrupamento por gênero usando reduce — padrão eficiente para agregação
  const byGenre = books.reduce((acc, book) => {
    acc[book.genre] = (acc[book.genre] || 0) + 1;
    return acc;
  }, {});

  // Ano mais recente e mais antigo entre os livros
  const years = books.map((b) => b.year).filter((y) => y != null);
  const oldestYear = years.length ? Math.min(...years) : null;
  const newestYear = years.length ? Math.max(...years) : null;

  // Autor com mais livros (mais prolífico)
  const byAuthor = books.reduce((acc, book) => {
    acc[book.author] = (acc[book.author] || 0) + 1;
    return acc;
  }, {});

  let mostProlificAuthor = null;
  let maxBooks = 0;
  for (const [author, count] of Object.entries(byAuthor)) {
    if (count > maxBooks) {
      maxBooks = count;
      mostProlificAuthor = author;
    }
  }

  return {
    total,
    byGenre,
    oldestYear,
    newestYear,
    mostProlificAuthor: mostProlificAuthor
      ? { name: mostProlificAuthor, bookCount: maxBooks }
      : null,
  };
}

// ============================================================
// TIPOS (JSDoc) para documentação e IntelliSense
// ============================================================

/**
 * @typedef {Object} BookData
 * @property {string} title - Título do livro (obrigatório).
 * @property {string} author - Autor do livro (obrigatório).
 * @property {number} [year] - Ano de publicação (opcional, numérico).
 * @property {string} [genre] - Gênero literário (opcional).
 */

/**
 * @typedef {Object} Book
 * @property {number} id - Identificador único do livro.
 * @property {string} title - Título do livro.
 * @property {string} author - Autor do livro.
 * @property {number|null} [year] - Ano de publicação.
 * @property {string|null} [genre] - Gênero literário.
 * @property {string} createdAt - Data de criação (ISO 8601).
 * @property {string} updatedAt - Data da última atualização (ISO 8601).
 */

/**
 * @typedef {Object} Stats
 * @property {number} total - Total de livros cadastrados.
 * @property {Object.<string, number>} byGenre - Contagem por gênero.
 * @property {number|null} oldestYear - Mais antigo entre os anos publicados.
 * @property {number|null} newestYear - Mais recente entre os anos publicados.
 * @property {{name: string, bookCount: number}|null} mostProlificAuthor - Autor mais prolífico.
 */

// ============================================================
// EXPORTS — Módulo CommonJS (padrão Node.js)
// ============================================================
module.exports = {
  books,
  findById,
  create,
  updateById,
  deleteById,
  getStatistics,
};
```

