## Arquivo 3: `src/middleware/errorHandler.js`

```javascript
/**
 * ============================================================
 * MIDDLEWARE: Tratamento de Erros
 * ============================================================
 *
 * Este middleware implementa um sistema centralizado de tratamento
 * de erros com classes personalizadas. Em Express, middlewares de erro
 * têm 4 parâmetros (err, req, res, next) — o framework os identifica
 * automaticamente por diferença de assinatura.
 *
 * POR QUE CLASSES DE ERRO PERSONALIZADAS?
 * ---------------------------------------
 * Classes como NotFoundError e ValidationError permitem:
 *   1. Identificar o tipo de erro programaticamente (instanceof).
 *   2. Incluir campos extras (como campo inválido e mensagem específica).
 *   3. Manter consistência nas respostas de erro da API.
 *
 * A convenção REST para códigos HTTP:
 *   - 400 Bad Request: Erro de validação (dados inválidos).
 *   - 404 Not Found: Recurso não existe.
 *   - 500 Internal Server Error: Erro inesperado do servidor.
 * ============================================================
 */

/**
 * Classe base para erros da API.
 *
 * Estende Error nativo para manter compatibilidade com stack traces,
 * mas adiciona statusCode e isOperational (erro esperado vs. bug).
 */
class ApiError extends Error {
  /**
   * @param {string} message - Mensagem de erro descritiva.
   * @param {number} statusCode - Código HTTP da resposta de erro.
   */
  constructor(message, statusCode) {
    super(message);
    this.statusCode = statusCode;
    // Erros operacionais são esperados (ex: recurso não encontrado),
    // diferentemente de bugs do servidor que seriam isOperational = false.
    this.isOperational = true;
    Error.captureStackTrace(this, this.constructor);
  }
}

/**
 * Erro 404 — Recurso não encontrado.
 * Usado quando um ID inválido é fornecido ou o recurso não existe.
 */
class NotFoundError extends ApiError {
  /**
   * @param {string} resource - Nome do recurso (ex: "Livro").
   * @param {*} id - O ID que não foi encontrado.
   */
  constructor(resource = "Recurso", id) {
    super(`${resource} com ID ${id} não encontrado`, 404);
    this.resource = resource;
    this.id = id;
  }
}

/**
 * Erro 400 — Dados de entrada inválidos.
 * Usado para validação de campos obrigatórios, tipos incorretos, etc.
 */
class ValidationError extends ApiError {
  /**
   * @param {string} message - Mensagem de erro descritiva.
   * @param {Object} [fields] - Campos inválidos e suas mensagens.
   */
  constructor(message, fields = {}) {
    super(message, 400);
    this.fields = fields;
  }
}

/**
 * Middleware principal de tratamento de erros.
 *
 * Escolha: Colocamos este middleware COMO O ÚLTIMO dos middlewares
 * do Express. Ele captura erros lançados por rotas e middlewares
 * anteriores, garantindo que nenhum erro escape sem resposta.
 *
 * Em produção, aqui você também registraria o erro em um logger
 * (Winston, Pino, etc.) antes de enviar a resposta.
 *
 * @param {Error} err - O erro capturado.
 * @param {import('express').Request} req - Objeto de requisição Express.
 * @param {import('express').Response} res - Objeto de resposta Express.
 * @param {import('express').NextFunction} next - Função next do Express.
 */
function errorHandler(err, req, res, next) {
  // Se o erro for da nossa API (ApiError), usamos seu statusCode e mensagem.
  if (err instanceof ApiError) {
    return res.status(err.statusCode).json({
      success: false,
      error: {
        message: err.message,
        ...(err.fields && { fields: err.fields }), // Inclui campos inválidos se houver
        ...(err.resource && { resource: err.resource }),
      },
    });
  }

  // Erros não operacionais (bugs) — logamos e retornamos 500 genérico.
  // Em produção, NÃO exponha detalhes do erro para o cliente por segurança.
  console.error("❌ Erro não tratado:", err);
  return res.status(500).json({
    success: false,
    error: {
      message: "Erro interno do servidor. Tente novamente mais tarde.",
    },
  });
}

// ============================================================
// EXPORTS
// ============================================================
module.exports = {
  ApiError,
  NotFoundError,
  ValidationError,
  errorHandler,
};
```

