## Arquivo 4: `src/middleware/validator.js`

```javascript
/**
 * ============================================================
 * MIDDLEWARE: Validação de Entrada
 * ============================================================
 *
 * Este middleware valida os dados enviados pelo cliente antes que
 * cheguem às rotas. A validação antecipada evita lógica duplicada
 * dentro dos handlers e garante consistência nos dados armazenados.
 *
 * POR QUE VALIDAR NO MIDDLEWARE E NÃO NO HANDLER?
 * ------------------------------------------------
 * Separação de responsabilidades (Single Responsibility Principle):
 *   - O middleware cuida da validação (entrada).
 *   - O handler cuida da lógica de negócio (processamento).
 * Isso torna o código mais testável e reutilizável.
 * ============================================================
 */

const { ValidationError } = require("./errorHandler");

/**
 * Valida os dados de criação/atualização de um livro.
 *
 * Regras de validação:
 *   - title: obrigatório, string não vazia.
 *   - author: obrigatório, string não vazia.
 *   - year: se fornecido, deve ser número inteiro positivo.
 *   - genre: se fornecido, deve ser string não vazia.
 *
 * @param {import('express').Request} req - Objeto de requisição Express.
 * @param {import('express').Response} res - Objeto de resposta Express.
 * @param {import('express').NextFunction} next - Função next do Express.
 * @throws {ValidationError} Se a validação falhar.
 */
function validateBook(req, res, next) {
  const { title, author, year, genre } = req.body;

  const fields = {}; // Acumulador de erros por campo

  // Validação do título
  if (!title || typeof title !== "string" || title.trim() === "") {
    fields.title = "O título é obrigatório e deve ser uma string não vazia.";
  }

  // Validação do autor
  if (!author || typeof author !== "string" || author.trim() === "") {
    fields.author = "O autor é obrigatório e deve ser uma string não vazia.";
  }

  // Validação opcional do ano (se fornecido)
  if (year !== undefined && year !== null) {
    const numYear = Number(year);
    if (!Number.isInteger(numYear) || numYear <= 0 || numYear > new Date().getFullYear() + 1) {
      fields.year = `O ano deve ser um número inteiro entre 1 e ${new Date().getFullYear() + 1}.`;
    }
  }

  // Validação opcional do gênero (se fornecido)
  if (genre !== undefined && genre !== null) {
    if (typeof genre !== "string" || genre.trim() === "") {
      fields.genre = "O gênero deve ser uma string não vazia.";
    }
  }

  // Se houver erros, lançamos ValidationError com os campos problemáticos.
  // O middleware de erro tratará a resposta 400 automaticamente.
  if (Object.keys(fields).length > 0) {
    return next(new ValidationError("Dados de entrada inválidos.", fields));
  }

  // Se tudo estiver válido, prosseguimos para o próximo middleware/handler.
  next();
}

// ============================================================
// EXPORTS
// ============================================================
module.exports = { validateBook };
```

