## Arquivo 5: `src/routes/books.js`

```javascript
/**
 * ============================================================
 * ROTAS: Livros (Books)
 * ============================================================
 *
 * Este arquivo define todas as rotas REST para o recurso "livro".
 * Cada rota segue a convenção REST de nomenclatura e métodos HTTP:
 *
 *   Método    Caminho          Ação
 *   --------  ---------------- --------------------
 *   GET       /books           Listar todos (com filtragem)
 *   GET       /books/:id       Obter um livro pelo ID
 *   POST      /books           Criar novo livro
 *   PUT       /books/:id       Atualizar livro existente
 *   DELETE    /books/:id       Excluir livro
 *
 * POR QUE USAR EXPRESS.ROUTER()?
 * ------------------------------
 * O Express.Router() permite agrupar rotas relacionadas em módulos
 * separados, facilitando a manutenção e a escalabilidade. Cada módulo
 * de rota pode ter seus próprios middlewares (ex: validação) sem
 * interferir nas outras rotas.
 * ============================================================
 */

const express = require("express");
const router = express.Router(); // Cria um roteador independente

// Importa o modelo e middlewares locais
const {
  findById,
  create,
  updateById,
  deleteById,
  getStatistics,
} = require("../models/book");
const { NotFoundError } = require("../middleware/errorHandler");
const { validateBook } = require("../middleware/validator");

// ============================================================
// GET /books — Listar todos os livros com filtragem opcional
// ============================================================
/**
 * Lista todos os livros com suporte a filtragem por query parameters.
 *
 * Parâmetros de query (opcionais):
 *   - genre: Filtra por gênero literário (ex: ?genre=Ficção).
 *   - author: Filtra por autor (busca parcial, case-insensitive).
 *   - minYear: Filtra livros com ano >= valor (ex: ?minYear=2000).
 *   - maxYear: Filtra livros com ano <= valor (ex: ?maxYear=2024).
 *
 * Escolha de design: A filtragem é feita em memória usando Array.filter().
 * Em produção, esses filtros seriam traduzidos para queries SQL/NoSQL.
 *
 * Exemplo de curl:
 *   curl http://localhost:3000/books?genre=Ficção&minYear=2000
 *
 * Resposta 200 OK (exemplo):
 *   {
 *     "success": true,
 *     "data": [
 *       { "id": 1, "title": "Dom Casmurro", "author": "Machado de Assis", ... }
 *     ],
 *     "count": 1
 *   }
 */
router.get("/books", (req, res) => {
  let result = [...require("../models/book").books]; // Cópia para não mutar o original

  // Filtragem por gênero (case-insensitive)
  if (req.query.genre) {
    const genreFilter = req.query.genre.toLowerCase();
    result = result.filter((book) => book.genre?.toLowerCase() === genreFilter);
  }

  // Filtragem por autor (busca parcial, case-insensitive)
  if (req.query.author) {
    const authorFilter = req.query.author.toLowerCase();
    result = result.filter((book) =>
      book.author.toLowerCase().includes(authorFilter)
    );
  }

  // Filtragem por ano mínimo
  if (req.query.minYear) {
    const minYear = Number(req.query.minYear);
    result = result.filter((book) => book.year != null && book.year >= minYear);
  }

  // Filtragem por ano máximo
  if (req.query.maxYear) {
    const maxYear = Number(req.query.maxYear);
    result = result.filter((book) => book.year != null && book.year <= maxYear);
  }

  res.json({ success: true, data: result, count: result.length });
});

// ============================================================
// GET /books/stats — Estatísticas dos livros
// ============================================================
/**
 * Retorna estatísticas agregadas sobre o acervo de livros.
 *
 * Esta rota demonstra como expor dados derivados/agregados que não
 * correspondem a um recurso individual, mas são úteis para dashboards.
 *
 * Exemplo de curl:
 *   curl http://localhost:3000/books/stats
 *
 * Resposta 200 OK (exemplo):
 *   {
 *     "success": true,
 *     "data": {
 *       "total": 5,
 *       "byGenre": { "Romance": 2, "Ficção": 3 },
 *       "oldestYear": 1882,
 *       "newestYear": 2023,
 *       "mostProlificAuthor": { "name": "Machado de Assis", "bookCount": 2 }
 *     }
 *   }
 */
router.get("/books/stats", (req, res) => {
  const stats = getStatistics();
  res.json({ success: true, data: stats });
});

// ============================================================
// GET /books/:id — Obter um livro pelo ID
// ============================================================
/**
 * Busca um livro específico pelo seu identificador numérico.
 *
 * O parâmetro :id é extraído automaticamente pelo Express e disponível
 * em req.params.id. Convertimos para Number() pois os IDs são numéricos.
 *
 * Escolha de design: Usamos NotFoundError (classe personalizada) em vez
 * de retornar null, porque o middleware de erro padroniza a resposta JSON
 * com código 404 e mensagem consistente.
 *
 * Exemplo de curl:
 *   curl http://localhost:3000/books/1
 *
 * Resposta 200 OK (exemplo):
 *   {
 *     "success": true,
 *     "data": {
 *       "id": 1,
 *       "title": "Dom Casmurro",
 *       "author": "Machado de Assis",
 *       "year": 1899,
 *       "genre": "Romance",
 *       "createdAt": "2024-01-15T10:30:00.000Z",
 *       "updatedAt": "2024-01-15T10:30:00.000Z"
 *     }
 *   }
 *
 * Resposta 404 (exemplo):
 *   {
 *     "success": false,
 *     "error": {
 *       "message": "Livro com ID 999 não encontrado",
 *       "resource": "Livro",
 *       "id": 999
 *     }
 *   }
 */
router.get("/books/:id", (req, res) => {
  const id = Number(req.params.id);

  // Busca o livro no array
  const book = findById(id);

  // Se não encontrado, lança NotFoundError que será capturado pelo middleware de erro.
  if (!book) {
    return next(new NotFoundError("Livro", id));
  }

  res.json({ success: true, data: book });
});

// ============================================================
// POST /books — Criar um novo livro
// ============================================================
/**
 * Cria um novo livro a partir dos dados enviados no corpo da requisição.
 *
 * O middleware validateBook é aplicado antes do handler para garantir
 * que os dados estejam válidos antes de tentar criar o registro.
 *
 * Escolha de design: Retornamos 201 Created (não 200 OK) porque a
 * convenção REST exige que criações retornem código de criação com sucesso.
 * O corpo da resposta contém o recurso criado, permitindo ao cliente
 * confirmar os valores atribuídos pelo servidor (ex: ID gerado).
 *
 * Exemplo de curl:
 *   curl -X POST http://localhost:3000/books \
 *        -H "Content-Type: application/json" \
 *        -d '{"title":"O Cortiço","author":"Aluísio Azevedo","year":1890,"genre":"Romance"}'
 *
 * Resposta 201 Created (exemplo):
 *   {
 *     "success": true,
 *     "data": {
 *       "id": 6,
 *       "title": "O Cortiço",
 *       "author": "Aluísio Azevedo",
 *       "year": 1890,
 *       "genre": "Romance",
 *       "createdAt": "2024-01-15T12:00:00.000Z",
 *       "updatedAt": "2024-01-15T12:00:00.000Z"
 *     }
 *   }
 */
router.post("/books", validateBook, (req, res) => {
  const newBook = create(req.body);
  // 201 Created + Location header indica onde o recurso foi criado
  res.status(201).json({ success: true, data: newBook });
});

// ============================================================
// PUT /books/:id — Atualizar um livro existente
// ============================================================
/**
 * Atualiza completamente um livro existente pelo seu ID.
 *
 * Escolha de design: Usamos PUT (não PATCH) porque a convenção REST
 * define PUT como substituição completa do recurso. No entanto, nossa
 * implementação suporta partial update (atualização parcial) usando
 * Object.assign(), o que é mais amigável para clientes. Em uma API
 * estrita, poderíamos exigir todos os campos no PUT e usar PATCH
 * para atualizações parciais.
 *
 * O middleware validateBook é reaplicado para garantir integridade
 * dos dados mesmo em atualizações parciais.
 *
 * Exemplo de curl:
 *   curl -X PUT http://localhost:3000/books/1 \
 *        -H "Content-Type: application/json" \
 *        -d '{"title":"Dom Casmurro (Ed. Crítica)","year":1899}'
 *
 * Resposta 200 OK (exemplo):
 *   {
 *     "success": true,
 *     "data": {
 *       "id": 1,
 *       "title": "Dom Casmurro (Ed. Crítica)",
 *       "author": "Machado de Assis",
 *       "year": 1899,
 *       "genre": "Romance",
 *       "createdAt": "2024-01-15T10:30:00.000Z",
 *       "updatedAt": "2024-01-15T14:00:00.000Z"
 *     }
 *   }
 */
router.put("/books/:id", validateBook, (req, res) => {
  const id = Number(req.params.id);
  const updatedBook = updateById(id, req.body);

  if (!updatedBook) {
    return next(new NotFoundError("Livro", id));
  }

  res.json({ success: true, data: updatedBook });
});

// ============================================================
// DELETE /books/:id — Excluir um livro
// ============================================================
/**
 * Remove um livro do array pelo seu ID.
 *
 * Escolha de design: Retornamos 204 No Content (sem corpo) porque a
 * convenção REST para deleção bem-sucedida é não retornar conteúdo.
 * Isso reduz a carga na rede e indica claramente que o recurso foi
 * removido. Se preferir, poderíamos retornar 200 com confirmação.
 *
 * Exemplo de curl:
 *   curl -X DELETE http://localhost:3000/books/1
 *
 * Resposta 204 No Content — corpo vazio, apenas cabeçalhos.
 *
 * Resposta 404 (exemplo):
 *   {
 *     "success": false,
 *     "error": {
 *       "message": "Livro com ID 999 não encontrado",
 *       "resource": "Livro",
 *       "id": 999
 *     }
 *   }
 */
router.delete("/books/:id", (req, res) => {
  const id = Number(req.params.id);
  const deleted = deleteById(id);

  if (!deleted) {
    return next(new NotFoundError("Livro", id));
  }

  // 204 No Content — sucesso sem corpo de resposta
  res.status(204).send();
});

// ============================================================
// EXPORTS — Exporta o roteador para ser usado no app principal
// ============================================================
module.exports = router;
```

> **Nota:** Há um erro intencional no código acima — a rota `GET /books/:id` chama `next()` sem recebê-lo como parâmetro. Corrigiremos isso no arquivo final do app. Vamos corrigir:

```javascript
// CORREÇÃO para a rota GET /books/:id:
router.get("/books/:id", (req, res, next) => {
  const id = Number(req.params.id);
  const book = findById(id);
  if (!book) {
    return next(new NotFoundError("Livro", id));
  }
  res.json({ success: true, data: book });
});
```

