## Arquivo 6: `src/app.js`

```javascript
/**
 * ============================================================
 * APP PRINCIPAL: Configuração do Express
 * ============================================================
 *
 * Este arquivo configura a aplicação Express com todos os middlewares
 * necessários. A ordem dos middlewares é crítica no Express:
 *   1. Middlewares globais (body-parser, CORS, etc.)
 *   2. Rotas da API
 *   3. Middleware de tratamento de erros (SEMPRE por último)
 *
 * POR QUE USAR async/await?
 * -------------------------
 * Async/await torna o código assíncrono mais legível ao evitar
 * "callback hell" e encadeamentos complexos de promessas (.then()).
 * Embora esta API não use operações assíncronas (array em memória),
 * a estrutura está preparada para migração a bancos de dados que
 * usam promessas/async.
 * ============================================================
 */

const express = require("express");
const bookRoutes = require("./routes/books");
const { errorHandler } = require("./middleware/errorHandler");

const app = express();

// ============================================================
// MIDDLEWARES GLOBAIS (ordem importa!)
// ============================================================

/**
 * body-parser: Parseia o corpo das requisições JSON.
 *
 * Escolha: express.json() converte automaticamente o corpo de
 * requisições com Content-Type: application/json em um objeto JS,
 * tornando req.body acessível nos handlers.
 */
app.use(express.json());

/**
 * CORS (Cross-Origin Resource Sharing): Permite requisições de
 * diferentes origens (útil para desenvolvimento frontend).
 *
 * Em produção, restrinja o origin a domínios específicos por segurança.
 */
app.use((req, res, next) => {
  res.header("Access-Control-Allow-Origin", "*");
  res.header("Access-Control-Allow-Headers", "Origin, X-Requested-With, Content-Type, Accept");
  res.header("Access-Control-Allow-Methods", "GET, POST, PUT, DELETE, OPTIONS");

  // Responde imediatamente a requisições OPTIONS (preflight CORS)
  if (req.method === "OPTIONS") {
    return res.sendStatus(200);
  }
  next();
});

/**
 * Logger simples de requisições — útil para depuração.
 * Mostra método, URL e timestamp de cada requisição.
 */
app.use((req, res, next) => {
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.url}`);
  next();
});

// ============================================================
// ROTAS DA API
// ============================================================

/**
 * Registra as rotas de livros. O prefixo "/api/v1" é uma convenção
 * comum para versionamento de APIs, permitindo evolução futura
 * sem quebrar clientes existentes.
 */
app.use("/api/v1", bookRoutes);

// ============================================================
// ROTA PARA RAIZ — Documentação rápida
// ============================================================
app.get("/", (req, res) => {
  res.json({
    success: true,
    message: "API de Livros — Exemplo Educacional",
    endpoints: {
      docs: "GET /api/v1/books/stats",
      list: "GET /api/v1/books",
      create: "POST /api/v1/books",
      update: "PUT /api/v1/books/:id",
      remove: "DELETE /api/v1/books/:id",
    },
  });
});

// ============================================================
// ROTA 404 — Captura requisições para rotas inexistentes
// ============================================================
app.use((req, res) => {
  res.status(404).json({
    success: false,
    error: { message: `Rota ${req.method} ${req.url} não encontrada` },
  });
});

// ============================================================
// MIDDLEWARE DE ERRO — SEMPRE O ÚLTIMO!
// ============================================================
app.use(errorHandler);

module.exports = app;
```

