## Arquivo 7: `src/server.js`

```javascript
/**
 * ============================================================
 * SERVER: Ponto de Entrada da Aplicação
 * ============================================================
 *
 * Este arquivo inicia o servidor HTTP e configura a porta de escuta.
 * A constante PORT pode ser sobrescrita por variável de ambiente,
 * uma prática recomendada para compatibilidade com plataformas
 * de hospedagem (Heroku, Railway, etc.).
 * ============================================================
 */

const app = require("./app");

// Porta padrão 3000, ou usa a variável de ambiente PORT se definida.
// Isso é uma convenção do Twelve-Factor App para configuração.
const PORT = process.env.PORT || 3000;

const server = app.listen(PORT, () => {
  console.log(`✅ Servidor rodando em http://localhost:${PORT}`);
  console.log(`📚 API de Livros — Exemplo Educacional`);
  console.log(`\nEndpoints disponíveis:`);
  console.log(`  GET    http://localhost:${PORT}/api/v1/books          — Listar livros`);
  console.log(`  GET    http://localhost:${PORT}/api/v1/books/stats    — Estatísticas`);
  console.log(`  POST   http://localhost:${PORT}/api/v1/books          — Criar livro`);
  console.log(`  PUT    http://localhost:${PORT}/api/v1/books/:id      — Atualizar livro`);
  console.log(`  DELETE http://localhost:${PORT}/api/v1/books/:id      — Excluir livro`);
});

// Tratamento de erros não capturados no processo Node.js.
// Isso evita que o servidor "silenciosamente" falhe em produção.
process.on("uncaughtException", (err) => {
  console.error("💥 Uncaught Exception:", err);
  process.exit(1); // Sai com código de erro para que o gerenciador reinicie o processo
});

process.on("unhandledRejection", (reason, promise) => {
  console.error("💥 Unhandled Rejection:", reason);
  // Não saímos do processo aqui — apenas logamos, pois pode haver recuperação.
});

module.exports = server;
```

